"use client"

import React from "react"
import type { SVGProps } from "react"
import { TrayIcon, WarningIcon, type Icon as PhosphorIcon } from "@phosphor-icons/react"

import { EmptyState, type EmptyStateIcon } from "@sb-components/composites/feedback/EmptyState/EmptyState"
// The ATOM `Button`, NOT the `_legacy` version:
// `AsyncContent` sits in the closure of the `CourseContents` screen, and that screen
// is FORBIDDEN from touching `_legacy` — an import at the composite tier would drag the
// whole dead branch back into the screen.
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"

/**
 * STATE SCOPE: `AsyncContent` is a state-transition scaffold — its own asset is BRANCH
 * SELECTION (error → loading → empty → content), not the shape of each message. Every story
 * is one branch, and the empty/error branches take only the minimal shape to prove the switch
 * runs; the full set of message variants lives in `AsyncContentEmpty` / `AsyncContentError`,
 * not repeated here.
 */

// ─────────────────────────────────────────────────────────────────────────────
// Shared message-frame plumbing (.Empty / .Error)
// ─────────────────────────────────────────────────────────────────────────────

/** Shared props of the two MESSAGE frames `.Empty` / `.Error`. */
interface MessageProps {
    /** Main line (already translated). `string`, not `ReactNode` — the frame forwards it into `EmptyState`, which renders it (COMPOSITE-8). */
    title: string
    /** Secondary line under the title (already translated). Optional. `string` for the same reason as {@link MessageProps.title}. */
    description?: string
    /**
     * Override the default glyph — takes a **COMPONENT REF** (`icon={TrayIcon}`), NOT
     * JSX. §14b: the caller (especially a SCREEN) must not hold a pre-built node. The
     * frame owns the scale + `weight="duotone"` (§4/§5) so every empty/error in the
     * system speaks with the same glyph voice — the caller only picks "which glyph",
     * not "what it looks like".
     */
    icon?: PhosphorIcon
    /**
     * General ACTION slot below the description — a COMPONENT reference (COMPOSITE-8),
     * never a built node (a `Button`, a two-button cluster…): forwarded straight into
     * `EmptyState`'s own `action` slot, which calls it and forwards `isSkeleton`. WINS
     * over the `onRetry`/`retryLabel` shorthand when both are passed.
     */
    action?: ComponentTypeWithSkeleton
    /** Shorthand: retry handler — only renders a button when PAIRED with `retryLabel`. */
    onRetry?: () => void
    /** Shorthand: the (already translated) label of the retry button — required for the button to appear. `string`, not `ReactNode` (COMPOSITE-8). */
    retryLabel?: string
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * Force `weight="duotone"` on the message frame's glyph — the FRAME owns
 * how the glyph looks, the caller only picks which glyph.
 */
const withDuotone = (Icon: PhosphorIcon): EmptyStateIcon => {
    const Glyph = (props: SVGProps<SVGSVGElement>) => <Icon {...props} weight="duotone" />
    return Glyph
}

/**
 * Resolve the `action` slot's COMPONENT: a free-form `action` component reference
 * wins; otherwise the `onRetry` + `retryLabel` pair is wrapped into a component
 * rendering a secondary size-sm `Button`. Returns a component reference (never a
 * built node, COMPOSITE-8) — `EmptyState` calls it itself, forwarding `isSkeleton`.
 */
const composeAction = ({ action, onRetry, retryLabel }: MessageProps): ComponentTypeWithSkeleton | undefined => {
    if (action) {
        return action
    }
    if (onRetry && retryLabel) {
        return () => (
            <Button
                variant="tertiary"
                size="sm"
                onPress={onRetry}
                label={retryLabel}
            />
        )
    }
    return undefined
}

// ─────────────────────────────────────────────────────────────────────────────
// .Base — the 4-branch state switch (was `AsyncContent`)
// ─────────────────────────────────────────────────────────────────────────────

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "AsyncContent" } as const

/** Props for {@link AsyncContent}. */
export interface AsyncContentBaseProps {
    /**
     * True while the FIRST load is running (no cache yet). While true,
     * {@link AsyncContentBaseProps.skeleton} shows. Pass an already-reduced
     * condition, e.g. `isLoading && items.length === 0`.
     */
    isLoading: boolean
    /**
     * The LOADING branch slot: a COMPONENT reference (COMPOSITE-8), never a built
     * node — a skeleton mirroring the real layout (a `Skeleton.*` tree), so the box
     * doesn't collapse/jump when it resolves. The frame calls it itself, forwarding
     * `isSkeleton={true}`.
     */
    skeleton: ComponentTypeWithSkeleton
    /** True (after loading finishes) → the frame falls to the empty branch. */
    isEmpty?: boolean
    /**
     * The EMPTY branch slot, passed as PROPS (not a node) — forwarded straight
     * to {@link AsyncContentEmpty}. Left empty → the empty branch renders null
     * (the section hides itself).
     */
    emptyContent?: AsyncContentEmptyProps
    /**
     * Truthy → the frame falls to the error branch (HIGHEST PRIORITY, beats
     * even loading). Pass SWR's `error` (only once there's no cache left to show).
     */
    error?: unknown
    /**
     * The ERROR branch slot, passed as PROPS — forwarded straight to
     * {@link AsyncContentError}. NOTE: Left empty, the error branch does NOT
     * activate (the frame falls through to loading/empty/content) — keeping the
     * old contract, no behaviour change in this consolidation.
     */
    errorContent?: AsyncContentErrorProps
    /**
     * The CONTENT branch slot — data has finished loading. The wrapper frame's
     * main path. A COMPONENT reference (COMPOSITE-8), never a built node — the
     * frame calls it itself, forwarding `isSkeleton={false}`.
     */
    content?: ComponentTypeWithSkeleton
    /** Dev/spec: overlay an anatomy annotation around the branch currently rendering. */
}

/**
 * The standard STATE-SWITCH frame for every async data region — the ONE place
 * holding the four branches that SWR's render contract demands. Priority order:
 *
 *   error → loading → empty → content
 *
 * The two message branches are configured via PROPS (not a node):
 * `emptyContent={{ title, description, onRetry, retryLabel }}`; `skeleton` is a
 * `Skeleton.*` tree mirroring the real layout.
 *
 * @param props - {@link AsyncContentBaseProps}
 */
const Base = ({
    isLoading,
    skeleton: Skeleton,
    isEmpty = false,
    emptyContent,
    error,
    errorContent,
    content: Content,
}: AsyncContentBaseProps) => {
    let branch: React.ReactNode
    if (error && errorContent) {
        branch = <ErrorMessage {...errorContent} />
    } else if (isLoading) {
        branch = <Skeleton isSkeleton />
    } else if (isEmpty) {
        branch = emptyContent ? <Empty {...emptyContent} /> : null
    } else {
        branch = Content ? <Content isSkeleton={false} /> : undefined
    }
    // `branch == null` = the SILENT empty branch: nothing rendered, so there is no
    // node to annotate — skip the overlay instead of badging an empty box.
    return <>{branch}</>
}

// ─────────────────────────────────────────────────────────────────────────────
// .Empty — the empty-message frame (was `EmptyContent`)
// ─────────────────────────────────────────────────────────────────────────────

/** Props for {@link AsyncContentEmpty} — the empty-message frame (props-only). */
export type AsyncContentEmptyProps = MessageProps

/**
 * A standalone EMPTY-MESSAGE frame — tray icon, title + optional description,
 * and an action slot (or the "retry" shorthand), centred. This is the standard
 * `emptyContent` for {@link AsyncContent}.
 *
 * A THIN layer over the `EmptyState` frame: it only adds the default
 * `TrayIcon` and wraps `onRetry`/`retryLabel` into a button for the `action`
 * slot — it does NOT redraw the icon + title + description + button itself.
 *
 * @param props - {@link AsyncContentEmptyProps}
 */
const Empty = (props: AsyncContentEmptyProps) => {
    const { title, description, icon, classNames } = props
    return (
        <EmptyState

            classNames={classNames}
            icon={withDuotone(icon ?? TrayIcon)}
            title={title}
            description={description}
            action={composeAction(props)}
        />
    )
}

// ─────────────────────────────────────────────────────────────────────────────
// .Error — the error-message frame (was `ErrorContent`)
// ─────────────────────────────────────────────────────────────────────────────

/** Props for {@link AsyncContentError} — the error-message frame (props-only). */
export type AsyncContentErrorProps = MessageProps

/**
 * A standalone ERROR-MESSAGE frame — warning icon, title + optional description,
 * and an action slot (usually "retry"), centred. This is the standard
 * `errorContent` for {@link AsyncContent}.
 *
 * A THIN layer over the `EmptyState` frame with `tone="danger"`.
 *
 * @param props - {@link AsyncContentErrorProps}
 */
const ErrorMessage = (props: AsyncContentErrorProps) => {
    const { title, description, icon, classNames } = props
    return (
        <EmptyState

            classNames={classNames}
            tone="danger"
            icon={withDuotone(icon ?? WarningIcon)}
            title={title}
            description={description}
            action={composeAction(props)}
        />
    )
}

/**
 * The FRAME namespace for the async lifecycle — three members, one import:
 *
 * | Member | Content channel |
 * |---|---|
 * | `.Base`  | `content` · `skeleton` · `emptyContent` · `errorContent` |
 * | `.Empty` | props-only (`title`/`description`/`icon`/`action`) |
 * | `.Error` | props-only (`title`/`description`/`icon`/`action`) |
 */
export { Base as AsyncContent, Empty as AsyncContentEmpty, ErrorMessage as AsyncContentError }

import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { type ButtonSize, type ButtonVariant, type IconComponent } from "@sb-components/atoms/buttons/Button/button-tokens"
import { ResponsiveCluster, type ResponsiveClusterItem } from "@sb-components/frames/ResponsiveCluster/ResponsiveCluster"
import type { ResponsiveRowSwitch } from "@sb-components/frames/ResponsiveRow/ResponsiveRow"
import type { PrincipleToken, ExplainReason } from "@sb-components/frames/_principles"
import { PRINCIPLE_STYLE } from "@sb-components/frames/_principle-style"
import type { AllowedGap, LayoutJustify } from "@sb-components/frames/_spacing"

/**
 * `ButtonGroup` — a layout cluster that arranges buttons built from `items`, with a
 * cluster-level `size`. Composes `ButtonBase`; per-button props
 * (`variant`/`prefixIcon`/`isPending`/`isDisabled`) belong to `Button`, not the cluster.
 */

/** One button in a {@link ButtonGroup} — described as data, not JSX. */
export interface ButtonGroupItem {
    /** React key + action identifier. */
    key: string
    /** Button label. Omit for an icon-only button (then `prefixIcon` + `ariaLabel` are required). */
    label?: string
    /** Icon component — leading glyph when `label` is set, sole glyph otherwise. */
    prefixIcon?: IconComponent
    /** Accessible name — required when there is no `label`. */
    ariaLabel?: string
    /** Action intent → variant. Default `primary`. */
    variant?: ButtonVariant
    onPress?: () => void
    isDisabled?: boolean
    /** `true` marks this button busy: spinner + locked press, scoped to this button only. */
    isPending?: boolean
}

/** Props for {@link ButtonGroup} — a row cluster of buttons. */
export interface ButtonGroupProps {
    /** The row's buttons, described as data. An item with `label` renders labeled; without, icon-only. */
    items: Array<ButtonGroupItem>
    /** Scale shared by the whole row (default `md`) — every button in a cluster is the same size. */
    size?: ButtonSize
    /** `true` renders a skeleton mirroring the item count (pill/square per item). */
    isSkeleton?: boolean
    /**
     * Layout seam for this control row. Default `flex-action`.
     * Use `flex-action-end` / `flex-action-start` / `flex-action-between` when the
     * main-axis distribution is part of the meaning (form closing rows).
     */
    principle?: PrincipleToken
    /**
     * Why this layer exists - one sentence, forwarded to the owning cluster beside `principle`.
     */
    explain?: ExplainReason
    /**
     * Container step this row leaves the full-width column for the packed row at.
     * Default `sm` — a button row needs far less room than a page split to pack.
     */
    at?: ResponsiveRowSwitch
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** Source-level tier metadata. */
export const meta = { tier: "composite", name: "ButtonGroup" } as const

/** Cluster of related buttons that wrap together at a breakpoint. */
export const ButtonGroup = ({
    items,
    size = "md",
    isSkeleton = false,
    principle = "flex-action",
    explain,
    at = "sm",
    classNames,
}: ButtonGroupProps) => {
    const entry = PRINCIPLE_STYLE[principle]
    const gap: AllowedGap = entry.kind === "gap" ? entry.step : 3
    const justify: LayoutJustify | undefined = entry.kind === "gap" ? entry.justify : undefined
    return (
        <ResponsiveCluster
            data-tier="composite"
            data-component="ButtonGroup"
            at={at}
            gap={gap}
            principle={principle}
            explain={explain}
            justify={justify}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={items.map((item): ResponsiveClusterItem => {
                const shared = {
                    variant: item.variant,
                    size,
                    onPress: item.onPress,
                    isDisabled: item.isDisabled,
                    isPending: item.isPending,
                } as const
                const { label, prefixIcon, ariaLabel } = item
                if (label != null) {
                    return {
                        key: item.key,
                        content: ({ isSkeleton: skeleton }: SkeletonProps) => (
                            <Button label={label} prefixIcon={prefixIcon} isSkeleton={skeleton} {...shared} />
                        ),
                    }
                }
                if (prefixIcon != null) {
                    return {
                        key: item.key,
                        content: ({ isSkeleton: skeleton }: SkeletonProps) => (
                            <Button
                                isIconOnly
                                prefixIcon={prefixIcon}
                                ariaLabel={ariaLabel ?? ""}
                                isSkeleton={skeleton}
                                {...shared}
                            />
                        ),
                    }
                }
                return { key: item.key, content: () => null }
            })}
        />
    )
}

import React from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import {
    ButtonGroupRoot,
    ButtonGroupSeparator,
} from "@sb-components/atoms/buttons/ButtonGroup/ButtonGroup"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `Button.RadioGroup` — a flex-wrap row of selectable buttons, single- or multi-select.
 * Leaves: `items` builds N child buttons (`Default`, with per-item `isDisabled`); `multiple`
 * allows ≥2 selected at once; `trailing` appends a non-option button (e.g. "+N"); `itemAction`
 * turns each item into a fused `ButtonGroup` [select | delete | more].
 */

interface CloneableActionElementProps {
    children?: ReactNode
}

/** One selectable button in a {@link ButtonRadioGroup}. */
export interface ButtonRadioGroupItem<T extends string> {
    /** Value selected when this button is chosen. */
    value: T
    /** Button content (icon + label + meta — caller-defined inline row). */
    content: ReactNode
    /** When true the button is dimmed and not selectable. */
    isDisabled?: boolean
}

/** Props shared by both the single- and multi-select modes of {@link ButtonRadioGroup}. */
interface ButtonRadioGroupBaseProps<T extends string> {
    /** The selectable buttons. */
    items: Array<ButtonRadioGroupItem<T>>
    /** Accessible label for the group. */
    ariaLabel: string
    /**
     * Optional trailing node placed after the buttons in the SAME row (e.g. a
     * "+N" overflow button). Not part of the group's value — it's an action.
     */
    trailing?: ReactNode
    /**
     * Optional per-item trailing action(s) — e.g. a delete button and/or a "⋮"
     * (kebab) menu trigger. When provided, the item's select button and these
     * action buttons render as ONE connected `ButtonGroup` per item
     * (`[select | delete | ⋮]`). Return the action `<Button>`s as an ARRAY (with
     * `key`s) so each is an individual segment. Omit for a plain single-select row.
     */
    itemAction?: (item: ButtonRadioGroupItem<T>) => ReactNode
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** Single-select mode (default) — exactly one value selected at a time. */
interface ButtonRadioGroupSingleProps<T extends string> extends ButtonRadioGroupBaseProps<T> {
    /** Single-select — omit or pass `false`. */
    multiple?: false
    /** Currently selected value. */
    value: T
    /** Fired with the chosen value when a button is selected. */
    onChange: (value: T) => void
}

/**
 * Multi-select mode — a SET of values, each button an independent toggle. The
 * caller owns the set + the toggle logic (e.g. enforcing "at least one selected");
 * this component only reports which button was pressed via {@link onToggle}.
 */
interface ButtonRadioGroupMultiProps<T extends string> extends ButtonRadioGroupBaseProps<T> {
    /** Multi-select — pass `true`. */
    multiple: true
    /** Currently selected values. */
    values: Array<T>
    /** Fired with the pressed value (the caller adds/removes it from its own set). */
    onToggle: (value: T) => void
}

/** Props for {@link ButtonRadioGroup} — a discriminated union on `multiple`. */
export type ButtonRadioGroupProps<T extends string> =
    | ButtonRadioGroupSingleProps<T>
    | ButtonRadioGroupMultiProps<T>

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "ButtonRadioGroup" } as const

/**
 * A single-select toggle-button group laid out as a flex-wrap row (buttons wrap
 * to the next line, never scroll). Every option is a house `<Button>`:
 * standalone, selected = filled `tertiary` (NEUTRAL, not accent — a facet/config
 * toggle isn't a CTA), unselected = hollow `ghost`. NEVER `primary` here — a config
 * row commonly sits on the SAME surface as the page's one accent CTA.
 *
 * When `itemAction` is supplied, each item instead renders as one connected
 * `ButtonGroup` — the select button + its action button(s) touching, only the
 * two outer ends rounded (`[select | delete | ⋮]`). The seam is the house
 * `ButtonGroupSeparator`, baked to the `--border` token and full-height.
 *
 * `role="group"` + `aria-pressed` per option — works for BOTH the default
 * single-select toggle group and the multi-select mode. House `Button` does not
 * accept `aria-pressed`, so the standalone path wraps the control in a span;
 * the fused `ButtonGroupRoot` path cannot wrap (segments must be buttons), so
 * pressed state is carried only on the standalone span.
 *
 * @param props - {@link ButtonRadioGroupProps}
 */
export const ButtonRadioGroup = <T extends string>(props: ButtonRadioGroupProps<T>) => {
    const { items, ariaLabel, trailing, itemAction, classNames } = props
    // narrow the discriminated union once — selection state + the press handler are
    // the only things that differ between single- and multi-select.
    const isSelected = (candidate: T): boolean =>
        (props.multiple ? props.values.includes(candidate) : props.value === candidate)
    const onPress = (candidate: T): void => {
        if (props.multiple) {
            props.onToggle(candidate)
        } else {
            props.onChange(candidate)
        }
    }
    return (
        <div
            role="group"
            aria-label={ariaLabel}
            className={cn("flex flex-wrap items-center gap-2", classNames)}
            data-tier="composite"
            data-component="ButtonRadioGroup"
            data-principle="flex-action"
        >
            {items.map((item) => {
                const selected = isSelected(item.value)
                if (!itemAction) {
                    // standalone: selected = filled `tertiary`, unselected = hollow `ghost`.
                    return (
                        <span key={item.value} aria-pressed={selected}>
                            <Button
                                size="sm"
                                variant={selected ? "tertiary" : "ghost"}
                                isDisabled={item.isDisabled}
                                onPress={() => onPress(item.value)}
                                label={item.content}
                            />
                        </span>
                    )
                }
                // select button + its action(s) = one connected ButtonGroup per item.
                // Each action button gets a `ButtonGroupSeparator` injected at the head
                // of its children — the separator must sit inside the following button.
                return (
                    <ButtonGroupRoot key={item.value} size="sm">
                        <Button
                            size="sm"
                            variant={selected ? "secondary" : "tertiary"}
                            isDisabled={item.isDisabled}
                            onPress={() => onPress(item.value)}
                            label={item.content}
                        />
                        {React.Children.map(itemAction(item), (action) =>
                            React.isValidElement<CloneableActionElementProps>(action)
                                ? React.cloneElement(
                                    action,
                                    undefined,
                                    <ButtonGroupSeparator />,
                                    action.props.children,
                                )
                                : action,
                        )}
                    </ButtonGroupRoot>
                )
            })}
            {trailing}
        </div>
    )
}

"use client"

import { cn } from "@heroui/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import type { IconComponent } from "@sb-components/atoms/buttons/Button/button-tokens"

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "FloatingActionButton" } as const

/**
 * `FloatingActionButton` — a bottom-right floating action button: a round, shadowed accent
 * circle composing the icon-only `Button`, pinned to the corner with `fixed`. Leaves: `icon`,
 * `isSkeleton`. `onPress`/`ariaLabel` carry the press handler and accessible name only.
 */

/** Props for the {@link FloatingActionButton} block. */
export interface FloatingActionButtonProps {
    /** Press handler (open the target overlay / action). */
    onPress: () => void
    /** Accessible name for the icon-only button. */
    ariaLabel: string
    /**
     * The single icon (§13b: named slot, not `children` — this block wraps no
     * caller content, it just carries one icon), passed as a COMPONENT reference
     * (not built JSX) — this block calls it itself, centered and sized by the
     * base `Button` (icon-size §5a).
     */
    icon?: IconComponent
    /** `true` → skeleton mirror (round FAB box, same placement) while loading. */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * A bottom-right floating action button — a round, shadowed accent circle. COMPOSES
 * the base `<Button iconOnly>` atom (§6): the atom owns the icon-only look,
 * native icon sizing (§5a) and interaction; this block only layers the fixed
 * placement, round shape, shadow and z-index. Pure + props-only.
 *
 * @param props - {@link FloatingActionButtonProps}
 */
export const FloatingActionButton = ({
    onPress,
    ariaLabel,
    icon: Icon,
    isSkeleton = false,
    classNames,
}: FloatingActionButtonProps) => {
    return (
        <div
            className={cn(
                "fixed bottom-6 right-[calc(var(--app-rail-w,0px)+1.5rem)] z-40",
                classNames,
            )}
        >
            <Button
                isIconOnly
                variant="primary"
                ariaLabel={ariaLabel}
                onPress={onPress}
                // `icon` is optional (the "icon unset" state is a bare circle); the atom
                // renders no glyph when `prefixIcon` is undefined (guarded), so the cast
                // only bridges the isIconOnly type which demands a definite component.
                prefixIcon={Icon as IconComponent}
                isSkeleton={isSkeleton}
                isElevated
            />
        </div>
    )
}

import React from "react"
import { cn } from "@heroui/react"
import type { ReactNode } from "react"
import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Tooltip } from "@sb-components/atoms/overlay/Tooltip/Tooltip"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import type { ChipTone, IconComponent } from "@sb-components/atoms/chips/Chip/Chip"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `EnumChip` — a `Chip` whose tone / label / optional tooltip / optional leading icon come
 * from a per-value lookup (`map[value]`), so a domain badge shrinks to just its map table plus
 * this delegate. Props: `value`, `map` (two halves of one lookup), `isSkeleton`,
 * `className`/`classNames`.
 */

/**
 * HeroUI soft-chip colors usable by an {@link EnumChip}.
 *
 * Alias, not a redeclaration: the exact same five values `Chip`'s own
 * `ChipTone` already carries.
 *
 * Aliases `ChipTone` specifically (NOT `AlertStatus`): `entry.color` flows
 * straight into `Chip`'s `tone`, a vendor-constrained prop — `ChipTone` is the
 * one guaranteed to match it 1:1.
 */
export type EnumChipColor = ChipTone

/**
 * The ONLY icons an {@link EnumChipEntry} can name — a CLOSED set, not an
 * arbitrary `IconComponent`. A string selector like `ListMark`
 * (`SurfaceCard.tsx`'s own "check"/"cross"/"pending"/"none" vocabulary), NOT
 * a raw icon reference — narrowing to a curated set is the whole point of
 * "universal" symbols (check/cross, nothing caller-chosen). Extend this
 * union the day a THIRD symbol earns the same bar, don't loosen the type.
 */
export type EnumChipIcon = "check" | "cross"

const ENUM_CHIP_ICON_MAP: Record<EnumChipIcon, IconComponent> = {
    check: CheckCircleIcon,
    cross: XCircleIcon,
}

/** One enum value's chip presentation. */
export interface EnumChipEntry {
    /** Soft chip color. Omit to use the Chip default. */
    color?: EnumChipColor
    /** Visible label (already localized by the caller). */
    label: ReactNode
    /** Optional tooltip (already localized); wraps the chip in a Tooltip when set. */
    tooltip?: ReactNode
    /**
     * Optional leading icon — one of {@link EnumChipIcon}, not a component.
     * Omit for every existing map entry that never had one; only add where
     * the value itself is a "universal" symbol, e.g. a failed/not-passed
     * verdict.
     */
    icon?: EnumChipIcon
}

/** Props for {@link EnumChip}. */
export interface EnumChipProps<E extends string> {
    /** The current enum value; looked up in {@link map}. */
    value: E
    /** Map from enum value to presentation (accepts Partial — unhandled values throw). */
    map: Partial<Record<E, EnumChipEntry>>
    /**
     * @deprecated pass `classNames` instead — a free string cannot be constrained.
     * Kept only for the two `_legacy` callers (`HostPlatformChip`, `EntityResultRow`)
     * that still pass a free-form string; `_legacy` is off-limits to edit, so this
     * escape stays until those callers are retired.
     */
    className?: string
    /**
     * Extra classes on the chip. Prefer this over `className`; the string form is going
     * away. This value is handed straight to `Chip`'s own closed `classNames` union, so
     * an unconstrained string here would only fail one tier down.
     */
    classNames?: Array<AllowedClassName>
    /** When `true`, renders the skeleton placeholder (a chip-shaped pill) instead of the real chip. */
    isSkeleton?: boolean
}

/**
 * The canonical "enum → soft chip" composite: a `Chip` whose
 * tone / label / optional tooltip / optional leading icon come from a per-value map.
 * Domain badges (AI-model category, difficulty, video host …) shrink to just their map
 * table + this delegate. Deliberately does NOT force width.
 *
 * Each entry can carry an optional per-value `icon` — most maps stay text-only;
 * a value only gets an icon when it is a "universal" symbol (check/cross), not a habit.
 *
 * @param props - {@link EnumChipProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "EnumChip" } as const

/** Chip whose tone, label, tooltip, and icon come from `map[value]`. */
export const EnumChip = <E extends string>({ value, map, className, classNames, isSkeleton }: EnumChipProps<E>) => {
    const wrapChip = (chip: React.ReactElement) => {
        const cls = cn(className, classNames)
        return cls ? <div className={cls}>{chip}</div> : chip
    }
    if (isSkeleton) {
        // The atom's shimmer matches the real chip box, so no `h-6` patch is needed
        // here — a call site having to patch the atom's shape is the sign the atom is
        // wrong, not this spot. `Chip` no longer takes placement classes; wrap instead.
        return wrapChip(<Chip isSkeleton />)
    }
    const entry = map[value]
    if (!entry) {
        throw new Error(`EnumChip: no map entry for value "${value}"`)
    }
    const chip = wrapChip(
        <Chip
            tone={entry.color ?? "default"}
            text={entry.label}
            icon={entry.icon != null ? ENUM_CHIP_ICON_MAP[entry.icon] : undefined}
        />,
    )
    if (entry.tooltip == null) {
        return chip
    }
    return (
        <Tooltip label={entry.tooltip}>{chip}</Tooltip>
    )
}

import type { ReactNode } from "react"
import { cn } from "@heroui/react"
import {
    TableRoot,
    TableScrollContainer,
    TableContent,
    TableHeader,
    TableBody,
    TableColumn,
    TableRow,
    TableCell,
} from "@sb-components/atoms/data/Table/Table"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { Box } from "@sb-components/frames/Box/Box"

/**
 * `Table` — a table frame. Owns the column configuration (`columns`: alignment + width),
 * building rows from `items`, and the three frame states of a list: empty (`emptyContent`),
 * loading (`isSkeleton`), and pressable rows (`onRowPress`). Does not format content — every
 * cell is a `ReactNode` the consumer passes in.
 */

/** Which edge a column's content aligns to (reading start, or the right edge for numbers/actions). */
export type TableAlign = "start" | "end"

/** Declares ONE column — data configuration, not a JSX child. */
export interface TableColumnSpec {
    /** Column key: both the React key and the key used to read the cell in each `item`. */
    key: string
    /**
     * Column header text. `string`, not `ReactNode` (COMPOSITE-8): the frame renders it through
     * the `Typography` atom itself rather than accepting an already-built node it cannot reopen.
     */
    header: string
    /** Content alignment for the column (applies to BOTH the header and every cell). Default `start`. */
    align?: TableAlign
    /** Fixed CSS width for the column (`"96px"`, `"20%"`). Omit to size to content. */
    width?: string
}

/**
 * ONE row: `key` (React key + row id) plus one node for EVERY `column.key`.
 * Already-formatted nodes — the frame knows nothing about the domain.
 *
 * COMPOSITE-8 note: cell values remain `ReactNode` on this pre-existing item shape
 * (`TableRowItem = Record<string, ReactNode>`). Not redesigned in the COMPOSITE-3/10 batch.
 */
export type TableRowItem = Record<string, ReactNode> & { key: string }

/** Props for {@link Table}. */
export interface TableBaseProps {
    /** Column configuration, in reading order. The first column is the row-header (a11y). */
    columns: ReadonlyArray<TableColumnSpec>
    /** The rows. REQUIRED — a repeated list is data, never children (§13b). */
    items: ReadonlyArray<TableRowItem>
    /**
     * The table's name for screen readers. REQUIRED: react-aria's `Table` has no
     * implicit label — omitting it reads the whole table as nameless (tsc/eslint do NOT catch this).
     */
    ariaLabel: string
    /**
     * Rendered INSIDE the table body when `items` is empty — so "empty" reads as
     * intentional. Takes a COMPONENT reference (COMPOSITE-8): the frame calls it,
     * forwarding `isSkeleton`, rather than receiving an already-built node it cannot shimmer.
     */
    emptyContent?: ComponentTypeWithSkeleton
    /**
     * `true` → keeps the REAL frame + header, replaces every cell with a skeleton
     * bar instead (§8 keeps the container real). Mirror row count = `items.length`,
     * or `3` when empty.
     */
    isSkeleton?: boolean
    /** A handler set → every row becomes a press target (react-aria row action), receiving `item.key`. */
    onRowPress?: (key: string) => void
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Table" } as const

/** Default mirror row count when there is no data yet to count. */
const SKELETON_ROWS_FALLBACK = 3

/** Content alignment — set on the CHILD span (wins over inheritance), see the file header note. */
const ALIGN_CLS: Record<TableAlign, string> = {
    start: "text-start",
    end: "text-end",
}

/** Wraps one cell/header's content so the FRAME owns alignment (§4), instead of it leaking to the call site. */
/** Params for the local {@link CellBox} — one table cell's alignment wrapper (internal, not a public slot). */
interface CellBoxArgs {
    /** Horizontal alignment of the cell content. */
    align?: TableAlign
    /** Cell content. */
    children: ReactNode
}

const CellBox = ({ align, children }: CellBoxArgs) => (
    <span className={cn("block", ALIGN_CLS[align ?? "start"])}>{children}</span>
)

/**
 * Table frame: a `columns` configuration + an `items` array, the frame builds its
 * own header/rows/cells. Empty → `emptyContent`; loading → mirrors the skeleton
 * within the same frame; `onRowPress` set → rows become press targets (a11y handled by react-aria).
 *
 * @param props - {@link TableBaseProps}
 */
const TableBase = ({
    columns,
    items,
    ariaLabel,
    emptyContent: EmptyContent,
    isSkeleton = false,
    onRowPress,
    classNames,
}: TableBaseProps) => {
    // The header is CONFIGURATION (known before any data arrives) → the skeleton keeps
    // the REAL header, only cells become bars; the frame/column widths never jump once data lands (§8).
    const header = (
        <TableHeader>
            {columns.map((column, index) => (
                <TableColumn
                    key={column.key}
                    id={column.key}
                    isRowHeader={index === 0}
                    style={column.width != null ? { width: column.width } : undefined}

                >
                    <CellBox align={column.align}>
                        <Typography size="sm" text={column.header} />
                    </CellBox>
                </TableColumn>
            ))}
        </TableHeader>
    )

    const body = isSkeleton ? (
        <TableBody>
            {Array.from({ length: items.length || SKELETON_ROWS_FALLBACK }).map((_, rowIndex) => (
                <TableRow key={rowIndex} id={`skeleton-${rowIndex}`}>
                    {columns.map((column) => (
                        <TableCell key={column.key}>
                            {/* The bar is 14px tall < the real cell's 20px line-height → wrap it in an>
                                `h-5` box so the mirror row is the EXACT height of a real row (§8, no
                                layout jump). Balance the height with `items-center`, NOT with margin
                                (§10a). The tag sits OUTSIDE the atom (the atom takes no rest props) —
                                same reason as `CellBox`. */}
                            <span className="flex h-5 items-center">
                                <Typography size="sm" isSkeleton />
                            </span>
                        </TableCell>
                    ))}
                </TableRow>
            ))}
        </TableBody>
    ) : (
        <TableBody

            renderEmptyState={
                EmptyContent != null
                    ? () => (
                        <Box principle="page-pad"
                            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                            className="text-center">
                            <EmptyContent isSkeleton={isSkeleton} />
                        </Box>
                    )
                    : undefined
            }
        >
            {items.map((item) => (
                <TableRow
                    key={item.key}
                    id={item.key}
                    onAction={onRowPress != null ? () => onRowPress(item.key) : undefined}

                >
                    {columns.map((column) => (
                        <TableCell key={column.key}>
                            <CellBox align={column.align}>{item[column.key]}</CellBox>
                        </TableCell>
                    ))}
                </TableRow>
            ))}
        </TableBody>
    )

    return (
        // House `TableRoot` omits `className` — placement classes ride a plain wrapper.
        <div className={cn(classNames)} data-tier="composite" data-component="Table">
            <TableRoot variant="primary">
                <TableScrollContainer>
                    <TableContent aria-label={ariaLabel}>
                        {header}
                        {body}
                    </TableContent>
                </TableScrollContainer>
            </TableRoot>
        </div>
    )
}

/**
 * `Table.*` — data-table frame (COMPOSITE tier §13). `Base` is the only shape;
 * variants (alignment, width, empty, loading, pressable rows) are PROPS on it (§6b).
 */
export { TableBase as Table }

import type { ComponentType, SVGProps } from "react"
import { Alert, type AlertStatus } from "@sb-components/atoms/feedback/Alert/Alert"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { Box } from "@sb-components/frames/Box/Box"
import { cn } from "@heroui/react"

/**
 * `Callout` — a flat tint strip placed inside a surface (surface-in-surface), not a floating
 * card. The shell owns the tint + icon per `status`; content goes through the named slots
 * `title`/`description`/`body`/`action` plus an optional close button. Builds its own
 * `Button` from `actionLabel`/`onAction` and forwards `onClose` to the underlying `Alert` atom.
 */

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Callout" } as const

/** Semantic tone — the atom's `AlertStatus` re-exported under this frame's name. */
export type CalloutStatus = AlertStatus

/** Icon passed as a COMPONENT (phosphor), never JSX — the frame owns its scale (§4/§5). */
export type CalloutIcon = ComponentType<SVGProps<SVGSVGElement>>

/**
 * Action button bg/text per status — SOLID `bg-<status>` CTA against the lighter
 * tint. INTERNAL: the CTA lived in the caller's `action` slot in the old shape,
 * so the caller had to hold `Button` and apply the skin itself. Now the frame
 * builds the button ITSELF from `actionLabel`/`onAction` ⇒ the caller
 * (especially a SCREEN) no longer touches the atom.
 */
const CALLOUT_ACTION_CLASS: Record<CalloutStatus, string> = {
    default: "bg-foreground text-background",
    accent: "bg-accent text-accent-foreground",
    success: "bg-success text-success-foreground",
    warning: "bg-warning text-warning-foreground",
    danger: "bg-danger text-danger-foreground",
    info: "bg-info text-info-foreground",
}

/** Props SPECIFIC to {@link Callout} — EXCEPT the `title`/`isSkeleton` pair (see {@link CalloutProps}). */
interface CalloutOwnProps {
    /** Semantic tone (drives tint + icon/title colour). Default `"default"`. */
    status?: CalloutStatus
    /**
     * Optional supporting line under the title — the body TEXT slot. `string`,
     * not `ReactNode` (COMPOSITE-8) — forwarded straight into `Alert`, which
     * renders it (or a shimmer bar in its place) itself.
     */
    description?: string
    /**
     * Optional free-form body region under `description` (a short list, a meta
     * row). A COMPONENT reference, not a built node (COMPOSITE-8) — the frame
     * calls it itself with `isSkeleton` forwarded before handing the result to
     * `Alert`'s own `body` slot.
     */
    body?: ComponentTypeWithSkeleton
    /** Optional custom indicator icon as a COMPONENT; omit for the status default. */
    icon?: CalloutIcon
    /**
     * CTA label (footer slot). The frame builds the button ITSELF and applies the
     * skin per `status` — the caller only supplies TEXT, not a `Button` (a screen
     * must not hold the atom).
     */
    actionLabel?: string
    /** Handler for the CTA; the button only shows once `actionLabel` is also present. */
    onAction?: () => void
    /** When provided, renders a status-coloured close (×) wired to this. */
    onClose?: () => void
    /** Accessible label for the close button. */
    closeAriaLabel?: string
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * `isSkeleton` is a co-located loading state — forwarded straight into `Alert`,
 * which owns drawing the shimmer bars. `title` is optional only in the
 * `isSkeleton: true` branch; the live branch still requires it. `string`, not
 * `ReactNode` (COMPOSITE-8) — the frame hands it to `Alert`'s own `title` slot.
 */
export type CalloutProps = CalloutOwnProps &
    (
        | { isSkeleton: true; title?: string }
        | { isSkeleton?: false; title: string }
    )

/**
 * A tinted, flat note for use INSIDE a card / surface (surface-in-surface): a thin
 * `bg-<status>-soft` + `shadow-none` highlight strip, so it doesn't read as a
 * card-in-card.
 *
 * A thin FRAME around the `Alert` atom: callout = an alert PLACED INSIDE a
 * surface, so the frame only picks `tone="soft"` + glyph `md` and hands the
 * whole skin (tint · icon per valence · × button) to the atom. The frame used
 * to hand-feed three color tables in parallel with `Toast` — that was drift,
 * now removed.
 *
 * @param props - {@link CalloutProps}
 */
export const Callout = (props: CalloutProps) => {
    const {
        status = "default",
        description,
        body: Body,
        icon,
        actionLabel,
        onAction,
        onClose,
        closeAriaLabel,
        classNames,
    } = props
    // Narrowed off the discriminant so `title` stays required in the live branch —
    // destructuring it straight off `props` above would widen it to `string | undefined`
    // and lose exactly that guarantee (same shape `Alert`/`Toast` already use).
    const content = props.isSkeleton
        ? ({ isSkeleton: true, title: props.title } as const)
        : ({ isSkeleton: false, title: props.title } as const)
    const alert = (
        <Alert
            status={status}
            tone="soft"
            {...content}
            description={description}
            body={Body ? <Body isSkeleton={props.isSkeleton} /> : undefined}
            icon={icon}
            action={
                actionLabel ? (
                    // The frame owns the CTA: builds the button + applies skin per status itself. Caller only supplies text.
                    // Button is an atom — it owns its own appearance, so the per-status skin wraps a div rather than reaching into the atom.
                    <div className={CALLOUT_ACTION_CLASS[status]}>
                        <Button label={actionLabel} size="sm" onPress={onAction} />
                    </div>
                ) : undefined
            }
            onClose={onClose}
            closeAriaLabel={closeAriaLabel}
        />
    )
    return classNames?.length ? <Box className={cn(classNames)}>{alert}</Box> : alert
}

import type { ComponentType, SVGProps } from "react"
import { cn } from "@heroui/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { StackV } from "@sb-components/frames/Stack/Stack"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"

/**
 * `EmptyState` — a centered vertical stack that fills an empty spot (empty list, no results)
 * or a broken spot (`tone="danger"` + a retry button). Slots: `code`, `icon`, `description`,
 * `body`, `action`; axes `tone` and `size` (`compact`/`page`). This shell IS the empty/error
 * state, so it has no loading leaf of its own.
 */

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "EmptyState" } as const

/** Icon passed as a COMPONENT (phosphor), never JSX — the frame owns its scale (§4/§5). */
export type EmptyStateIcon = ComponentType<SVGProps<SVGSVGElement>>

/** Props SPECIFIC to {@link EmptyState} — EXCEPT the `title`/`isSkeleton` pair (see {@link EmptyStateProps}). */
interface EmptyStateOwnProps {
    /**
     * Optional decorative icon as a COMPONENT (Phosphor) above the title — the frame
     * renders it `size-8` + toned. Ignored in `size="compact"`.
     */
    icon?: EmptyStateIcon
    /**
     * Optional large status numeral (e.g. `"404"`, `"500"`) above the icon/title.
     * Intended for `size="page"`; ignored in `size="compact"`. `string`, not
     * `ReactNode` (COMPOSITE-8) — the frame wraps it in `Typography` itself.
     */
    code?: string
    /**
     * Optional supporting text under the title. Ignored in `size="compact"`.
     * `string`, not `ReactNode` (COMPOSITE-8) — the frame wraps it in `Typography`
     * itself, so `isSkeleton` reaches the text it renders.
     */
    description?: string
    /**
     * Optional free-form body region under `description` (a hint list, an
     * illustration). Ignored in `size="compact"`. A COMPONENT reference, not a
     * built node (COMPOSITE-8) — the frame calls it itself with `isSkeleton`
     * forwarded.
     */
    body?: ComponentTypeWithSkeleton
    /**
     * Optional call-to-action region below the body (typically a `Button`).
     * Ignored in `size="compact"`. In `size="page"`, this can lay out multiple
     * actions itself — centered and wrapped. A COMPONENT reference, not a built
     * node (COMPOSITE-8) — the frame calls it itself with `isSkeleton` forwarded.
     */
    action?: ComponentTypeWithSkeleton
    /**
     * Icon tone. `"neutral"` (default) tints the icon `text-foreground`;
     * `"danger"` tints it `text-danger` for error placeholders. Only the icon
     * colour changes — title and description stay as-is.
     */
    tone?: "neutral" | "danger"
    /**
     * Layout size:
     * - `"default"` — the standard centered stack for lists/panels/sections.
     * - `"compact"` — a single muted title-only line (no icon/description/body/action/code).
     * - `"page"` — roomy full-page sizing for whole-route failures (404/500), with a
     *   larger title and room for a `code` numeral above it.
     */
    size?: "default" | "compact" | "page"
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * `isSkeleton` is a co-located loading state — this frame renders its own
 * skeleton bars (via `Typography`) rather than delegating to a `Skeleton.*`
 * compound. `title` is optional only in the `isSkeleton: true` branch; the
 * live branch still requires it. `string`, not `ReactNode` (COMPOSITE-8).
 */
export type EmptyStateProps = EmptyStateOwnProps &
    (
        | { isSkeleton: true; title?: string }
        | { isSkeleton?: false; title: string }
    )

/**
 * Centered placeholder for lists, panels, sections, or whole routes with no content —
 * and for the "failed to load" variant of the same hole (`tone="danger"` + a retry `action`).
 * A vertical, centered stack: optional `code` → optional icon → title → optional
 * description → optional body → optional action. Omits a card wrapper — the caller
 * wraps it in a surface (e.g. `SurfaceCardList emptyState={…}`) when a frame is wanted.
 *
 * @param props - {@link EmptyStateProps}
 */
export const EmptyState = (props: EmptyStateProps) => {
    const {
        icon: Icon,
        code,
        description,
        body: Body,
        action: Action,
        tone = "neutral",
        size = "default",
        classNames,
    } = props
    const isSkeleton = props.isSkeleton ?? false
    // Narrowed off the discriminant so `title` stays required in the live branch —
    // destructuring it straight off `props` above would widen it to `string | undefined`
    // and lose exactly that guarantee (same shape `Alert`/`Toast` already use).
    const titleContent = props.isSkeleton
        ? ({ isSkeleton: true, text: props.title } as const)
        : ({ isSkeleton: false, text: props.title } as const)
    // Same discriminant trick for the optional strings below — `isSkeleton` must stay the
    // exact `true`/`false` literal, not the widened `boolean` this frame's own flag would
    // give, because `Typography`'s prop type is the same kind of union.
    const skeletonAttrs = isSkeleton ? ({ isSkeleton: true } as const) : ({ isSkeleton: false } as const)

    if (size === "compact") {
        // NOTE: The `Typography.*` atom does NOT accept unknown props (no rest spread) → every
        // anatomy tag must sit on a WRAPPING element, not be stuffed into the atom.
        return (
            <span
                className={cn("block", classNames)}

                data-tier="composite"
                data-component="EmptyState"
            >
                <Typography size="sm" color="muted" {...titleContent} />
            </span>
        )
    }

    const isPage = size === "page"

    return (
        <div

            className={cn(
                isPage
                    ? "mx-auto flex min-h-[70vh] max-w-xl flex-col items-center justify-center gap-6 px-6 py-8 text-center"
                    : "flex flex-col items-center gap-3 py-6 text-center",
                classNames,
            )}
            data-tier="composite"
            data-component="EmptyState"
        >
            {code != null ? (
                <div>
                    <Typography size="h1" weight="bold" color="muted" text={code} {...skeletonAttrs} />
                </div>
            ) : null}
            {Icon ? (
                <span className={cn("inline-flex", tone === "danger" ? "text-danger" : "text-foreground")}>
                    <Icon className="size-8" />
                </span>
            ) : null}
            {isPage ? (
                <StackV
                    gap={3}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    isSkeleton={isSkeleton}
                    items={[
                        () => (
                            <div>
                                <Typography size="h4" weight="semibold" align="center" {...titleContent} />
                            </div>
                        ),
                        ...(description ? [() => (
                            <div>
                                <Typography size="sm" color="muted" text={description} {...skeletonAttrs} />
                            </div>
                        )] : []),
                    ]}
                />
            ) : (
                <>
                    <div>
                        <Typography weight="medium" {...titleContent} />
                    </div>
                    {description ? (
                        <div>
                            <Typography size="xs" color="muted" text={description} {...skeletonAttrs} />
                        </div>
                    ) : null}
                </>
            )}
            {Body ? <div><Body isSkeleton={isSkeleton} /></div> : null}
            {Action ? (
                <div className={isPage ? "flex flex-wrap items-center justify-center gap-3" : undefined}>
                    <Action isSkeleton={isSkeleton} />
                </div>
            ) : null}
        </div>
    )
}

import type { ComponentType, ReactNode } from "react"
import { Label, Skeleton as HeroSkeleton, cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `FieldFrame` — the label / hint / control / error scaffold every form atom
 * composes so the atom itself is the full field.
 *
 * Composite form helper: label / hint / control / error scaffold.
 * Owns the vertical rhythm (`flex flex-col`, a fixed `gap-3` — the label rule,
 * see `FIELD_SEAM`): label on top, hint below the label, control, error line
 * last — and mirrors the exact shape when `isSkeleton`.
 *
 * "Bare" mode: when there is no label/hint/errorMessage/required (and not
 * skeleton), FieldFrame renders `children` directly with zero wrapper, so the
 * atom can still be used as a bare cell nested inside something else.
 */
export interface FieldFrameProps {
    /** Label above the control (`text-sm font-medium`). Omit → no label. */
    label?: ReactNode
    /** Description below the label (`text-xs text-muted`) — ALWAYS shown (unlike errorMessage). */
    hint?: ReactNode
    /** Error line below the control (`text-sm text-danger`) — set → field invalid. */
    errorMessage?: ReactNode
    /** Adds a `*` mark (text-danger) after the label. */
    isRequired?: boolean
    /** Dims the label (locking the control itself is the atom's job). */
    isDisabled?: boolean
    /** Loading mirror: a label-width skeleton over a control-skeleton, keeping the same column. */
    isSkeleton?: boolean
    /**
     * Control-shaped skeleton for `isSkeleton` — a zero-prop component reference
     * (COMPOSITE-8), never a built node. The frame mounts it only while loading.
     */
    skeletonControl?: ComponentType
    /**
     * The real control (an already-wrapped HeroUI cell). `FieldFrame` is a
     * wrapping frame that must accept the calling atom's arbitrary control
     * as-is (Input/Select/Choice/…) — it can't be swapped for a data prop,
     * since the control isn't "content" but a whole component tree.
     */
    children?: ReactNode
    /** The control's `id` so the label's `htmlFor` points correctly — the atom passes the same id down to the control. */
    id?: string
    /** Where this sits inside its parent (the outer column). Everything about appearance is a prop of its own. */
    classNames?: Array<AllowedClassName>
}

/**
 * Accessible NAME for the control: when `label` is a string, use it directly
 * (guarantees the control always has a readable name — even a compound control
 * like Number/Date/Otp that can't wire up `htmlFor`), otherwise falls back to
 * `fallback` (ariaLabel/placeholder). Avoids the a11y gap of an "unnamed control"
 * when a field has a label that can't be associated.
 */
export const fieldName = (label: ReactNode, fallback?: string): string | undefined =>
    typeof label === "string" ? label : fallback

/**
 * The seam between a label and the control it names is step 4 (`gap-3`, 12px) — a label names its
 * subject across a change of register, and `principles/gap.md`'s label rule sits that boundary at
 * step 4. It is fixed, not a prop: the old `tight`/`related` choice let one field breathe at a
 * different rhythm than the next for no reason a reader could name, which is the ambiguity the
 * numeric scale exists to end. Every field in the system now stacks at the same seam.
 */
const FIELD_SEAM = "gap-3"

/** Label + `*` mark when required. */
const withRequired = (label: ReactNode, isRequired?: boolean) =>
    isRequired ? (
        <>
            {label} <span className="text-danger">*</span>
        </>
    ) : (
        label
    )

/** Mount the control skeleton slot when present. */
const renderSkeletonControl = (skeletonControl?: ComponentType) => {
    const SkeletonControl = skeletonControl
    return SkeletonControl ? <SkeletonControl /> : null
}

/**
 * `FieldFrame` — label/hint/control/error column shared by every form atom.
 * @param props - {@link FieldFrameProps}
 */
const FieldFrameBase = ({
    label,
    hint,
    errorMessage,
    isRequired,
    isDisabled,
    isSkeleton,
    skeletonControl,
    children,
    id,
    classNames,
}: FieldFrameProps) => {
    const hasFrame = label != null || hint != null || errorMessage != null

    // ── Loading mirror ────────────────────────────────────────────────────────
    if (isSkeleton) {
        // Bare skeleton (no label frame) → just the control skeleton box (badges Skeleton itself).
        if (!hasFrame && label == null) {
            return <>{renderSkeletonControl(skeletonControl)}</>
        }
        return (
            <div data-tier="composite" data-component="FieldFrame" data-principle="label-field" className={cn("flex flex-col", FIELD_SEAM, classNames)}>
                {label != null ? (
                    // label-bar look), not the slot word "Label" it stands in for.
                    <HeroSkeleton className="h-4 w-1/3 rounded-md" />
                ) : null}
                {renderSkeletonControl(skeletonControl)}
            </div>
        )
    }

    // ── "Bare" — no frame → renders the control directly ───────────────────────
    if (!hasFrame) {
        return <>{children}</>
    }

    // ── Full field ─────────────────────────────────────────────────────────────
    return (
        <div data-tier="composite" data-component="FieldFrame" className={cn("flex flex-col", FIELD_SEAM, classNames)}>
            {label != null ? (
                <Label htmlFor={id} isDisabled={isDisabled} className="text-sm font-medium">
                    {withRequired(label, isRequired)}
                </Label>
            ) : null}

            {hint != null ? (
                <p className="text-muted text-xs">
                    {hint}
                </p>
            ) : null}

            {children}

            {errorMessage != null ? (
                <p className="text-danger text-sm">
                    {errorMessage}
                </p>
            ) : null}
        </div>
    )
}

/** `FieldFrame` — label/hint/control/error scaffold. */
export { FieldFrameBase as FieldFrame }

