import React from "react"
import { cn } from "@heroui/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { IconTile, type IconComponent, type IconTileTone } from "@sb-components/atoms/display/IconTile/IconTile"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { Box } from "@sb-components/frames/Box/Box"

/**
 * `UserCell` — the system's one person row: avatar + name + optional `@handle`. Leaves: `size`,
 * `handle`, `trailing`, `leadingIcon`, `isOwnRow`, `isSkeleton`. `leadingIcon`/`leadingTone` let
 * the row lead with a framed `IconTile` instead of `Avatar`, for rows that aren't a person
 * (a course/org/resource). `avatar` swaps the image inside `Avatar`; `username`/`displayName`
 * are the content each leaf fills in. Deps `Avatar` and `Typography` link to their own stories.
 */

/** Props for {@link UserCell}. */
export interface UserCellProps {
    /** Account username; drives the avatar fallback and is the default display name. */
    username: string
    /** Human-friendly name shown as the primary label; falls back to {@link UserCellProps.username}. */
    displayName?: string
    /** Uploaded avatar URL; resilient fallbacks are handled by {@link Avatar}. */
    avatar?: string | null
    /** Secondary handle line (e.g. `@username`); hidden when omitted. */
    handle?: string
    /** Visual density of the row; controls the avatar preset. Defaults to `"sm"`. */
    size?: "sm" | "md"
    /**
     * Optional icon COMPONENT that swaps the leading {@link Avatar} for a framed
     * {@link IconTile} — for rows led by a course/org/resource glyph instead of a
     * person (e.g. a leaderboard row for a team, or a "posted in `<course>`"
     * byline). Additive: omitted (default), the cell renders `Avatar` exactly as
     * before — every other prop keeps its current meaning. Always rendered at
     * `IconTile`'s `"sm"` step (40px) regardless of {@link UserCellProps.size},
     * matching the pairing already used for an icon-led row elsewhere in the
     * house (`FoundationResourceList`, `LeaderboardBoard`) — `IconTile`'s size
     * steps (40/64/80) don't line up with `Avatar`'s (32/40/48), so this is the
     * one step common to both without an untested oversize tile in a name row.
     */
    leadingIcon?: IconComponent
    /**
     * Tinted background + icon colour for {@link UserCellProps.leadingIcon}.
     * Ignored unless `leadingIcon` is set. Defaults to `"accent"`.
     */
    leadingTone?: IconTileTone
    /**
     * Optional right-aligned slot, e.g. a follow button or status chip. A
     * COMPONENT reference (COMPOSITE-8): the cell calls it itself and forwards
     * `isSkeleton`, so the slot can shimmer in place instead of vanishing
     * during loading and jumping the row's width back once data lands.
     */
    trailing?: ComponentTypeWithSkeleton
    /**
     * `true` when this row belongs to the viewer — tints the name accent so it
     * stands out in a list (e.g. a leaderboard or comment thread).
     */
    isOwnRow?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * Render the leaf skeleton (shimmer) instead of the cell. Every shimmer is
     * delegated to the atom it stands for — `Avatar isSkeleton size={size}` for
     * the circle, `Typography isSkeleton` for the name/handle bars — so none of
     * them drifts from that atom's own resting shape (COMPOSITE-10: this
     * composite decides WHICH parts shimmer and HOW MANY, never draws one itself).
     */
    isSkeleton?: boolean
}

/**
 * Presentational person cell: avatar + name + optional `@handle`, with an optional
 * right-aligned trailing slot. Pure and props-only — no store or data access; the
 * caller supplies all text and any interactive controls via {@link UserCellProps.trailing}.
 *
 * Composes the {@link Avatar} and {@link Typography} atoms — an avatar with a
 * name/handle beside it is an identity pairing, which is why this lives at the
 * composite tier instead of atom. The text column truncates so the cell
 * survives narrow containers (`min-w-0`).
 *
 * @param props - {@link UserCellProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "UserCell" } as const

const UserCellBase = ({
    username,
    displayName,
    avatar,
    handle,
    size = "sm",
    trailing: Trailing,
    leadingIcon: LeadingIcon,
    leadingTone = "accent",
    classNames,
    isOwnRow = false,
    isSkeleton = false,
}: UserCellProps) => {
    const name = displayName ?? username

    // `trailing` is free content the caller's component builds, not part of
    // UserCell's own anatomy, so it stays unbadged. Called in BOTH states
    // (COMPOSITE-8) — forwarding `isSkeleton` lets it shimmer in place instead
    // of vanishing during loading and jumping the row's width once data lands.
    const trailingSlot = Trailing ? (
        <Box principle="push-end" className="shrink-0">
        explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row."
            <Trailing isSkeleton={isSkeleton} />
        </Box>
    ) : null

    if (isSkeleton) {
        // Every shimmer is the atom's own: the avatar circle delegates to `Avatar
        // isSkeleton size={size}` so it matches this row's size, and the name/handle
        // bars delegate to `Typography isSkeleton` so their line box tracks that
        // atom's own type scale — nothing here draws a bar by hand (COMPOSITE-10).
        return (
            <div
                data-tier="composite"
                data-component="UserCell"

                className={cn("flex min-w-0 items-center gap-2", classNames)}
            >
                {LeadingIcon ? (
                    <IconTile isSkeleton size="sm" />
                ) : (
                    <Avatar isSkeleton size={size} />
                )}
                <div className="flex min-w-0 flex-col gap-0">
                    <Typography size="sm" isSkeleton />
                    {handle ? (
                        <Typography size="xs" isSkeleton />
                    ) : null}
                </div>
                {trailingSlot}
            </div>
        )
    }

    return (
        <div
            data-tier="composite"
            data-component="UserCell"

            className={cn("flex min-w-0 items-center gap-2", classNames)}
        >
            {LeadingIcon ? (
                <IconTile
                    icon={LeadingIcon}
                    tone={leadingTone}
                    size="sm"

                />
            ) : (
                <Avatar
                    name={username}
                    src={avatar ?? undefined}
                    seed={username}
                    size={size}

                />
            )}
            <div className="flex min-w-0 flex-col gap-0">
                <Typography size="sm"
                    weight="medium"
                    color={isOwnRow ? "accent" : undefined}
                    truncate

                    text={name}
                />
                {handle ? (
                    <Typography size="xs"
                        color="muted"
                        truncate

                        text={handle}
                    />
                ) : null}
            </div>
            {trailingSlot}
        </div>
    )
}

/** `UserCell.*` — presentational identity cell (avatar + name + optional handle/trailing). */
export { UserCellBase as UserCell }

import React from "react"
import { cn } from "@heroui/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH } from "@sb-components/frames/Stack/Stack"

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Legend" } as const

/** Many items in a narrow block wrap to a new line instead of overflowing. */

/**
 * Resolve a swatch `color` into the right paint channel: a Tailwind `bg-*`
 * utility class is applied as a className; anything else (a raw hex, `var(--…)`,
 * `rgb(…)`, …) is applied as an inline `backgroundColor` — same dual-mode
 * handling as the dot of `Chip` (`dotClassName` vs `dotColor`).
 */
const resolveDotColor = (color: string): { className?: string; style?: React.CSSProperties } =>
    color.startsWith("bg-")
        ? { className: color }
        : { style: { backgroundColor: color } }

/** One legend entry: a colour swatch + its label (+ an optional trailing value). */
export interface LegendItem {
    /** Stable key. */
    key: string
    /**
     * Label shown next to the swatch. `string`, not `ReactNode` — the composite
     * wraps it in `Typography` itself, so it must be able to build it.
     */
    label: string
    /** Swatch colour — a Tailwind `bg-*` class OR a raw colour value (`var(--success)`, `#3178c6`). */
    color: string
    /**
     * Optional trailing value printed after the label in the SAME muted line
     * (e.g. a "· 12" count or a "40%" share). Omit for a bare label. `string` —
     * see {@link LegendItem.label}.
     */
    suffix?: string
}

/** Props {@link Legend} carries regardless of loading state. */
interface LegendOwnProps {
    /**
     * Layout of the entries. `"row"` (default) is a `flex-wrap` row that wraps to
     * new lines when narrow; `"col"` stacks entries vertically.
     */
    direction?: "row" | "col"
    /** Entry count to shimmer while `isSkeleton`. Defaults to `3`. */
    skeletonCount?: number
    /** `true` → tag the dot/label skeleton bars with ``. */
}

/**
 * Props for the {@link Legend} block. `items` is REQUIRED unless `isSkeleton`
 * (§12b) — a shimmer legend has no real entries to show yet.
 */
export type LegendProps = LegendOwnProps &
    (
        | { isSkeleton: true; items?: Array<LegendItem> }
        | { isSkeleton?: false; items: Array<LegendItem> }
    )

/**
 * Standalone colour legend — a `flex-wrap` row (or vertical stack) of `dot +
 * label + optional trailing value`, matching the legend a {@link SegmentBar} or
 * {@link CourseProgressBar} renders under itself. Each entry's `color` accepts a
 * Tailwind `bg-*` class or a raw colour value, and an optional `suffix` prints a
 * count/share after the label. Pure/props-only.
 *
 * @param props - {@link LegendProps}
 */
export const Legend = ({
    items,
    direction = "row",
    isSkeleton = false,
    skeletonCount = 3,
    
}: LegendProps) => {
    return (
        <div
            className={cn(
                direction === "col"
                    ? "flex flex-col gap-2"
                    : "flex flex-wrap gap-x-3 gap-y-2",
                
            )}

            data-tier="composite"
            data-component="Legend"
            data-principle={direction === "col" ? "sibling-stack" : undefined}
        >
            {isSkeleton
                ? Array.from({ length: skeletonCount }, (_unused, index) => (
                    <StackH
                        key={index}
                        gap={3}
                        isSkeleton={isSkeleton}
                        items={[
                            /* ATOM GAP: no swatch/dot atom exists yet, so the dot stays a
                                    real plain span in both states — a neutral flat fill (no
                                    hand-drawn `animate-pulse`, COMPOSITE-10) instead of reaching
                                    for a vendor Skeleton (the same span shape the loaded entry
                                    below draws, just without a real color). */
                            () => (
                                <span
                                    aria-hidden
                                    className="size-2.5 shrink-0 rounded-full bg-default"

                                />
                            ),
                            () => <Typography size="xs" isSkeleton />,
                        ]}
                    />
                ))
                : (items ?? []).map((item) => {
                    const dot = resolveDotColor(item.color)
                    return (
                        <StackH
                            key={item.key}
                            gap={3}
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <span
                                        aria-hidden
                                        style={dot.style}
                                        className={cn("size-2.5 shrink-0 rounded-full", dot.className)}
                                    />
                                ),
                                () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={`${item.label}${item.suffix ?? ""}`} />,
                            ]}
                        />
                    )
                })}
        </div>
    )
}

import React from "react"
import { cn } from "@heroui/react"
import { ProgressBar } from "@sb-components/atoms/display/Progress/Progress"
import { ProgressMeterTargetMark } from "./TargetMark"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "ProgressMeter" } as const

/** Fill still far from the 85% target — the accent notch pill overshoots the thin bar; `mt-5` reserves room for the floating "85%" label. */
interface ProgressMeterOwnProps {
    /** Maximum value representing 100% completion. Defaults to `100`. */
    max?: number
    /**
     * Optional descriptive label rendered on the left of the top row. Pass a
     * translated string — the block never calls `useTranslations` itself. `string`,
     * not `ReactNode`: the composite wraps it in `Typography` itself, and a
     * pre-built node could not be told it is loading.
     */
    label?: string
    /** When `true`, renders the rounded completion percentage on the right of the top row. */
    showValue?: boolean
    /**
     * Fill color. Defaults to `"accent"`; pass a semantic tone (danger / warning /
     * success) when the bar's VALUE carries meaning.
     */
    color?: "accent" | "success" | "warning" | "danger"
    /** Optional TARGET mark on the track — a thin tick at `target/max` (e.g. an "85% goal" line). */
    target?: number
    /** Optional label rendered above the target tick (e.g. `"85%"`). Only shown when {@link ProgressMeterProps.target} is set. `string` — see {@link ProgressMeterOwnProps.label}. */
    targetLabel?: string
    /**
     * Optional left-aligned COMPONENT slot for a custom row above the track,
     * additive to (and independent of) the `label`/`showValue` row: pass this
     * when the row needs more than plain text (e.g. an icon plus a custom-
     * formatted unit). A COMPONENT reference, not a built node (COMPOSITE-8) —
     * the meter calls it itself and forwards `isSkeleton`, so it can shimmer in
     * place. Omitted (default), no such row renders and existing callers —
     * including ones already using `label`/`showValue` — are unaffected.
     */
    leading?: ComponentTypeWithSkeleton
    /**
     * Right-aligned partner to {@link ProgressMeterOwnProps.leading}. Either
     * may be passed alone; the row renders whichever side(s) are set.
     */
    trailing?: ComponentTypeWithSkeleton
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     * Prefer this over `className`; the string form is going away.
     */
    classNames?: Array<AllowedClassName>
    /** Dev/spec: overlay the anatomy annotation on this meter. */
}

/**
 * Props for {@link ProgressMeter}. `value` is REQUIRED unless `isSkeleton`
 * (§12b) — a shimmer track has no real ratio to show yet.
 */
export type ProgressMeterProps = ProgressMeterOwnProps &
    (
        | { isSkeleton: true; value?: number }
        | { isSkeleton?: false; value: number }
    )

/**
 * ProgressMeter renders a labelled, accessible progress bar: an optional top row
 * (label + rounded percentage) above a house {@link ProgressBar}, with an
 * optional target/goal marker overlaid on the track. A second, independent row
 * — {@link ProgressMeterOwnProps.leading}/{@link ProgressMeterOwnProps.trailing} —
 * can render just above the track for callers that need components instead of
 * plain text.
 *
 * @param props - {@link ProgressMeterProps}
 */
export const ProgressMeter = ({
    value,
    max = 100,
    label,
    showValue = false,
    color = "accent",
    target,
    targetLabel,
    leading: Leading,
    trailing: Trailing,
    isSkeleton = false,
    classNames,
}: ProgressMeterProps) => {
    const safeMax = max > 0 ? max : 1
    // `value` is REQUIRED whenever `isSkeleton` is false (the discriminated union above) —
    // guaranteed by the type at every real call site — the `?? 0` only satisfies narrowing
    // across the destructure, and is never seen while `isSkeleton` (the row it feeds stays
    // unshown or goes through `Typography`'s own shimmer instead).
    const percent = Math.round(((value ?? 0) / safeMax) * 100)
    const hasTopRow = label !== undefined || showValue
    // target tick position, clamped into the track (0..100%)
    const targetPercent = target === undefined
        ? null
        : Math.min(Math.max((target / safeMax) * 100, 0), 100)
    const topRow = hasTopRow ? (
        <StackH
            gap={3}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            justify="between"
            isSkeleton={isSkeleton}
            items={[
                () => <Typography size="xs" color="muted" truncate isSkeleton={isSkeleton} text={label} />,
                ...(showValue ? [() => (
                    <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={<>{percent}%</>} />
                )] : []),
            ]}
        />
    ) : null
    // Additive row, independent of `topRow` above: a component-based
    // leading/trailing pair for callers that need more than plain text (an
    // icon, a chip, a custom-formatted unit). Either side may be passed alone;
    // omitted entirely, `slotRow` is `null` and nothing changes for existing
    // callers.
    const hasSlotRow = Leading !== undefined || Trailing !== undefined
    const slotRow = hasSlotRow ? (
        <StackH
            gap={3}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            justify="between"
            isSkeleton={isSkeleton}
            items={[
                () => Leading ? (
                    <div className="min-w-0">
                        <Leading isSkeleton={isSkeleton} />
                    </div>
                ) : <span />,
                ...(Trailing ? [() => (
                    <div className="shrink-0">
                        <Trailing isSkeleton={isSkeleton} />
                    </div>
                )] : []),
            ]}
        />
    ) : null
    // Two DIFFERENT jobs, so two boxes. A single div doing both — `pt-6` (24px,
    // room for the floating label) and `flex h-5 items-center` (20px, the pill's
    // reference frame) on the SAME element — breaks: padding that exceeds the
    // declared height forces the browser to grow the outer box to fit it (24px,
    // not 20), and the two children then read TWO DIFFERENT origins on that grown
    // box — the track (normal flow) starts AFTER the padding, at y=56, while the
    // pill (`absolute top-1/2`) measures against the WHOLE padding box, landing at
    // y=44.
    // OUTER box owns the label's clearance only (`pt-6`, the scale's first step
    // that clears a `h-5`/20px obstacle).
    // INNER box is `relative flex h-5 items-center` — the pill's containing block
    // AND the track's flex-center axis, both measured against the SAME 20px frame,
    // so the `h-5` pill sits EXACTLY on the track midline.
    const trackSection = (
        <div className={cn(targetPercent !== null && targetLabel !== undefined && "pt-6")}>
            <div
                className={cn(
                    "relative",
                    targetPercent !== null && "flex h-5 items-center",
                )}
            >
                <div className="w-full">
                    <ProgressBar
                        trackDensity="compact"
                        value={value}
                        max={safeMax}
                        color={color}
                        ariaLabel={label ?? "Progress"}
                        isSkeleton={isSkeleton}
                    />
                </div>
                {targetPercent === null ? null : (
                    <ProgressMeterTargetMark percent={targetPercent} label={targetLabel} />
                )}
            </div>
        </div>
    )
    return (
        <StackV
            gap={3}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[
                () => topRow,
                () => slotRow,
                () => trackSection,
            ]}
        />
    )
}

import React from "react"
import { cn } from "@heroui/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { TypographyColor } from "@sb-components/atoms/text/Typography/Typography"

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "DotLabel" } as const

/**
 * `DotLabel` — a colour dot + an inline text label as one unit, with no pill/background. Use
 * where a coloured dot reads faster than the word alone but a full chip's padding would be too
 * heavy (a status line inside a card, an "Online" row beside a name, a category line in a dense
 * list). Leaves: `tone`, `color`, `isSkeleton`. The dot is a plain span (no bare-swatch atom yet).
 */

/** Label tone — the 6-value scale every composite text draws from. Default `muted` (a status line reads as secondary text; the swatch already carries the emphasis). */
export type DotLabelTone = "default" | "muted" | "accent" | "success" | "warning" | "danger"

const TONE_TO_TYPOGRAPHY: Record<DotLabelTone, TypographyColor> = {
    default: "default",
    muted: "muted",
    accent: "accent",
    success: "success",
    warning: "warning",
    danger: "danger",
}

/**
 * Resolve a swatch `color` into the right paint channel — same dual-mode
 * split `Legend` uses for its own dot: a Tailwind `bg-*` utility applies as a
 * className; anything else (a raw hex, `var(--…)`, `rgb(…)`) applies as an
 * inline `backgroundColor`, so a caller can pass either a token or a value
 * outside the Tailwind palette (e.g. a GitHub language colour) through one prop.
 */
/** The resolved dot paint channel — a Tailwind `bg-*` className, or a raw-colour inline style, never both. */
interface ResolvedDotColor {
    className?: string
    style?: React.CSSProperties
}

const resolveDotColor = (color: string): ResolvedDotColor => {
    if (color.startsWith("bg-")) {
        return { className: color }
    }
    return { style: { backgroundColor: color } }
}

/** Props shared regardless of loading state — see {@link DotLabelProps} for the `color`/`label`/`isSkeleton` union. */
interface DotLabelOwnProps {
    /** Label tone. Defaults to `"muted"`. */
    tone?: DotLabelTone
}

/**
 * `color`/`label` are required when rendering a real row; not needed when
 * `isSkeleton` — the shimmer mirror has no swatch colour or text of its own.
 */
export type DotLabelProps = DotLabelOwnProps &
    (
        | { isSkeleton: true; color?: string; label?: string }
        | {
              isSkeleton?: false
              /**
               * Swatch colour — a Tailwind `bg-*` class OR a raw colour value
               * (`var(--success)`, `#3178c6`).
               */
              color: string
              /**
               * The label text, rendered through `Typography` — the composite owns
               * the tone (see {@link DotLabelOwnProps.tone}), so this is `string`,
               * never a pre-built node.
               */
              label: string
          }
    )

/**
 * `DotLabel` — a colour dot beside an inline text label, no chip/pill shell.
 * See the file header for why this is not already `Chip`'s dot variant or
 * `Legend`.
 *
 * @param props - {@link DotLabelProps}
 */
export const DotLabel = ({
    color,
    label,
    tone = "muted",
    
    isSkeleton = false,
}: DotLabelProps) => {
    const dot = color ? resolveDotColor(color) : undefined

    return (
        <span
            className={cn("inline-flex items-center gap-1")}

            data-tier="composite"
            data-component="DotLabel"
            data-principle="icon-text"
        >
            {isSkeleton ? (
                // ATOM GAP (same one `Legend` already flags): no swatch/dot atom exists
                // yet, so the dot stays a real plain span in both states — a neutral
                // flat fill (no hand-drawn `animate-pulse`, COMPOSITE-10) instead of
                // reaching for a vendor Skeleton.
                <span
                    aria-hidden
                    className="size-2.5 shrink-0 rounded-full bg-default"

                />
            ) : (
                <span
                    aria-hidden
                    style={dot?.style}
                    className={cn("size-2.5 shrink-0 rounded-full", dot?.className)}

                />
            )}
            <Typography
                size="sm"
                color={isSkeleton ? undefined : TONE_TO_TYPOGRAPHY[tone]}

                isSkeleton={isSkeleton}
                text={label}
            />
        </span>
    )
}

import React from "react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV } from "@sb-components/frames/Stack/Stack"

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "TitledText" } as const

/**
 * `TitledText` — a primary line + optional muted secondary (and optional hint) stacked
 * vertically as one composite; a title<->subtitle pair is a single semantic unit rather than raw
 * `<Typography>` hand-rolled at every row. The composite owns the type scale per `size`; the
 * caller passes nodes only. Leaves: `subtitle`, `hint`, `size`, `weight`, `truncate`, `isSkeleton`.
 */

/**
 * Vertical text-stack scale:
 * - `row`    — dense list/setting row (title `sm` medium · subtitle `xs` muted).
 * - `header` — section/page header (title `h3` semibold · subtitle `sm` muted).
 * - `stat`   — a metric (title = big `h3` bold VALUE · subtitle = foreground label · hint muted).
 */
export type TitledTextSize = "row" | "header" | "stat"

/** Typography `size` + tone config resolved per {@link TitledTextSize}. */
/**
 * Skeleton bar width per line. Named so the widths can be typed where they are WRITTEN, not
 * only where they are read: the classes must be literal (`w-1/2`) because Tailwind only emits
 * a class it can see as a literal string in the source.
 */
interface TitledTextSkeletonWidths {
    /** Width class of the title bar. */
    title: AllowedClassName
    /** Width class of the subtitle bar. */
    sub: AllowedClassName
    /** Width class of the hint bar. */
    hint: AllowedClassName
}

interface SizeConfig {
    titleSize: "sm" | "h3"
    titleWeight: "medium" | "semibold" | "bold"
    subSize: "xs" | "sm"
    /** `undefined` -> foreground (default); `"muted"` -> muted line. */
    subColor?: "muted"
    subWeight?: "medium"
    /**
     * Skeleton bar width for each line — write the class LITERALLY (`w-1/2`), don't
     * build it dynamically (`w-${…}`), since Tailwind only generates a class from a
     * literal string it scans in the source.
     */
    skeleton: TitledTextSkeletonWidths
}

const SIZE_CONFIG: Record<TitledTextSize, SizeConfig> = {
    row: {
        titleSize: "sm",
        titleWeight: "medium",
        subSize: "xs",
        subColor: "muted",
        skeleton: { title: "w-1/2", sub: "w-2/3", hint: "w-1/3" },
    },
    header: {
        titleSize: "h3",
        titleWeight: "semibold",
        subSize: "sm",
        subColor: "muted",
        skeleton: { title: "w-1/3", sub: "w-2/3", hint: "w-1/2" },
    },
    stat: {
        titleSize: "h3",
        titleWeight: "bold",
        // stat's secondary is the LABEL — foreground + medium, not muted.
        subSize: "sm",
        subWeight: "medium",
        skeleton: { title: "w-1/3", sub: "w-2/3", hint: "w-1/2" },
    },
}

/** Props for the {@link TitledText} composite. */
export interface TitledTextProps {
    /** Primary line (title / name / label / stat value), rendered through `Typography`. */
    title: string
    /** Optional secondary line beneath the title (subtitle / role / description / stat label). */
    subtitle?: string
    /** Optional third muted line (only meaningful for `size="stat"`, e.g. a delta hint). */
    hint?: string
    /** Text-stack scale. Defaults to `"row"`. */
    size?: TitledTextSize
    /** Override the title weight (per-size default otherwise). */
    weight?: "medium" | "semibold" | "bold"
    /** Truncate every line to a single line (needs a bounded parent width). */
    truncate?: boolean
    /** `true` -> render the skeleton mirror (bars sized per line). */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * TitledText renders a primary line over an optional muted secondary (and hint)
 * as one vertical unit. The composite OWNS the type scale + tone per `size`; the
 * caller passes nodes only. Root is `flex min-w-0 flex-col` so truncation works
 * and callers can add `flex-1`.
 *
 * @param props - {@link TitledTextProps}
 */
export const TitledText = ({
    title,
    subtitle,
    hint,
    size = "row",
    weight,
    truncate = false,
    isSkeleton = false,
    classNames,
}: TitledTextProps) => {
    const cfg = SIZE_CONFIG[size]
    const rootClassNames: Array<AllowedClassName> = ["min-w-0", ...(classNames ?? [])]

    // COMPOSITE-10: ONE render path — same `StackV`, same `gap`, in both states.
    // Text always goes through the `Typography` ATOM; `isSkeleton` just flows
    // straight into it so each line draws its own bar, sized to its own value
    // (§12c) — no second, hand-built skeleton tree to keep in sync with this one.
    return (
        <StackV
            gap={1}
            classNames={rootClassNames}
            isSkeleton={isSkeleton}

            items={[
                () => (
                    <Typography
                        size={cfg.titleSize}
                        weight={isSkeleton ? undefined : (weight ?? cfg.titleWeight)}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        text={title}

                    />
                ),
                ...(subtitle ? [() => (
                    <Typography
                        size={cfg.subSize}
                        color={isSkeleton ? undefined : cfg.subColor}
                        weight={isSkeleton ? undefined : cfg.subWeight}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        text={subtitle}

                    />
                )] : []),
                ...(hint ? [() => (
                    <Typography
                        size="xs"
                        color={isSkeleton ? undefined : "muted"}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        text={hint}

                    />
                )] : []),
            ]}
        />
    )
}

