import React, { useEffect, useMemo, useRef, useState } from "react"
import ReactMarkdown from "react-markdown"
import remarkDirective from "remark-directive"
import remarkGfm from "remark-gfm"
import { cn } from "@heroui/react"
import { buildMarkdownRenderers } from "@sb-components/composites/viewers/MarkdownContent/map"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `MarkdownContent` — a viewer that paints an authored markdown document faithfully. Unlike
 * other composites it cannot know its shape before rendering — the payload decides it. Handles
 * Shiki-highlighted fenced code, mermaid diagrams (click-to-zoom, caption pairing),
 * `:::tab`/`:::code`/`:::preview` -> Preview<->Code tabs, GFM tables -> HeroUI `Table`,
 * `::::accordion`/`:::panel` -> HeroUI `Accordion`, plus `:::muted`/`:::chip`, image captions,
 * link routing, and heading anchors. Leaves by structure are the two spacing measures.
 */

/** How much room the document gets. */
export type MarkdownMeasure = "reading" | "compact"

/**
 * A directive node as `remark-directive` parses it — shared shape for the
 * `:::muted` / `:::tab`/`:::code`/`:::preview` / `::::accordion`/`:::panel`
 * rewriters below (they all only ever read/write these same four fields).
 */
interface DirectiveNode {
    /** mdast node type (`"containerDirective"` / `"leafDirective"` / `"textDirective"` for a directive). */
    type?: string
    /** Directive name as authored (`"muted"`, `"tab"`, `"code"`, `"preview"`, `"chip"`, `"accordion"`, `"panel"`). */
    name?: string
    /** Directive attributes (`{title="…"}`). */
    attributes?: Record<string, string>
    /** hast rewrite instructions (`hName`/`hProperties`) this pass writes into. */
    data?: Record<string, unknown>
    /** Child mdast nodes. */
    children?: Array<unknown>
}

/** A directive's inline content node, as read by {@link collectDirectiveText}. */
interface DirectiveTextNode {
    /** mdast node type (`"text"`, `"break"`, or a container). */
    type?: string
    /** Text value (only on `"text"` nodes). */
    value?: string
    /** Child mdast nodes. */
    children?: Array<unknown>
}

/**
 * Recursively rewrites `:::muted` directives (container/leaf/text, parsed by `remark-directive`)
 * into custom hast tags the renderer map styles as small muted text. Container/leaf -> block-level
 * `mutedblock`; inline `:muted[…]` -> `mutedtext`. Directives with any other name are left untouched
 * (and dropped by the hast conversion since they have no handler).
 * @param node - Current mdast node being walked.
 */
const applyMutedDirective = (node: DirectiveNode): void => {
    if (
        (node.type === "containerDirective" || node.type === "leafDirective" || node.type === "textDirective")
        && node.name === "muted"
    ) {
        const data = node.data || (node.data = {})
        data.hName = node.type === "textDirective" ? "mutedtext" : "mutedblock"
        data.hProperties = {}
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyMutedDirective(child as DirectiveNode)
        }
    }
}

/** remark transformer: turn `:::muted` directives into styled custom tags. */
const remarkMuted = () => (tree: unknown): void => {
    applyMutedDirective(tree as DirectiveNode)
}

/**
 * Recursively rewrites the `:::tab` / `:::code` / `:::preview` container directives into custom
 * hast tags the renderer map turns into a [Preview|Code] tabs block (see `TabsBlock`):
 * `tab`->`tabblock`, `code`->`tabcode`, `preview`->`tabpreview`. Each pane's child fence
 * (` ```tsx ` / ` ```mdx `) still renders through the normal `pre` handler. Other directive names
 * are left untouched.
 *
 * Note: container nesting needs MORE colons on the outer fence — `::::tab` wraps `:::code` /
 * `:::preview`.
 * @param node - Current mdast node being walked.
 */
const applyTabDirective = (node: DirectiveNode): void => {
    if (node.type === "containerDirective") {
        const tag = node.name === "tab"
            ? "tabblock"
            : node.name === "code"
                ? "tabcode"
                : node.name === "preview"
                    ? "tabpreview"
                    : null
        if (tag) {
            const data = node.data || (node.data = {})
            data.hName = tag
            data.hProperties = {}
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyTabDirective(child as DirectiveNode)
        }
    }
}

/** remark transformer: turn `::::tab`/`:::code`/`:::preview` directives into tabs-block tags. */
const remarkTab = () => (tree: unknown): void => {
    applyTabDirective(tree as DirectiveNode)
}

/**
 * Recursively collects the raw text of a directive subtree, preserving line breaks so each
 * authored line (one keyword per line) can be split back out into a separate chip.
 * @param node - Current mdast node.
 */
const collectDirectiveText = (node: DirectiveTextNode): string => {
    if (node.type === "text") {
        return node.value ?? ""
    }
    if (node.type === "break") {
        return "\n"
    }
    if (Array.isArray(node.children)) {
        return node.children
            .map((child) => collectDirectiveText(child as DirectiveTextNode))
            .join("\n")
    }
    return ""
}

/**
 * Rewrites the `:::chip` container directive into a custom `chipblock` tag (see `map.tsx`),
 * carrying its keywords (one per authored line) as a newline-split, `|`-joined `items` prop so the
 * renderer can render each as its own Chip. Other directive names are left untouched.
 * @param node - Current mdast node being walked.
 */
const applyChipDirective = (node: DirectiveNode): void => {
    if (node.type === "containerDirective" && node.name === "chip") {
        const items = collectDirectiveText(node as DirectiveTextNode)
            .split(/[\n·]+/)
            .map((line) => line.trim())
            .filter((line) => line.length > 0)
        const data = node.data || (node.data = {})
        data.hName = "chipblock"
        data.hProperties = {
            items: items.join("|"),
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyChipDirective(child as DirectiveNode)
        }
    }
}

/** remark transformer: turn `:::chip` directives into a chips-row tag. */
const remarkChip = () => (tree: unknown): void => {
    applyChipDirective(tree as DirectiveNode)
}

/**
 * Rewrites the `::::accordion` / `:::panel{title="…"}` container directives into custom hast tags
 * the renderer map turns into a HeroUI Accordion (see `map.tsx`): `accordion`->`accordionblock`;
 * each `:::panel{title="…"}`->`accordionpanel` carrying its `title` attribute. Inner panel content
 * (bullets, code fences) still renders through the normal handlers.
 *
 * Note: nesting needs MORE colons on the outer fence — `::::accordion` wraps `:::panel`.
 * @param node - Current mdast node being walked.
 */
const applyAccordionDirective = (node: DirectiveNode): void => {
    if (node.type === "containerDirective") {
        if (node.name === "accordion") {
            const data = node.data || (node.data = {})
            data.hName = "accordionblock"
            data.hProperties = {}
        } else if (node.name === "panel") {
            const data = node.data || (node.data = {})
            data.hName = "accordionpanel"
            data.hProperties = { title: node.attributes?.title ?? "" }
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) applyAccordionDirective(child as DirectiveNode)
    }
}

/** remark transformer: `::::accordion`/`:::panel` become accordion tags. */
const remarkAccordion = () => (tree: unknown): void => {
    applyAccordionDirective(tree as DirectiveNode)
}

/**
 * Module-level constant — NOT recreated every render. If `remarkPlugins={[...]}` were inline, each
 * `MarkdownContent` re-render would hand `ReactMarkdown` a new array -> re-parse the whole markdown.
 */
const REMARK_PLUGINS = [remarkGfm, remarkDirective, remarkMuted, remarkTab, remarkChip, remarkAccordion]

// Matches each ```mermaid fence and the figure caption paragraph that follows it.
// Group 1 = diagram source; group 2 = the first non-blank line after the fence.
const MERMAID_CAPTION_REGEX = /```mermaid[ \t]*\r?\n([\s\S]*?)\r?\n```[ \t]*\r?\n+[ \t]*([^\r\n]+)/g

/**
 * Cuts off a trailing ```mermaid fence that hasn't been closed yet — markdown fed in
 * progressively (a typewriter reveal, an AI stream) walks THROUGH every partial length of the
 * diagram source one tick at a time, and `mermaid.render()` throws "Syntax error in text" for
 * every one of those incomplete snapshots. Since a reveal only ever GROWS the text, at most the
 * LAST fence can be unterminated — any earlier one already has content (and therefore its closing
 * fence) after it.
 * @param markdown - Raw markdown source, possibly mid-reveal.
 * @returns `markdown` unchanged, or truncated right before an unterminated trailing mermaid fence.
 */
const holdBackIncompleteMermaidFence = (markdown: string): string => {
    const lines = markdown.split("\n")
    let lastOpenLine = -1
    for (let i = 0; i < lines.length; i++) {
        if (/^```mermaid[ \t]*$/.test(lines[i].trimEnd())) {
            lastOpenLine = i
        }
    }
    if (lastOpenLine === -1) {
        return markdown
    }
    const isClosed = lines.slice(lastOpenLine + 1).some((line) => line.trim() === "```")
    return isClosed ? markdown : lines.slice(0, lastOpenLine).join("\n").trimEnd()
}

/**
 * Scans markdown for mermaid blocks and pairs each with the caption paragraph that
 * immediately follows it (a figure-caption line, Vietnamese or English — see the regex below), keyed by trimmed source.
 * @param markdown - Raw markdown source.
 * @returns Caption text keyed by trimmed mermaid source.
 */
const extractMermaidCaptions = (markdown: string): Record<string, string> => {
    const captions: Record<string, string> = {}
    MERMAID_CAPTION_REGEX.lastIndex = 0
    for (let match = MERMAID_CAPTION_REGEX.exec(markdown); match; match = MERMAID_CAPTION_REGEX.exec(markdown)) {
        const code = match[1].trim()
        const caption = match[2].trim().replace(/^\*+|\*+$/g, "").trim()
        if (/^(Hình|Figure)\b/i.test(caption)) { // vn-ok: matches the VI figure word in lesson prose
            captions[code] = caption
        }
    }
    return captions
}

/**
 * Removes each mermaid figure-caption paragraph ("Figure N: …", either language) from the source
 * so it isn't rendered twice — the diagram now shows it as a real `<figcaption>`.
 * @param markdown - Raw markdown source.
 * @returns Markdown with figure-caption paragraphs stripped.
 */
const stripMermaidCaptions = (markdown: string): string => {
    MERMAID_CAPTION_REGEX.lastIndex = 0
    return markdown.replace(MERMAID_CAPTION_REGEX, (match: string, _code: string, caption: string) => {
        const clean = caption.trim().replace(/^\*+|\*+$/g, "").trim()
        if (/^(Hình|Figure)\b/i.test(clean)) { // vn-ok: matches the VI figure word in lesson prose
            return match.slice(0, match.lastIndexOf(caption))
        }
        return match
    })
}

/**
 * Storybook has no `next-themes` provider (unlike `src`) — the toolbar's Light/Dark
 * global instead stamps a `"light"`/`"dark"` class on an ANCESTOR wrapper div (see
 * `.storybook/preview.tsx`). Read it off the DOM the same way `BlockAnatomy` already
 * does (`host.closest(".dark")`), and keep it live with a `MutationObserver` so
 * flipping the toolbar mid-session re-themes Mermaid/Shiki without a remount.
 * @param ref - Ref on (or inside) the element whose nearest themed ancestor to watch.
 */
const useIsDarkTheme = (ref: React.RefObject<HTMLDivElement | null>): boolean => {
    const [isDark, setIsDark] = useState(false)
    useEffect(() => {
        const el = ref.current
        if (!el) {
            return
        }
        const themeHost = el.closest(".light, .dark") ?? document.documentElement
        const read = () => setIsDark(themeHost.classList.contains("dark"))
        read()
        const observer = new MutationObserver(read)
        observer.observe(themeHost, { attributes: true, attributeFilter: ["class"] })
        return () => observer.disconnect()
    }, [ref])
    return isDark
}

/** Props for {@link MarkdownContent}. */
export interface MarkdownContentProps {
    /** The document, as authored. This is the payload that decides the shape. */
    source: string
    /** How much room the document gets. Defaults to `"reading"`. */
    measure?: MarkdownMeasure
    /** Where the article wrapper sits inside its parent, from the closed positioning union. */
    classNames?: Array<AllowedClassName>
    /**
     * `true` -> render a 2-line shimmer mirror instead of the real document
     * (the owner of the shape owns the skeleton).
     */
    isSkeleton?: boolean
}

/**
 * Render an authored markdown document. See the file header for the scope of
 * this port and why a viewer is allowed to write its own spacing.
 *
 * @param props - {@link MarkdownContentProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "MarkdownContent" } as const

const MarkdownContent = ({
    source,
    measure = "reading",
    classNames,
    isSkeleton = false,
}: MarkdownContentProps) => {
    const reading = measure === "reading"
    const rootRef = useRef<HTMLDivElement>(null)
    const isDark = useIsDarkTheme(rootRef)

    // Hold back an unterminated trailing mermaid fence FIRST — see the helper's own JSDoc.
    // Hooks run UNCONDITIONALLY even on a skeleton call (rules of hooks) — `source` is
    // just "" on that path (see the call-site), so this is cheap, not wasted real work.
    const stableSource = useMemo(() => holdBackIncompleteMermaidFence(source), [source])
    const mermaidCaptions = useMemo(() => extractMermaidCaptions(stableSource), [stableSource])
    // Strip mermaid figure-captions — they render as a real `<figcaption>` instead.
    const renderedSource = useMemo(() => stripMermaidCaptions(stableSource), [stableSource])

    const components = useMemo(
        () => buildMarkdownRenderers({ isDark, reading, mermaidCaptions }),
        [isDark, reading, mermaidCaptions],
    )

    // Skeleton mirror owned by THIS composite (§12c) — AFTER every hook above has run
    // (rules of hooks: an early return before a hook call would skip it conditionally).
    if (isSkeleton) {
        return (
            <StackV
                gap={3}
                classNames={classNames}
                isSkeleton={isSkeleton}

                items={[
                    () => <Typography isSkeleton size="base" />,
                    () => <Typography isSkeleton size="base" />,
                ]}
            />
        )
    }

    return (
        <article
            ref={rootRef}

            className={cn("first:*:mt-0 last:*:mb-0", classNames)}
            data-tier="composite"
            data-component="MarkdownContent"
        >
            <ReactMarkdown remarkPlugins={REMARK_PLUGINS} components={components as never}>
                {renderedSource}
            </ReactMarkdown>
        </article>
    )
}

export { MarkdownContent }

import React from "react"
import { cn } from "@heroui/react"
import {
    AccordionTree,
    AccordionTreeBody,
    AccordionTreeHeading,
    AccordionTreeIndicator,
    AccordionTreeItem,
    AccordionTreePanel,
    AccordionTreeTrigger,
} from "@sb-components/atoms/navigation/AccordionTree/AccordionTree"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { CodeToHtml } from "@sb-components/composites/viewers/MarkdownContent/CodeToHtml"
import { MermaidDiagram } from "@sb-components/composites/viewers/MarkdownContent/MermaidDiagram"
import { TabsBlock, TabPane } from "@sb-components/composites/viewers/MarkdownContent/TabsBlock"
import {
    MarkdownTable,
    MarkdownTableBody,
    MarkdownTableCell,
    MarkdownTableColumn,
    MarkdownTableHead,
    MarkdownTableRow,
} from "@sb-components/composites/viewers/MarkdownContent/MarkdownTableParts"
import { Box } from "@sb-components/frames/Box/Box"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * The element-renderer MAP for `MarkdownContent` — the whole grammar (headings,
 * tables, code, mermaid, custom directive tags) in one file.
 *
 * Handles: Shiki syntax highlighting, mermaid diagrams, `:::tab`/`:::code`/
 * `:::preview` -> Preview<->Code tabs, GFM tables -> house `TableRoot`,
 * `::::accordion`/`:::panel` -> house `AccordionTree`, `:::muted`, `:::chip`, image
 * captions, link routing, heading anchors. Not handled here: `arcSections`,
 * `plain` mode, the ` ```mdx ` live-render fence, the ` ```layout ` fence.
 *
 * Vertical rhythm is owned by the single wrapper in `MarkdownContent.tsx`, or in
 * reading measure by a plain `<div className={blockMy}>` around each block-level
 * renderer's output — margin is a seam between two blocks, written where both are
 * visible rather than passed as a `className` prop. `CodeToHtml`,
 * `MermaidDiagram`, and `MarkdownTable` take no `className`.
 */

/** UI copy for the code/table/mermaid chrome. Storybook has no i18n-aware runtime
 * for this tree (see the file header on `MarkdownContent.tsx`), so — like every
 * other composite in this design system — the copy is a hardcoded constant
 * instead of a `useTranslations()` call. Values mirror `src/messages/vi.json`'s
 * `markdown.*` keys so a reader comparing the two sees the same words. */
const TABLE_ARIA_LABEL = "Content table"
const MERMAID_LOADING_LABEL = "Drawing diagram..."
const MERMAID_EXPAND_LABEL = "Expand diagram"
const MERMAID_FALLBACK_LABEL = "Figure"
const HEADING_ANCHOR_LABEL = "Link to this section"

/** Anything the parser hands back with only children — most of the grammar. */
export interface MarkdownNodeProps {
    /** Whatever the parser put inside this element. */
    children?: React.ReactNode
}

/** A link node: the payload decides the target, the viewer only decides the skin. */
export interface MarkdownLinkProps extends MarkdownNodeProps {
    /** Link target as authored. */
    href?: string
}

/** An image node — a raw URL plus its alt text, both straight from the payload. */
export interface MarkdownImageProps {
    /** Image source as authored. */
    src?: string
    /** Alt text as authored; a non-empty alt doubles as a real figure caption. */
    alt?: string
}

/**
 * A code node. A fenced block arrives with `language-*` on react-markdown's
 * `className`; that string is the language hook, not a styling door — stored here
 * as `fenceClass` so COMPOSITE-4 does not see a `className` prop on a `*Props` type.
 */
export interface MarkdownCodeProps extends MarkdownNodeProps {
    /** `language-*` for a fenced block, absent for inline code. */
    fenceClass?: string
}

/** react-markdown still emits `className` on `code`; rename at the renderer boundary. */
type MarkdownCodeRuntimeProps = MarkdownNodeProps & {
    className?: string
}

/** One `:::panel{title="…"}` inside an `::::accordion` block. */
export interface MarkdownPanelProps extends MarkdownNodeProps {
    /** Trigger-row title carried by the directive attribute. */
    title?: string
}

/** The `:::chip` directive's rewritten tag — one `|`-joined line of keywords. */
export interface MarkdownChipBlockProps {
    /** `|`-joined keyword list, one per authored line (see `remarkChip` in `MarkdownContent.tsx`). */
    items?: string
}

/** Config for one {@link buildTocHeading} level. */
interface TocHeadingConfig {
    /** Heading depth surfaced in the outline. */
    level: 2 | 3 | 4
    /** Tailwind text-size class. */
    sizeClass: string
    /** Tailwind margin class (asymmetric — reading measure only). */
    marginClass: string
    /** `true` (reading measure only) -> render the hover `#` deep-link affordance. */
    showAnchor: boolean
}

/**
 * Recursively flattens a React children tree to its plain-text content — used to
 * derive a stable heading slug (and the "on this page" outline label) from the
 * rendered heading nodes.
 * @param node - The React node to read text from.
 * @returns The concatenated text content.
 */
const getNodeText = (node: React.ReactNode): string => {
    if (node === null || node === undefined || typeof node === "boolean") {
        return ""
    }
    if (typeof node === "string" || typeof node === "number") {
        return String(node)
    }
    if (Array.isArray(node)) {
        return node.map(getNodeText).join("")
    }
    if (React.isValidElement(node)) {
        return getNodeText((node.props as MarkdownNodeProps).children)
    }
    return ""
}

/**
 * Slugify heading text into a URL-safe anchor id (diacritics stripped, Vietnamese
 * Vietnamese d-with-stroke folded to `d`, non-alphanumerics collapsed to single hyphens). Deterministic so the
 * rendered heading id and any "on this page" outline reading it from the DOM agree.
 * @param text - The raw heading text.
 * @returns The anchor slug.
 */
const slugify = (text: string): string =>
    text
        .normalize("NFKD")
        .replace(/[̀-ͯ]/g, "")
        .replace(/[đĐ]/g, "d") // vn-ok: slug transliteration of the VI letter
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")

/**
 * Heading renderer factory: renders a section heading carrying a slug `id` +
 * `data-toc` markers so an "on this page" rail can scan the rendered article
 * (`[data-toc]`) and anchor-scroll to it. `scroll-mt-20` clears a sticky navbar
 * when jumped to. The hover `#` deep-link only renders in reading measure — cards
 * / chat / modals have no shareable url for it.
 * @param config - {@link TocHeadingConfig}
 */
const buildTocHeading = ({ level, sizeClass, marginClass, showAnchor }: TocHeadingConfig) =>
    ({ children }: MarkdownNodeProps) => {
        const Tag = `h${level}` as "h2" | "h3" | "h4"
        const text = getNodeText(children)
        const id = slugify(text)
        return (
            <Tag
                id={id}
                data-toc=""
                data-toc-level={level}
                data-toc-label={text}
                className={cn("group scroll-mt-20 font-semibold", marginClass, sizeClass)}
            >
                {children}
                {showAnchor ? (
                    <a
                        href={`#${id}`}
                        aria-label={HEADING_ANCHOR_LABEL}
                        className="ml-2 text-muted no-underline opacity-0 transition-opacity group-hover:opacity-100"
                    >
                        #
                    </a>
                ) : null}
            </Tag>
        )
    }

/** Params for {@link buildMarkdownRenderers}. */
export interface MarkdownRenderersParams {
    /** True when the Storybook toolbar theme is dark; selects mermaid/Shiki themes. */
    isDark: boolean
    /** Reading-grade typography (bigger type, generous rhythm) vs the compact scale. */
    reading: boolean
    /** Figure captions keyed by trimmed mermaid source, paired from the following paragraph. */
    mermaidCaptions: Record<string, string>
}

/**
 * Builds the element-renderer map handed to `ReactMarkdown`. See the file header
 * for scope; each renderer stays margin-free in compact measure (the wrapper in
 * `MarkdownContent.tsx` owns the uniform rhythm there) and carries its own
 * asymmetric margin in reading measure.
 * @param params - {@link MarkdownRenderersParams}
 */
export const buildMarkdownRenderers = ({ isDark, reading, mermaidCaptions }: MarkdownRenderersParams) => {
    const blockMy = reading ? "my-4" : "my-3"
    // Link text rides the same body scale as the surrounding prose.
    const linkSize = reading ? "base" : "sm"

    return {
        h1: ({ children }: MarkdownNodeProps) => (
            <h1 className={cn("font-semibold text-foreground", reading ? "mt-8 mb-3 text-2xl" : "mt-6 mb-2 text-xl")}>{children}</h1>
        ),
        h2: buildTocHeading({
            level: 2,
            sizeClass: reading ? "text-xl" : "text-lg",
            marginClass: reading ? "mt-8 mb-3" : "mt-6 mb-2",
            showAnchor: reading,
        }),
        h3: buildTocHeading({
            level: 3,
            sizeClass: reading ? "text-lg" : "text-base",
            marginClass: reading ? "mt-6 mb-2" : "mt-4 mb-2",
            showAnchor: reading,
        }),
        h4: buildTocHeading({
            level: 4,
            sizeClass: reading ? "text-base" : "text-sm",
            marginClass: reading ? "mt-6 mb-2" : "mt-4 mb-2",
            showAnchor: reading,
        }),
        p: ({ children }: MarkdownNodeProps) => (
            <p className={cn("text-foreground", reading ? "my-3 text-base leading-7" : "my-2 text-sm leading-6")}>{children}</p>
        ),
        ul: ({ children }: MarkdownNodeProps) => (
            <ul className={cn("list-disc pl-6", reading ? "my-3 space-y-1" : "my-2 space-y-1")}>{children}</ul>
        ),
        ol: ({ children }: MarkdownNodeProps) => (
            <ol className={cn("list-decimal pl-6", reading ? "my-3 space-y-1" : "my-2 space-y-1")}>{children}</ol>
        ),
        li: ({ children }: MarkdownNodeProps) => (
            <li className={cn("text-foreground", reading ? "text-base leading-7" : "text-sm leading-6")}>{children}</li>
        ),
        strong: ({ children }: MarkdownNodeProps) => (
            <strong className="font-semibold text-foreground">{children}</strong>
        ),
        em: ({ children }: MarkdownNodeProps) => <em className="italic">{children}</em>,
        // Internal (`/`-prefixed) links stay in the same tab; anything else is external and opens a
        // new tab. Reuses the `Typography` atom's `isLink` branch (HeroUI `Link` + a11y) rather than
        // hand-rolling an `<a>` — the atom already owns exactly this link skin everywhere else.
        a: ({ href, children }: MarkdownLinkProps) => {
            const isInternal = typeof href === "string" && href.startsWith("/")
            return (
                <Typography
                    size={linkSize}
                    isLink
                    href={href}
                    target={isInternal ? undefined : "_blank"}
                    rel={isInternal ? undefined : "noopener noreferrer"}
                    text={children}
                />
            )
        },
        blockquote: ({ children }: MarkdownNodeProps) => (
            <blockquote className={cn("border-l-2 border-default pl-3 text-muted", reading ? "my-4" : "my-3")}>{children}</blockquote>
        ),
        hr: () => <hr className={cn("border-default", reading ? "my-8" : "my-6")} />,
        // Markdown `![caption](src)`: a non-empty alt doubles as a real figure caption; an empty
        // alt renders a bare (decorative) image — same rule `src` uses.
        img: ({ src, alt }: MarkdownImageProps) => (
            alt ? (
                <figure className={blockMy}>
                    <img src={src} alt={alt} className="w-full rounded-2xl" />
                    <figcaption className="mt-2 text-center text-sm italic text-muted">{alt}</figcaption>
                </figure>
            ) : (
                <img src={src} alt="" className={cn("w-full rounded-2xl", blockMy)} />
            )
        ),
        // GFM table -> house `TableRoot` compound (see the file header on `MarkdownTableParts.tsx`
        // for why this is NOT the config-driven `composites/data/Table`). The block-rhythm margin
        // (COMPOSITE-4: `MarkdownTable` takes no `className`) is owned here, by the plain wrapping
        // `<div>` — margin is a seam between two blocks, not a prop of either one.
        table: ({ children }: MarkdownNodeProps) => (
            <div className={blockMy}>
                <MarkdownTable ariaLabel={TABLE_ARIA_LABEL}>{children}</MarkdownTable>
            </div>
        ),
        thead: MarkdownTableHead,
        tbody: MarkdownTableBody,
        tr: MarkdownTableRow,
        th: MarkdownTableColumn,
        td: MarkdownTableCell,
        // A fenced block's inner `code` carries `language-*`; anything else is inline.
        // react-markdown still passes `className`; rename to `fenceClass` at this boundary.
        code: ({ children, className }: MarkdownCodeRuntimeProps) => {
            const fenceClass = className
            if (fenceClass?.startsWith("language-")) {
                return children
            }
            return (
                // inset-exception: inline-code geometry, wider than tall by nature, not a surface inset
                // (same shape as `RichText`'s inline `<code>` — see `RichText.tsx`)
                <Box as="code" principle="control-pad" className="rounded-md bg-default px-1 py-0 font-mono text-sm text-foreground [overflow-wrap:anywhere]"
                    explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                    {children}
                </Box>
            )
        },
        // Fenced block dispatch: `mermaid` -> diagram, everything else -> Shiki.
        pre: ({ children }: MarkdownNodeProps) => {
            const child = React.Children.only(children) as React.ReactElement<MarkdownCodeRuntimeProps>
            const fenceClass = child.props.className
            const lang = /language-(\w+)/.exec(fenceClass ?? "")?.[1] ?? "text"
            const code = String(child.props.children ?? "").replace(/\n$/, "")
            // Block-rhythm margin (COMPOSITE-4: neither viewer takes `className`) owned by the
            // plain wrapping `<div>` — margin is a seam between two blocks, not either one's prop.
            if (lang.toLowerCase() === "mermaid") {
                return (
                    <div className={blockMy}>
                        <MermaidDiagram
                            code={code}
                            theme={isDark ? "dark" : "default"}
                            loadingLabel={MERMAID_LOADING_LABEL}
                            expandLabel={MERMAID_EXPAND_LABEL}
                            caption={mermaidCaptions[code.trim()]}
                            fallbackLabel={MERMAID_FALLBACK_LABEL}
                        />
                    </div>
                )
            }
            return (
                <div className={blockMy}>
                    <CodeToHtml
                        code={code}
                        language={lang}
                        theme={isDark ? "material-theme-darker" : "material-theme-lighter"}

                    />
                </div>
            )
        },
        // Custom `:::muted` directive tags (see `remarkMuted` in `MarkdownContent.tsx`): small,
        // muted label text. `[&_*]:text-muted` forces the muted colour onto any inner `<p>`.
        mutedblock: ({ children }: MarkdownNodeProps) => (
            <div className="text-sm font-semibold text-muted [&_*]:text-muted">{children}</div>
        ),
        mutedtext: ({ children }: MarkdownNodeProps) => (
            <span className="text-sm font-semibold text-muted">{children}</span>
        ),
        // Custom `:::chip` directive tag: a wrapped row of chips, one per authored keyword line.
        // Reuses the `Chip` ATOM (soft/neutral) rather than HeroUI `Chip` directly.
        chipblock: ({ items }: MarkdownChipBlockProps) => (
            <div className="my-2">
                <StackH
                    as="span"
                    at="sm"
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    items={String(items ?? "").split("|").filter(Boolean).map((keyword) => () => (
                        <Chip tone="default" text={keyword} />
                    ))}
                />
            </div>
        ),
        // :::tab -> [ Preview | Code ] tabs; code/preview panes carry `kind` so `TabsBlock` matches them.
        tabblock: ({ children }: MarkdownNodeProps) => <TabsBlock>{children}</TabsBlock>,
        tabcode: ({ children }: MarkdownNodeProps) => <TabPane kind="code">{children}</TabPane>,
        tabpreview: ({ children }: MarkdownNodeProps) => <TabPane kind="preview">{children}</TabPane>,
        // ::::accordion / :::panel{title} -> house `AccordionTree` compound (incremental panels from
        // react-markdown — not the data-driven Disclosure `Accordion` atom). `variant="default"`
        // keeps the item separator FULL-BLEED, with the light hairline `--separator` re-point so
        // dividers read the same as the `SurfaceListCard` family; `border` delineates it as a
        // nested surface.
        accordionblock: ({ children }: MarkdownNodeProps) => (
            // `AccordionTree` omits `className` (atom door is closed); border/rhythm sit on the
            // wrapping seam so COMPOSITE-4 stays clean while the nested-surface look is preserved.
            <div className={cn("overflow-hidden border border-default bg-surface", blockMy)}>
                <AccordionTree
                    variant="default"
                    separatorTone="subtle"
                >
                    {children}
                </AccordionTree>
            </div>
        ),
        accordionpanel: ({ title, children }: MarkdownPanelProps) => (
            <AccordionTreeItem aria-label={String(title ?? "")}>
                <AccordionTreeHeading>
                    <AccordionTreeTrigger>
                        <div className="text-start">
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                justify="between"
                                items={[
                                    () => <span className={reading ? "text-base font-semibold" : "text-sm font-semibold"}>{title}</span>,
                                    () => <AccordionTreeIndicator />,
                                ]}
                            />
                        </div>
                    </AccordionTreeTrigger>
                </AccordionTreeHeading>
                <AccordionTreePanel>
                    <AccordionTreeBody>
                        <div className="space-y-2">{children}</div>
                    </AccordionTreeBody>
                </AccordionTreePanel>
            </AccordionTreeItem>
        ),
    }
}

"use client"

import React from "react"
import type { SVGProps } from "react"
import { TrayIcon, WarningIcon, type Icon as PhosphorIcon } from "@phosphor-icons/react"

import { EmptyState, type EmptyStateIcon } from "@/components/composites/feedback/EmptyState"
// The ATOM `Button`, NOT the `_legacy` version (§0 + teacher, 2026-07-26):
// `AsyncContent` sits in the closure of the `CourseContents` screen, and that screen
// is FORBIDDEN from touching `_legacy` — an import at the composite tier would drag the
// whole dead branch back into the screen (caught by the 2026-07-27 deep-scan).
import { Button } from "@/components/atoms/buttons/Button"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import type { CallerIdentity } from "@/components/frames/_identity"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * STORYBOOK-LOCAL DESIGN SPEC — `AsyncContent.*`, the ONE async-state FRAME
 * namespace (teacher's call, 2026-07-25). Three sibling frames that used to live as
 * three loose folders (`AsyncContent` · `EmptyContent` · `ErrorContent`) are now
 * MEMBERS of one namespace — same tier, same job (holding the lifecycle of ONE
 * async data region: error -> loading -> empty -> content), one import.
 *
 * | Member | Role | Content channel |
 * |---|---|---|
 * | `.Base`  | the STATE-SWITCH frame (4-branch switch) | slot `content`, `skeleton`, `emptyContent`, `errorContent` |
 * | `.Empty` | the EMPTY-MESSAGE frame  | props `title`/`description`/`action` |
 * | `.Error` | the ERROR-MESSAGE frame   | props `title`/`description`/`action` |
 *
 * FRAME API LAW (§13b):
 * - `.Base` is a WRAPPER frame -> the named slot (`content`) is the main path;
 *   the other three branches each get their own named slot (`skeleton` · `emptyContent` ·
 *   `errorContent`).
 * - `.Empty`/`.Error` are props-only MESSAGE frames — NO `children`: they don't
 *   wrap content, they LAY OUT a message (icon · title · description · action)
 *   already translated and passed in by the caller. They carry no domain
 *   text/semantics of their own.
 * - Namespace only — do NOT export a bare component.
 *
 * Each member's behaviour/skin stays VERBATIM from the old folders; this is an
 * API refactor, not a visual one. The one NEW thing: a general `action` slot on
 * `.Empty`/`.Error` (the `onRetry` + `retryLabel` shorthand still works exactly
 * as before). Synced to `src` later.
 * ─────────────────────────────────────────────────────────────────────────────
 */

// ─────────────────────────────────────────────────────────────────────────────
// Shared message-frame plumbing (.Empty / .Error)
// ─────────────────────────────────────────────────────────────────────────────

/** Shared props of the two MESSAGE frames `.Empty` / `.Error`. */
interface MessageProps {
    /** Main line (already translated). `string`, not `ReactNode` — the frame forwards it into `EmptyState`, which renders it (COMPOSITE-8). */
    title: string
    /** Secondary line under the title (already translated). Optional. `string` for the same reason as {@link MessageProps.title}. */
    description?: string
    /**
     * Override the default glyph — takes a **COMPONENT REF** (`icon={TrayIcon}`), NOT
     * JSX. §14b: the caller (especially a SCREEN) must not hold a pre-built node. The
     * frame owns the scale + `weight="duotone"` (§4/§5) so every empty/error in the
     * system speaks with the same glyph voice — the caller only picks "which glyph",
     * not "what it looks like".
     */
    icon?: PhosphorIcon
    /**
     * General ACTION slot below the description — a COMPONENT reference (COMPOSITE-8),
     * never a built node (a `Button`, a two-button cluster…): forwarded straight into
     * `EmptyState`'s own `action` slot, which calls it and forwards `isSkeleton`. WINS
     * over the `onRetry`/`retryLabel` shorthand when both are passed.
     */
    action?: ComponentTypeWithSkeleton
    /** Shorthand: retry handler — only renders a button when PAIRED with `retryLabel`. */
    onRetry?: () => void
    /** Shorthand: the (already translated) label of the retry button — required for the button to appear. `string`, not `ReactNode` (COMPOSITE-8). */
    retryLabel?: string
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * Caller identity to wear on this message frame's root instead of its own — pass this when
     * a `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its own)
     * is using this empty/error message AS its root element, instead of wrapping it in a raw
     * `<div data-tier=… data-component=…>`. See `_identity.ts`. Omitted -> this frame keeps
     * emitting no `data-tier`/`data-component` of its own, unchanged (the nested `EmptyState`
     * still carries ITS OWN composite identity either way — composites always name themselves).
     */
    identity?: CallerIdentity
}

/**
 * Force `weight="duotone"` on the message frame's glyph — §4/§5: the FRAME owns
 * how the glyph looks, the caller only picks which glyph. Before 2026-07-25 the
 * frame took `icon?: ReactNode`, so each caller decided its own weight -> they had
 * already drifted (story duotone, screen not). The old `nodeAsIcon` adapter was
 * removed per its own debt note.
 */
const withDuotone = (Icon: PhosphorIcon): EmptyStateIcon => {
    const Glyph = (props: SVGProps<SVGSVGElement>) => <Icon {...props} weight="duotone" />
    return Glyph
}

/**
 * Resolve the `action` slot's COMPONENT: a free-form `action` component reference
 * wins; otherwise the `onRetry` + `retryLabel` pair is wrapped into a component
 * rendering a secondary size-sm `Button`. Returns a component reference (never a
 * built node, COMPOSITE-8) — `EmptyState` calls it itself, forwarding `isSkeleton`.
 */
const composeAction = ({ action, onRetry, retryLabel }: MessageProps): ComponentTypeWithSkeleton | undefined => {
    if (action) {
        return action
    }
    if (onRetry && retryLabel) {
        return () => (
            <Button
                variant="tertiary"
                size="sm"
                onPress={onRetry}
                label={retryLabel}
            />
        )
    }
    return undefined
}

// ─────────────────────────────────────────────────────────────────────────────
// .Base — the 4-branch state switch (was `AsyncContent`)
// ─────────────────────────────────────────────────────────────────────────────

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "AsyncContent" } as const

/** Props for {@link AsyncContent}. */
export interface AsyncContentBaseProps {
    /**
     * True while the FIRST load is running (no cache yet). While true,
     * {@link AsyncContentBaseProps.skeleton} shows. Pass an already-reduced
     * condition, e.g. `isLoading && items.length === 0`.
     */
    isLoading: boolean
    /**
     * The LOADING branch slot: a COMPONENT reference (COMPOSITE-8), never a built
     * node — a skeleton mirroring the real layout (a `Skeleton.*` tree), so the box
     * doesn't collapse/jump when it resolves. The frame calls it itself, forwarding
     * `isSkeleton={true}`.
     */
    skeleton: ComponentTypeWithSkeleton
    /** True (after loading finishes) -> the frame falls to the empty branch. */
    isEmpty?: boolean
    /**
     * The EMPTY branch slot, passed as PROPS (not a node) — forwarded straight
     * to {@link AsyncContentEmpty}. Left empty -> the empty branch renders null
     * (the section hides itself).
     */
    emptyContent?: AsyncContentEmptyProps
    /**
     * Truthy -> the frame falls to the error branch (HIGHEST PRIORITY, beats
     * even loading). Pass SWR's `error` (only once there's no cache left to show).
     */
    error?: unknown
    /**
     * The ERROR branch slot, passed as PROPS — forwarded straight to
     * {@link AsyncContentError}. WARNING Left empty, the error branch does NOT
     * activate (the frame falls through to loading/empty/content) — keeping the
     * old contract, no behaviour change in this consolidation.
     */
    errorContent?: AsyncContentErrorProps
    /**
     * The CONTENT branch slot — data has finished loading. The wrapper frame's
     * main path. A COMPONENT reference (COMPOSITE-8), never a built node — the
     * frame calls it itself, forwarding `isSkeleton={false}`.
     */
    content?: ComponentTypeWithSkeleton
    /** Dev/spec: overlay an anatomy annotation around the branch currently rendering. */
}

/**
 * The standard STATE-SWITCH frame for every async data region — the ONE place
 * holding the four branches that SWR's render contract demands. Priority order:
 *
 *   error -> loading -> empty -> content
 *
 * The two message branches are configured via PROPS (not a node):
 * `emptyContent={{ title, description, onRetry, retryLabel }}`; `skeleton` is a
 * `Skeleton.*` tree mirroring the real layout.
 *
 * @param props - {@link AsyncContentBaseProps}
 */
const Base = ({
    isLoading,
    skeleton: Skeleton,
    isEmpty = false,
    emptyContent,
    error,
    errorContent,
    content: Content}: AsyncContentBaseProps) => {
    let branch: React.ReactNode
    if (error && errorContent) {
        branch = <ErrorMessage {...errorContent} />
    } else if (isLoading) {
        branch = <Skeleton isSkeleton />
    } else if (isEmpty) {
        branch = emptyContent ? <Empty {...emptyContent} /> : null
    } else {
        branch = Content ? <Content isSkeleton={false} /> : undefined
    }
    return <>{branch}</>
}

// ─────────────────────────────────────────────────────────────────────────────
// .Empty — the empty-message frame (was `EmptyContent`)
// ─────────────────────────────────────────────────────────────────────────────

/** Props for {@link AsyncContentEmpty} — the empty-message frame (props-only). */
export type AsyncContentEmptyProps = MessageProps

/**
 * A standalone EMPTY-MESSAGE frame — tray icon, title + optional description,
 * and an action slot (or the "retry" shorthand), centred. This is the standard
 * `emptyContent` for {@link AsyncContent}.
 *
 * A THIN layer over the `EmptyState` frame: it only adds the default
 * `TrayIcon` and wraps `onRetry`/`retryLabel` into a button for the `action`
 * slot — it does NOT redraw the icon + title + description + button itself.
 *
 * @param props - {@link AsyncContentEmptyProps}
 */
const Empty = (props: AsyncContentEmptyProps) => {
    const { title, description, icon, classNames, identity } = props
    // The caller's identity is FORWARDED to `EmptyState` — the element actually drawn here —
    // never wrapped in a div of our own. A wrapper would be a shape this tier must not draw.
    return (
        <EmptyState
            identity={identity}
            classNames={classNames}
            icon={withDuotone(icon ?? TrayIcon)}
            title={title}
            description={description}
            action={composeAction(props)}
        />
    )
}

// ─────────────────────────────────────────────────────────────────────────────
// .Error — the error-message frame (was `ErrorContent`)
// ─────────────────────────────────────────────────────────────────────────────

/** Props for {@link AsyncContentError} — the error-message frame (props-only). */
export type AsyncContentErrorProps = MessageProps

/**
 * A standalone ERROR-MESSAGE frame — warning icon, title + optional description,
 * and an action slot (usually "retry"), centred. This is the standard
 * `errorContent` for {@link AsyncContent}.
 *
 * A THIN layer over the `EmptyState` frame with `tone="danger"`.
 *
 * @param props - {@link AsyncContentErrorProps}
 */
const ErrorMessage = (props: AsyncContentErrorProps) => {
    const { title, description, icon, classNames, identity } = props
    // Forwarded, not wrapped — same reasoning as `Empty` above.
    return (
        <EmptyState
            identity={identity}
            classNames={classNames}
            tone="danger"
            icon={withDuotone(icon ?? WarningIcon)}
            title={title}
            description={description}
            action={composeAction(props)}
        />
    )
}

/**
 * The FRAME namespace for the async lifecycle — three members, one import:
 *
 * | Member | Content channel |
 * |---|---|
 * | `.Base`  | `content` · `skeleton` · `emptyContent` · `errorContent` |
 * | `.Empty` | props-only (`title`/`description`/`icon`/`action`) |
 * | `.Error` | props-only (`title`/`description`/`icon`/`action`) |
 */
export { Base as AsyncContent, Empty as AsyncContentEmpty, ErrorMessage as AsyncContentError }

import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"
import { type ButtonSize, type ButtonVariant, type IconComponent } from "@/components/atoms/buttons/Button/button-tokens"
import { ResponsiveCluster, type ResponsiveClusterItem } from "@/components/frames/ResponsiveCluster"
import type { ResponsiveRowSwitch } from "@/components/frames/ResponsiveRow"
import type { PrincipleToken, ExplainReason } from "@/components/frames/_principles"
import { PRINCIPLE_STYLE } from "@/components/frames/_principle-style"
import type { AllowedGap, LayoutJustify } from "@/components/frames/_spacing"

/**
 * `ButtonGroup` — a row of buttons described by `items` data: the HOMOGENEOUS case
 * (a filter row, a toolbar of icon buttons, N elements of the same kind). The
 * heterogeneous case (Submit / Save draft / Cancel, three different ROLES) is
 * `ActionBar`, a separate composite.
 *
 * Rebuilt on `ResponsiveCluster`: imports `Button`, renders one per item, and hands
 * the row itself to the frame below — this composite adds no arrangement of its own.
 */

/** One button in a {@link ButtonGroup} — described as data, not JSX. */
export interface ButtonGroupItem {
    /** React key + action identifier. */
    key: string
    /** Button label. Omit for an icon-only button (then `prefixIcon` + `ariaLabel` are required). */
    label?: string
    /** Icon component — leading glyph when `label` is set, sole glyph otherwise. */
    prefixIcon?: IconComponent
    /** Accessible name — required when there is no `label`. */
    ariaLabel?: string
    /** Action intent → variant. Default `primary`. */
    variant?: ButtonVariant
    onPress?: () => void
    isDisabled?: boolean
    /** `true` marks this button busy: spinner + locked press, scoped to this button only. */
    isPending?: boolean
}

/** Props for {@link ButtonGroup} — a row cluster of buttons. */
export interface ButtonGroupProps {
    /** The row's buttons, described as data. An item with `label` renders labeled; without, icon-only. */
    items: Array<ButtonGroupItem>
    /** Scale shared by the whole row (default `md`) — every button in a cluster is the same size. */
    size?: ButtonSize
    /** `true` renders a skeleton mirroring the item count (pill/square per item). */
    isSkeleton?: boolean
    /**
     * Layout seam for this control row. Default `flex-action`.
     * Use `flex-action-end` / `flex-action-start` / `flex-action-between` when the
     * main-axis distribution is part of the meaning (form closing rows).
     */
    principle?: PrincipleToken
    /**
     * Why this layer exists - one sentence, forwarded to the owning cluster beside `principle`.
     */
    explain?: ExplainReason
    /**
     * Container step this row leaves the full-width column for the packed row at.
     * Default `sm` — a button row needs far less room than a page split to pack.
     */
    at?: ResponsiveRowSwitch
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** Component-tier metadata for `ButtonGroup` — registers it as a composite named `ButtonGroup`. */
export const meta = { tier: "composite", name: "ButtonGroup" } as const

/** A responsive row of same-size buttons that packs into a cluster below the given breakpoint. */
export const ButtonGroup = ({
    items,
    size = "md",
    isSkeleton = false,
    principle = "flex-action",
    explain,
    at = "sm",
    classNames,
}: ButtonGroupProps) => {
    const entry = PRINCIPLE_STYLE[principle]
    const gap: AllowedGap = entry.kind === "gap" ? entry.step : 3
    const justify: LayoutJustify | undefined = entry.kind === "gap" ? entry.justify : undefined
    return (
        <ResponsiveCluster
            data-tier="composite"
            data-component="ButtonGroup"
            at={at}
            gap={gap}
            principle={principle}
            explain={explain}
            justify={justify}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={items.map((item): ResponsiveClusterItem => {
                const shared = {
                    variant: item.variant,
                    size,
                    onPress: item.onPress,
                    isDisabled: item.isDisabled,
                    isPending: item.isPending,
                } as const
                const { label, prefixIcon, ariaLabel } = item
                if (label != null) {
                    return {
                        key: item.key,
                        content: ({ isSkeleton: skeleton }: SkeletonProps) => (
                            <Button label={label} prefixIcon={prefixIcon} isSkeleton={skeleton} {...shared} />
                        ),
                    }
                }
                if (prefixIcon != null) {
                    return {
                        key: item.key,
                        content: ({ isSkeleton: skeleton }: SkeletonProps) => (
                            <Button
                                isIconOnly
                                prefixIcon={prefixIcon}
                                ariaLabel={ariaLabel ?? ""}
                                isSkeleton={skeleton}
                                {...shared}
                            />
                        ),
                    }
                }
                return { key: item.key, content: () => null }
            })}
        />
    )
}

import React from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"
import { Button } from "@/components/atoms/buttons/Button"
import {
    ButtonGroupRoot,
    ButtonGroupSeparator,
} from "@/components/atoms/buttons/ButtonGroup"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"

/**
 * `Button.RadioGroup` — a flex-wrap row of selectable buttons, single- or multi-select.
 * Leaves: `items` builds N child buttons (`Default`, with per-item `isDisabled`); `multiple`
 * allows ≥2 selected at once; `trailing` appends a non-option button (e.g. "+N"); `itemAction`
 * turns each item into a fused `ButtonGroup` [select | delete | more].
 */

interface CloneableActionElementProps {
    children?: ReactNode
}

/** One selectable button in a {@link ButtonRadioGroup}. */
export interface ButtonRadioGroupItem<T extends string> {
    /** Value selected when this button is chosen. */
    value: T
    /** Button content (icon + label + meta — caller-defined inline row). */
    content: ReactNode
    /** When true the button is dimmed and not selectable. */
    isDisabled?: boolean
}

/** Props shared by both the single- and multi-select modes of {@link ButtonRadioGroup}. */
interface ButtonRadioGroupBaseProps<T extends string> {
    /** The selectable buttons. */
    items: Array<ButtonRadioGroupItem<T>>
    /** Accessible label for the group. */
    ariaLabel: string
    /**
     * Optional trailing node placed after the buttons in the SAME row (e.g. a
     * "+N" overflow button). Not part of the group's value — it's an action.
     */
    trailing?: ReactNode
    /**
     * Optional per-item trailing action(s) — e.g. a delete button and/or a "⋮"
     * (kebab) menu trigger. When provided, the item's select button and these
     * action buttons render as ONE connected `ButtonGroup` per item
     * (`[select | delete | ⋮]`). Return the action `<Button>`s as an ARRAY (with
     * `key`s) so each is an individual segment. Omit for a plain single-select row.
     */
    itemAction?: (item: ButtonRadioGroupItem<T>) => ReactNode
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** Single-select mode (default) — exactly one value selected at a time. */
interface ButtonRadioGroupSingleProps<T extends string> extends ButtonRadioGroupBaseProps<T> {
    /** Single-select — omit or pass `false`. */
    multiple?: false
    /** Currently selected value. */
    value: T
    /** Fired with the chosen value when a button is selected. */
    onChange: (value: T) => void
}

/**
 * Multi-select mode — a SET of values, each button an independent toggle. The
 * caller owns the set + the toggle logic (e.g. enforcing "at least one selected");
 * this component only reports which button was pressed via {@link onToggle}.
 */
interface ButtonRadioGroupMultiProps<T extends string> extends ButtonRadioGroupBaseProps<T> {
    /** Multi-select — pass `true`. */
    multiple: true
    /** Currently selected values. */
    values: Array<T>
    /** Fired with the pressed value (the caller adds/removes it from its own set). */
    onToggle: (value: T) => void
}

/** Props for {@link ButtonRadioGroup} — a discriminated union on `multiple`. */
export type ButtonRadioGroupProps<T extends string> =
    | ButtonRadioGroupSingleProps<T>
    | ButtonRadioGroupMultiProps<T>

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "ButtonRadioGroup" } as const

/**
 * A single-select toggle-button group laid out as a flex-wrap row (buttons wrap
 * to the next line, never scroll). Every option is a house `<Button>`:
 * standalone, selected = filled `tertiary` (NEUTRAL, not accent — a facet/config
 * toggle isn't a CTA), unselected = hollow `ghost`. NEVER `primary` here — a config
 * row commonly sits on the SAME surface as the page's one accent CTA.
 *
 * When `itemAction` is supplied, each item instead renders as one connected
 * `ButtonGroup` — the select button + its action button(s) touching, only the
 * two outer ends rounded (`[select | delete | ⋮]`). The seam is the house
 * `ButtonGroupSeparator`, baked to the `--border` token and full-height.
 *
 * `role="group"` + `aria-pressed` per option — works for BOTH the default
 * single-select toggle group and the multi-select mode. House `Button` does not
 * accept `aria-pressed`, so the standalone path wraps the control in a span;
 * the fused `ButtonGroupRoot` path cannot wrap (segments must be buttons), so
 * pressed state is carried only on the standalone span.
 *
 * @param props - {@link ButtonRadioGroupProps}
 */
export const ButtonRadioGroup = <T extends string>(props: ButtonRadioGroupProps<T>) => {
    const { items, ariaLabel, trailing, itemAction, classNames } = props
    // narrow the discriminated union once — selection state + the press handler are
    // the only things that differ between single- and multi-select.
    const isSelected = (candidate: T): boolean =>
        (props.multiple ? props.values.includes(candidate) : props.value === candidate)
    const onPress = (candidate: T): void => {
        if (props.multiple) {
            props.onToggle(candidate)
        } else {
            props.onChange(candidate)
        }
    }
    return (
        <div
            role="group"
            aria-label={ariaLabel}
            className={cn("flex flex-wrap items-center gap-2", classNames)}
            data-tier="composite"
            data-component="ButtonRadioGroup"
            data-principle="flex-action"
        >
            {items.map((item) => {
                const selected = isSelected(item.value)
                if (!itemAction) {
                    // standalone: selected = filled `tertiary`, unselected = hollow `ghost`.
                    return (
                        <span key={item.value} aria-pressed={selected}>
                            <Button
                                size="sm"
                                variant={selected ? "tertiary" : "ghost"}
                                isDisabled={item.isDisabled}
                                onPress={() => onPress(item.value)}
                                label={item.content}
                            />
                        </span>
                    )
                }
                // select button + its action(s) = one connected ButtonGroup per item.
                // Each action button gets a `ButtonGroupSeparator` injected at the head
                // of its children — the separator must sit inside the following button.
                return (
                    <ButtonGroupRoot key={item.value} size="sm">
                        <Button
                            size="sm"
                            variant={selected ? "secondary" : "tertiary"}
                            isDisabled={item.isDisabled}
                            onPress={() => onPress(item.value)}
                            label={item.content}
                        />
                        {React.Children.map(itemAction(item), (action) =>
                            React.isValidElement<CloneableActionElementProps>(action)
                                ? React.cloneElement(
                                    action,
                                    undefined,
                                    <ButtonGroupSeparator />,
                                    action.props.children,
                                )
                                : action,
                        )}
                    </ButtonGroupRoot>
                )
            })}
            {trailing}
        </div>
    )
}

