     */
    classNames?: Array<AllowedClassName>
}

/**
 * A bottom-right floating action button — a round, shadowed accent circle. COMPOSES
 * the base `<Button iconOnly>` atom (§6): the atom owns the icon-only look,
 * native icon sizing (§5a) and interaction; this block only layers the fixed
 * placement, round shape, shadow and z-index. Pure + props-only.
 *
 * @param props - {@link FloatingActionButtonProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "FloatingActionButton" } as const

/** A bottom-right floating action button that composes the icon-only `Button` atom. */
export const FloatingActionButton = ({
    onPress,
    ariaLabel,
    icon: Icon,
    isSkeleton = false,
    classNames,
}: FloatingActionButtonProps) => {
    return (
        <div
            className={cn(
                "fixed bottom-6 right-[calc(var(--app-rail-w,0px)+1.5rem)] z-40",
                classNames,
            )}
        >
            <Button
                isIconOnly
                variant="primary"
                ariaLabel={ariaLabel}
                onPress={onPress}
                // `icon` is optional (the "icon unset" state is a bare circle); the atom
                // renders no glyph when `prefixIcon` is undefined (guarded), so the cast
                // only bridges the isIconOnly type which demands a definite component.
                prefixIcon={Icon as IconComponent}
                isSkeleton={isSkeleton}
                isElevated
            />
        </div>
    )
}

import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import type { IconComponent } from "@/components/atoms/buttons/Button/button-tokens"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { StackH } from "@/components/frames/Stack"

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "InputButtonLike" } as const

/**
 * `InputButtonLike` — a button disguised as an input field: it carries the house
 * `Button` `variant="field"` look (rounded shell, field background + border, muted
 * placeholder) but behaves as a single press target with no inner dividers, so it
 * can trigger an overlay (a global search dialog, a command palette) instead of
 * accepting typed input. Leaves: `icon`, `suffix`, `size`, `isSkeleton`, `placeholder`.
 */

export type InputButtonLikeSize = "sm" | "md" | "lg"

// Placeholder text-size expressed as a `Typography` size — lets the skeleton
// branch hand the SAME scale to the atom instead of a hand-copied class.
const TYPOGRAPHY_SIZE: Record<InputButtonLikeSize, "xs" | "sm" | "base"> = {
    sm: "xs",
    md: "sm",
    lg: "base",
}

/**
 * Props for the {@link InputButtonLike} block.
 */
export interface InputButtonLikeProps {
    /**
     * Placeholder-style label, rendered muted like an empty input value. Plain
     * text — the block wraps it itself, so it can also draw the skeleton bar
     * in its place.
     */
    placeholder: string
    /**
     * Optional leading icon (e.g. a magnifier), passed as a COMPONENT reference
     * (not built JSX) — the block calls it itself and owns its size (§5a) and
     * muted color.
     */
    icon?: IconComponent
    /**
     * Optional trailing region pinned to the right (e.g. a Kbd shortcut hint),
     * passed as a COMPONENT reference so the block can withhold it while loading.
     */
    suffix?: ComponentTypeWithSkeleton
    /** Control height/typography scale. Defaults to `md` (field height h-9). */
    size?: InputButtonLikeSize
    /**
     * Accessible label for the control. Falls back to {@link placeholder} when omitted.
     */
    ariaLabel?: string
    /**
     * Press handler — opens whatever the field stands in for (e.g. a search overlay).
     */
    onPress: () => void
    /** `true` → skeleton mirror (field-shaped bar, same height per size). */
    isSkeleton?: boolean
}

/**
 * A button disguised as an input field. It carries the house `Button`
 * `variant="field"` look — rounded-field shell, field background + border,
 * muted placeholder text — but behaves as a single press target with no inner
 * dividers, so it can trigger an overlay/command palette instead of accepting
 * typed input. Pure and props-only: the block owns the entire look — including
 * icon size (§5a) and muted color; consumers pass only raw content + a press
 * handler (and placement via classNames).
 *
 * ONE render path (§12c): the field shell stays real throughout — same
 * height/border/shadow whether loading or not, "a field that is loading is
 * still a field". Only the placeholder LABEL keeps its own bar via
 * `Typography` while loading; the leading icon and trailing `suffix` are
 * omitted while loading, and the press is locked. House `Button.isSkeleton` is
 * NEVER set here — that would replace the field chrome with a pill shimmer.
 */
export const InputButtonLike = ({
    placeholder,
    icon: Icon,
    suffix: Suffix,
    size = "md",
    ariaLabel,
    onPress,
    isSkeleton = false,
    
}: InputButtonLikeProps) => {
    const placeholderLabel = (
        <Typography
            size={TYPOGRAPHY_SIZE[size]}
            isSkeleton={isSkeleton}
            text={placeholder}
            color="muted"
            truncate
        />
    )

    const label = !isSkeleton && Suffix ? (
        <StackH
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            justify="between"
            align="center"
            classNames={["w-full", "min-w-0"]}
            items={[
                () => placeholderLabel,
                () => (
                    <span className="shrink-0">
                        <Suffix isSkeleton={isSkeleton} />
                    </span>
                ),
            ]}
        />
    ) : (
        placeholderLabel
    )

    return (
        <div data-tier="composite" data-component="InputButtonLike">
            <Button
                variant="field"
                size={size}
                ariaLabel={ariaLabel ?? placeholder}
                onPress={isSkeleton ? undefined : onPress}
                isDisabled={isSkeleton}
                prefixIcon={!isSkeleton && Icon ? Icon : undefined}
                label={label}
            />
        </div>
    )
}

import React from "react"
import { cn } from "@heroui/react"
import { LinkSeeMore } from "@/components/atoms/navigation/Link"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH } from "@/components/frames/Stack"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"

/**
 * The shared header of the `Surface*Card` family. Imported by SurfaceCard,
 * SurfaceListCard, and SurfaceAccordionCard so all three share ONE header.
 */

/** Shared label props every `Surface*Card` accepts to render a header above the surface. */
export interface SurfaceLabelProps {
    /**
     * Section title rendered OUTSIDE (above) the surface. Omit → no header.
     *
     * `string`, not `ReactNode` (COMPOSITE-8): the header wraps it in `Typography`
     * itself, so `isSkeleton` can reach the text it renders instead of arriving as
     * an already-built node it cannot reopen.
     */
    label?: string
    /** Passive muted tag pinned RIGHT of the label (a unit/count/currency), NOT an action. Text — see {@link SurfaceLabelProps.label}. */
    labelEnd?: string
    /** Renders a right-aligned see-more link (semibold accent + hover caret). */
    onSeeMore?: () => void
    /** Text for the see-more link. Defaults to "See more". */
    seeMoreLabel?: string
    /**
     * Arbitrary right-aligned slot (a manage button). Wins over `onSeeMore` and
     * `labelEnd`.
     *
     * A COMPONENT reference, not a built node (COMPOSITE-8) — the header calls it
     * with `isSkeleton` so it can build its own resting state, the same way it
     * calls every other slot it renders.
     */
    action?: ComponentTypeWithSkeleton
    /** Render the label as a SUBTLE eyebrow (`text-xs text-muted`, tighter gap). */
    subtleLabel?: boolean
    /**
     * `true` → the header row is in the RESTING state: `label` and the slot must turn
     * into shimmer.
     *
     * The flag flows DOWN FROM the parent frame (`SurfaceCard.*`) — the header doesn't
     * know on its own; whoever owns the shape owns that shape's resting state (§12c).
     * The header still keeps the EXACT real line box (`sm` 20px · `xs` 16px) so the
     * layout doesn't jump when data arrives (§8).
     */
    isSkeleton?: boolean
}

/**
 * The label row shared by every `Surface*Card`. Returns `null` when `label` is
 * omitted so a surface with no header renders bare.
 *
 * @param props - {@link SurfaceLabelProps}
 */
export const SurfaceCardHeader = ({
    label,
    labelEnd,
    onSeeMore,
    seeMoreLabel = "See more",
    action: Action,
    subtleLabel = false,
    isSkeleton = false,
}: SurfaceLabelProps) => {
    if (label == null) return null
    // Both sides of the row follow `subtleLabel` for text size — ONE shared variable
    // so the two sides can never drift apart.
    const textSize = subtleLabel ? "xs" : "sm"
    // Text goes through the ATOM (§9c), NOT HeroUI `Label` or a `<span>` with
    // classes slapped on. `Label` renders exactly 14px/500/lh-20 =
    // `size="sm" weight="medium"` so the shape doesn't change — but because
    // it's an atom, `isSkeleton` FLOWS STRAIGHT into it instead of forcing
    // the header row to branch off and build its own shimmer bar.
    const labelSlot = (
        <Typography
            size={textSize}
            weight={subtleLabel ? undefined : "medium"}
            color={subtleLabel ? "muted" : undefined}
            truncate
            isSkeleton={isSkeleton}
            text={label}
        />
    )
    const endSlot = Action ? <Action isSkeleton={isSkeleton} /> : (onSeeMore ? (
        // This is an ATOM with its own story ⇒ the node is named so it becomes a
        // clickable DEP in the panel; the badge stops here, no drilling into the
        // atom's insides (§11a).
        <span className="shrink-0">
            <LinkSeeMore onPress={onSeeMore} size={textSize} label={seeMoreLabel} />
        </span>
    ) : labelEnd != null ? (
        // Also goes through the atom, same reason — the flag keeps flowing, not branching.
        <Typography
            size={textSize}
            color="muted"
            isSkeleton={isSkeleton}
            text={labelEnd}
        />
    ) : null)
    return (
        <StackH
            gap={4}
            justify="between"
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                () => <StackH gap={3} classNames={["min-w-0"]} items={[() => labelSlot]} />,
                () => endSlot,
            ]}
        />
    )
}

/** The `gap` between a {@link SurfaceCardHeader} and its surface — `gap-2` subtle, `gap-3` full. */
export const surfaceSectionGap = (subtleLabel: boolean | undefined) => (subtleLabel ? "gap-2" : "gap-3")

/**
 * Three frame variants of a `Surface*Card` face:
 * - `"surface"` (default) — `shadow-surface`, used when the parent is a bare
 *   `bg-background`.
 * - `"nested"` — a border REPLACES the shadow (`border border-default`, shadow
 *   dropped) — used when this face sits INSIDE another face (a `bg-surface`
 *   panel, a `bg-surface-secondary` bubble, a modal/page card): the shadow sinks
 *   into the parent face so the signal switches to a border instead.
 */
export type SurfaceCardVariant = "surface" | "nested"

/**
 * The shared `Surface*Card` frame class — `rounded-3xl bg-surface` + a BORDER XOR the
 * elevation SHADOW (`variant="nested"` = surface-in-surface: a border replaces the
 * shadow that renders invisible on a parent surface). Callers add their own
 * `overflow-hidden` / padding.
 */
export const surfaceFrame = (variant: SurfaceCardVariant = "surface") =>
    cn("rounded-3xl bg-surface", variant === "nested" ? "border border-default" : "shadow-surface")

import type { ReactNode } from "react"
import { cn } from "@heroui/react"
import {
    TableRoot,
    TableScrollContainer,
    TableContent,
    TableHeader,
    TableBody,
    TableColumn,
    TableRow,
    TableCell,
} from "@/components/atoms/data/Table"
import { Typography } from "@/components/atoms/text/Typography"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Box } from "@/components/frames/Box"

/**
 * `Table` — a table frame. Owns the column configuration (`columns`: alignment + width),
 * building rows from `items`, and the three frame states of a list: empty (`emptyContent`),
 * loading (`isSkeleton`), and pressable rows (`onRowPress`). Does not format content — every
 * cell is a `ReactNode` the consumer passes in.
 */

/** Which edge a column's content aligns to (reading start, or the right edge for numbers/actions). */
export type TableAlign = "start" | "end"

/** Declares ONE column — data configuration, not a JSX child. */
export interface TableColumnSpec {
    /** Column key: both the React key and the key used to read the cell in each `item`. */
    key: string
    /**
     * Column header text. `string`, not `ReactNode` (COMPOSITE-8): the frame renders it through
     * the `Typography` atom itself rather than accepting an already-built node it cannot reopen.
     */
    header: string
    /** Content alignment for the column (applies to BOTH the header and every cell). Default `start`. */
    align?: TableAlign
    /** Fixed CSS width for the column (`"96px"`, `"20%"`). Omit to size to content. */
    width?: string
}

/**
 * ONE row: `key` (React key + row id) plus one node for EVERY `column.key`.
 * Already-formatted nodes — the frame knows nothing about the domain.
 *
 * COMPOSITE-8 note: cell values remain `ReactNode` on this pre-existing item shape
 * (`TableRowItem = Record<string, ReactNode>`). Not redesigned in the COMPOSITE-3/10 batch.
 */
export type TableRowItem = Record<string, ReactNode> & { key: string }

/** Props for {@link Table}. */
export interface TableBaseProps {
    /** Column configuration, in reading order. The first column is the row-header (a11y). */
    columns: ReadonlyArray<TableColumnSpec>
    /** The rows. REQUIRED — a repeated list is data, never children (§13b). */
    items: ReadonlyArray<TableRowItem>
    /**
     * The table's name for screen readers. REQUIRED: react-aria's `Table` has no
     * implicit label — omitting it reads the whole table as nameless (tsc/eslint do NOT catch this).
     */
    ariaLabel: string
    /**
     * Rendered INSIDE the table body when `items` is empty — so "empty" reads as
     * intentional. Takes a COMPONENT reference (COMPOSITE-8): the frame calls it,
     * forwarding `isSkeleton`, rather than receiving an already-built node it cannot shimmer.
     */
    emptyContent?: ComponentTypeWithSkeleton
    /**
     * `true` → keeps the REAL frame + header, replaces every cell with a skeleton
     * bar instead (§8 keeps the container real). Mirror row count = `items.length`,
     * or `3` when empty.
     */
    isSkeleton?: boolean
    /** A handler set → every row becomes a press target (react-aria row action), receiving `item.key`. */
    onRowPress?: (key: string) => void
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Table" } as const

/** Default mirror row count when there is no data yet to count. */
const SKELETON_ROWS_FALLBACK = 3

/** Content alignment — set on the CHILD span (wins over inheritance), see the file header note. */
const ALIGN_CLS: Record<TableAlign, string> = {
    start: "text-start",
    end: "text-end",
}

/** Wraps one cell/header's content so the FRAME owns alignment (§4), instead of it leaking to the call site. */
/** Params for the local {@link CellBox} — one table cell's alignment wrapper (internal, not a public slot). */
interface CellBoxArgs {
    /** Horizontal alignment of the cell content. */
    align?: TableAlign
    /** Cell content. */
    children: ReactNode
}

const CellBox = ({ align, children }: CellBoxArgs) => (
    <span className={cn("block", ALIGN_CLS[align ?? "start"])}>{children}</span>
)

/**
 * Table frame: a `columns` configuration + an `items` array, the frame builds its
 * own header/rows/cells. Empty → `emptyContent`; loading → mirrors the skeleton
 * within the same frame; `onRowPress` set → rows become press targets (a11y handled by react-aria).
 *
 * @param props - {@link TableBaseProps}
 */
const TableBase = ({
    columns,
    items,
    ariaLabel,
    emptyContent: EmptyContent,
    isSkeleton = false,
    onRowPress,
    classNames,
}: TableBaseProps) => {
    // The header is CONFIGURATION (known before any data arrives) → the skeleton keeps
    // the REAL header, only cells become bars; the frame/column widths never jump once data lands (§8).
    const header = (
        <TableHeader>
            {columns.map((column, index) => (
                <TableColumn
                    key={column.key}
                    id={column.key}
                    isRowHeader={index === 0}
                    style={column.width != null ? { width: column.width } : undefined}

                >
                    <CellBox align={column.align}>
                        <Typography size="sm" text={column.header} />
                    </CellBox>
                </TableColumn>
            ))}
        </TableHeader>
    )

    const body = isSkeleton ? (
        <TableBody>
            {Array.from({ length: items.length || SKELETON_ROWS_FALLBACK }).map((_, rowIndex) => (
                <TableRow key={rowIndex} id={`skeleton-${rowIndex}`}>
                    {columns.map((column) => (
                        <TableCell key={column.key}>
                            {/* The bar is 14px tall < the real cell's 20px line-height → wrap it in an>
                                `h-5` box so the mirror row is the EXACT height of a real row (§8, no
                                layout jump). Balance the height with `items-center`, NOT with margin
                                (§10a). The tag sits OUTSIDE the atom (the atom takes no rest props) —
                                same reason as `CellBox`. */}
                            <span className="flex h-5 items-center">
                                <Typography size="sm" isSkeleton />
                            </span>
                        </TableCell>
                    ))}
                </TableRow>
            ))}
        </TableBody>
    ) : (
        <TableBody

            renderEmptyState={
                EmptyContent != null
                    ? () => (
                        <Box principle="page-pad"
                            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                            className="text-center">
                            <EmptyContent isSkeleton={isSkeleton} />
                        </Box>
                    )
                    : undefined
            }
        >
            {items.map((item) => (
                <TableRow
                    key={item.key}
                    id={item.key}
                    onAction={onRowPress != null ? () => onRowPress(item.key) : undefined}

                >
                    {columns.map((column) => (
                        <TableCell key={column.key}>
                            <CellBox align={column.align}>{item[column.key]}</CellBox>
                        </TableCell>
                    ))}
                </TableRow>
            ))}
        </TableBody>
    )

    return (
        // House `TableRoot` omits `className` — placement classes ride a plain wrapper.
        <div className={cn(classNames)} data-tier="composite" data-component="Table">
            <TableRoot variant="primary">
                <TableScrollContainer>
                    <TableContent aria-label={ariaLabel}>
                        {header}
                        {body}
                    </TableContent>
                </TableScrollContainer>
            </TableRoot>
        </div>
    )
}

/**
 * `Table.*` — data-table frame (COMPOSITE tier §13). `Base` is the only shape;
 * variants (alignment, width, empty, loading, pressable rows) are PROPS on it (§6b).
 */
export { TableBase as Table }

import type { ComponentType, SVGProps } from "react"
import { Alert, type AlertStatus } from "@/components/atoms/feedback/Alert"
import { Button } from "@/components/atoms/buttons/Button"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * STORYBOOK-LOCAL DESIGN SPEC — `Callout`, a tinted flat strip LIVING INSIDE a
 * surface (`title`/`description`/`body`/`action`).
 *
 * WARNING Split out of the `Feedback.*` namespace (2026-08-01) back into its own flat
 * file — the 2026-07-25 consolidation grouped `Callout`/`Empty`/`Confirm` under
 * one `Feedback` folder; this reverses that so each frame is discoverable by
 * its own name again. Props/behaviour are UNCHANGED — this is a file-location +
 * naming refactor, not a visual or API change.
 *
 * ATOM COMPOSITION (§12): text goes through `Typography.*`, buttons through
 * `Button.*`, icons come from `@phosphor-icons/react` — ONE SET ONLY (§50),
 * passed as a component ref, the frame forces size/weight itself (§4/§5).
 * DELIBERATE EXCEPTION: keeps HeroUI's `Alert.Title`/`Alert.Description`
 * because HeroUI itself carries the COLOR-BY-STATUS contract (`.alert--warning
 * .alert__title` -> `text-warning-soft-foreground`). Swapping in `Typography` would
 * mean hand-feeding a color table — that's the real "hand-rolled". Switch to the
 * atom once an `Alert` atom exists.
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Callout" } as const

/** Semantic tone — the atom's `AlertStatus` re-exported under this frame's name. */
export type CalloutStatus = AlertStatus

/** Icon passed as a COMPONENT (phosphor), never JSX — the frame owns its scale (§4/§5). */
export type CalloutIcon = ComponentType<SVGProps<SVGSVGElement>>

/**
 * Action button bg/text per status — SOLID `bg-<status>` CTA against the lighter
 * tint. INTERNAL: the CTA lived in the caller's `action` slot in the old shape,
 * so the caller had to hold `Button` and apply the skin itself. Now the frame
 * builds the button ITSELF from `actionLabel`/`onAction` => the caller
 * (especially a SCREEN) no longer touches the atom.
 */
const CALLOUT_ACTION_CLASS: Record<CalloutStatus, string> = {
    default: "bg-foreground text-background",
    accent: "bg-accent text-accent-foreground",
    success: "bg-success text-success-foreground",
    warning: "bg-warning text-warning-foreground",
    danger: "bg-danger text-danger-foreground",
    info: "bg-info text-info-foreground",
}

/** Props SPECIFIC to {@link Callout} — EXCEPT the `title`/`isSkeleton` pair (see {@link CalloutProps}). */
interface CalloutOwnProps {
    /** Semantic tone (drives tint + icon/title colour). Default `"default"`. */
    status?: CalloutStatus
    /**
     * Optional supporting line under the title — the body TEXT slot. `string`,
     * not `ReactNode` (COMPOSITE-8) — forwarded straight into `Alert`, which
     * renders it (or a shimmer bar in its place) itself.
     */
    description?: string
    /**
     * Optional free-form body region under `description` (a short list, a meta
     * row). A COMPONENT reference, not a built node (COMPOSITE-8) — the frame
     * calls it itself with `isSkeleton` forwarded before handing the result to
     * `Alert`'s own `body` slot.
     */
    body?: ComponentTypeWithSkeleton
    /** Optional custom indicator icon as a COMPONENT; omit for the status default. */
    icon?: CalloutIcon
    /**
     * CTA label (footer slot). The frame builds the button ITSELF and applies the
     * skin per `status` — the caller only supplies TEXT, not a `Button` (a screen
     * must not hold the atom).
     */
    actionLabel?: string
    /** Handler for the CTA; the button only shows once `actionLabel` is also present. */
    onAction?: () => void
    /** When provided, renders a status-coloured close (×) wired to this. */
    onClose?: () => void
    /** Accessible label for the close button. */
    closeAriaLabel?: string
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * `isSkeleton` is a co-located loading state — forwarded straight into `Alert`,
 * which owns drawing the shimmer bars. `title` is optional only in the
 * `isSkeleton: true` branch; the live branch still requires it. `string`, not
 * `ReactNode` (COMPOSITE-8) — the frame hands it to `Alert`'s own `title` slot.
 */
export type CalloutProps = CalloutOwnProps &
    (
        | { isSkeleton: true; title?: string }
        | { isSkeleton?: false; title: string }
    )

/**
 * A tinted, flat note for use INSIDE a card / surface (surface-in-surface): a thin
 * `bg-<status>-soft` + `shadow-none` highlight strip, so it doesn't read as a
 * card-in-card.
 *
 * A thin FRAME around the `Alert` atom: callout = an alert PLACED INSIDE a
 * surface, so the frame only picks `tone="soft"` + glyph `md` and hands the
 * whole skin (tint · icon per valence · × button) to the atom. The frame used
 * to hand-feed three color tables in parallel with `Toast` — that was drift,
 * now removed.
 *
 * @param props - {@link CalloutProps}
 */
export const Callout = (props: CalloutProps) => {
    const {
        status = "default",
        description,
        body: Body,
        icon,
        actionLabel,
        onAction,
        onClose,
        closeAriaLabel,
        classNames,
    } = props
    // Narrowed off the discriminant so `title` stays required in the live branch —
    // destructuring it straight off `props` above would widen it to `string | undefined`
    // and lose exactly that guarantee (same shape `Alert`/`Toast` already use).
    const content = props.isSkeleton
        ? ({ isSkeleton: true, title: props.title } as const)
        : ({ isSkeleton: false, title: props.title } as const)
    return (
        <Alert
            status={status}
            tone="soft"
            {...content}
            description={description}
            body={Body ? <Body isSkeleton={props.isSkeleton} /> : undefined}
            icon={icon}
            action={
                actionLabel ? (
                    // The frame owns the CTA: builds the button + applies skin per status itself. Caller only supplies text.
                    // Button is an atom — it owns its own appearance, so the per-status skin wraps a div rather than reaching into the atom.
                    <div className={CALLOUT_ACTION_CLASS[status]}>
                        <Button label={actionLabel} size="sm" onPress={onAction} />
                    </div>
                ) : undefined
            }
            onClose={onClose}
            closeAriaLabel={closeAriaLabel}
            classNames={classNames}
        />
    )
}

import type { ComponentType, SVGProps } from "react"
import { cn } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { StackV } from "@/components/frames/Stack"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * STORYBOOK-LOCAL DESIGN SPEC — `EmptyState`, a CENTERED vertical stack that
 * fills an empty/error spot (`code`/`icon`/`title`/`description`/`body`/`action`).
 *
 * WARNING Split out of the `Feedback.*` namespace (2026-08-01) back into its own flat
 * file — the 2026-07-25 consolidation grouped `Callout`/`Empty`/`Confirm` under
 * one `Feedback` folder; this reverses that so each frame is discoverable by
 * its own name again (this member was `Feedback.Empty` / `FeedbackEmpty`).
 * Props/behaviour are UNCHANGED — this is a file-location + naming refactor,
 * not a visual or API change.
 *
 * ATOM COMPOSITION (§12): text goes through `Typography.*`, icons come from
 * `@phosphor-icons/react` — ONE SET ONLY (§50), passed as a component ref, the
 * frame forces size/weight itself (§4/§5).
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "EmptyState" } as const

/** Icon passed as a COMPONENT (phosphor), never JSX — the frame owns its scale (§4/§5). */
export type EmptyStateIcon = ComponentType<SVGProps<SVGSVGElement>>

/** Props SPECIFIC to {@link EmptyState} — EXCEPT the `title`/`isSkeleton` pair (see {@link EmptyStateProps}). */
interface EmptyStateOwnProps {
    /**
     * Optional decorative icon as a COMPONENT (Phosphor) above the title — the frame
     * renders it `size-8` + toned. Ignored in `size="compact"`.
     */
    icon?: EmptyStateIcon
    /**
     * Optional large status numeral (e.g. `"404"`, `"500"`) above the icon/title.
     * Intended for `size="page"`; ignored in `size="compact"`. `string`, not
     * `ReactNode` (COMPOSITE-8) — the frame wraps it in `Typography` itself.
     */
    code?: string
    /**
     * Optional supporting text under the title. Ignored in `size="compact"`.
     * `string`, not `ReactNode` (COMPOSITE-8) — the frame wraps it in `Typography`
     * itself, so `isSkeleton` reaches the text it renders.
     */
    description?: string
    /**
     * Optional free-form body region under `description` (a hint list, an
     * illustration). Ignored in `size="compact"`. A COMPONENT reference, not a
     * built node (COMPOSITE-8) — the frame calls it itself with `isSkeleton`
     * forwarded.
     */
    body?: ComponentTypeWithSkeleton
    /**
     * Optional call-to-action region below the body (typically a `Button`).
     * Ignored in `size="compact"`. In `size="page"`, this can lay out multiple
     * actions itself — centered and wrapped. A COMPONENT reference, not a built
     * node (COMPOSITE-8) — the frame calls it itself with `isSkeleton` forwarded.
     */
    action?: ComponentTypeWithSkeleton
    /**
     * Icon tone. `"neutral"` (default) tints the icon `text-foreground`;
     * `"danger"` tints it `text-danger` for error placeholders. Only the icon
     * colour changes — title and description stay as-is.
     */
    tone?: "neutral" | "danger"
    /**
     * Layout size:
     * - `"default"` — the standard centered stack for lists/panels/sections.
     * - `"compact"` — a single muted title-only line (no icon/description/body/action/code).
     * - `"page"` — roomy full-page sizing for whole-route failures (404/500), with a
     *   larger title and room for a `code` numeral above it.
     */
    size?: "default" | "compact" | "page"
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * Caller identity to wear on this composite's root instead of its own — pass this when a
     * `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its own) is
     * using this composite AS its root element, instead of wrapping it in a raw `<div
     * data-tier=… data-component=…>`. See `_identity.ts`. Omitted -> this composite keeps
     * emitting its own `data-tier="composite" data-component="EmptyState"`, unchanged.
     */
    identity?: CallerIdentity
}

/**
 * `isSkeleton` is a co-located loading state — this frame renders its own
 * skeleton bars (via `Typography`) rather than delegating to a `Skeleton.*`
 * compound. `title` is optional only in the `isSkeleton: true` branch; the
 * live branch still requires it. `string`, not `ReactNode` (COMPOSITE-8).
 */
export type EmptyStateProps = EmptyStateOwnProps &
    (
        | { isSkeleton: true; title?: string }
        | { isSkeleton?: false; title: string }
    )

/**
 * Centered placeholder for lists, panels, sections, or whole routes with no content —
 * and for the "failed to load" variant of the same hole (`tone="danger"` + a retry `action`).
 * A vertical, centered stack: optional `code` -> optional icon -> title -> optional
 * description -> optional body -> optional action. Omits a card wrapper — the caller
 * wraps it in a surface (e.g. `SurfaceCardList emptyState={…}`) when a frame is wanted.
 *
 * @param props - {@link EmptyStateProps}
 */
export const EmptyState = (props: EmptyStateProps) => {
    const {
        icon: Icon,
        code,
        description,
        body: Body,
        action: Action,
        tone = "neutral",
        size = "default",
        classNames,
        identity,
    } = props
    const isSkeleton = props.isSkeleton ?? false
    // Narrowed off the discriminant so `title` stays required in the live branch —
    // destructuring it straight off `props` above would widen it to `string | undefined`
    // and lose exactly that guarantee (same shape `Alert`/`Toast` already use).
    const titleContent = props.isSkeleton
        ? ({ isSkeleton: true, text: props.title } as const)
        : ({ isSkeleton: false, text: props.title } as const)
    // Same discriminant trick for the optional strings below — `isSkeleton` must stay the
    // exact `true`/`false` literal, not the widened `boolean` this frame's own flag would
    // give, because `Typography`'s prop type is the same kind of union.
    const skeletonAttrs = isSkeleton ? ({ isSkeleton: true } as const) : ({ isSkeleton: false } as const)

    if (size === "compact") {
        // WARNING The `Typography.*` atom does NOT accept unknown props (no rest spread) -> every
        // anatomy tag must sit on a WRAPPING element, not be stuffed into the atom.
        return (
            <span
                className={cn("block", classNames)}
                {...resolveIdentity(identity, { tier: "composite", name: "EmptyState" })}
            >
