import { StackV } from "@/components/frames/Stack"

/**
 * STORYBOOK-LOCAL DESIGN SPEC — ported faithfully from
 * `@/components/blocks/stats/CourseProgressBar`. Authored in Storybook (not
 * `src`); synced to `src` later.
 */

/** One dimension of course progress (content / challenge / milestone). */
export interface CourseProgressDimension {
    /** Stable key (also used as the i18n label lookup elsewhere). */
    key: string
    /**
     * Legend label. `string`, not `ReactNode` — passed straight into
     * {@link Legend}'s `label` field, which the composite wraps in `Typography`
     * itself.
     */
    label: string
    /** Real completed count for this dimension. */
    completed: number
    /** Real total count for this dimension — dimensions with `total === 0` render no lane at all. */
    total: number
    /** CSS colour for this dimension's fill + legend dot. Falls back to a palette. */
    color?: string
}

/** Props {@link CourseProgressBar} carries regardless of loading state. */
interface CourseProgressBarOwnProps {
    /** Accessible summary of the whole bar. */
    ariaLabel: string
    /** Hide the legend row under the bar. */
    hideLegend?: boolean
    /** Layout utilities on the root element, from the closed positioning union. */
}

/**
 * Props for the {@link CourseProgressBar} block. `dims` is REQUIRED unless
 * `isSkeleton` (§12b) — a shimmer track has no real ratios to show yet.
 */
export type CourseProgressBarProps = CourseProgressBarOwnProps &
    (
        | { isSkeleton: true; dims?: Array<CourseProgressDimension> }
        | { isSkeleton?: false; dims: Array<CourseProgressDimension> }
    )

/** Default per-dimension colours (semantic tokens) when a dimension has no explicit `color`. */
const PALETTE = ["var(--accent)", "var(--success)", "var(--warning)", "var(--danger)", "var(--muted)"]

/**
 * Course progress as EQUAL-WIDTH lanes, one per dimension (content / challenge /
 * milestone), each independently filled to ITS OWN ratio — inside one continuous
 * rounded track. Deliberately NOT {@link SegmentBar} (which sizes each slice by its
 * raw-count share of a single shared total): course dimensions are different UNITS
 * at wildly different scales, so a shared-total bar renders the smaller dimensions
 * as sub-pixel slivers. Equal lanes guarantee every dimension a real, always-visible
 * width while each lane's OWN fill still reflects its true `completed / total` ratio.
 *
 * @param props - {@link CourseProgressBarProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "CourseProgressBar" } as const

/** Renders course progress as equal-width lanes, one per dimension, each filled to its own ratio. */
export const CourseProgressBar = ({
    dims,
    ariaLabel,
    hideLegend,
    isSkeleton = false}: CourseProgressBarProps) => {
    const lanes = (dims ?? [])
        .filter((dim) => dim.total > 0)
        .map((dim, index) => ({
            ...dim,
            color: dim.color ?? PALETTE[index % PALETTE.length],
            ratio: Math.min(1, dim.completed / dim.total)}))

    return (
        <StackV
            gap={3}
            items={[
                /* ATOM GAP: equal-width multi-lane track has no atom counterpart (see
                        file header note), so it stays a hand-drawn real element — the SAME
                        track renders in both states; isSkeleton hides the lanes for a flat
                        neutral fill instead of reaching for a vendor Skeleton or hand-rolling
                        a bespoke `animate-pulse` shimmer (COMPOSITE-10). */
                () => (
                    <div
                        role="img"
                        aria-label={ariaLabel}
                        className={cn("flex h-1 w-full overflow-hidden rounded-full bg-default")}
                    >
                        {isSkeleton
                            ? null
                            : lanes.map((lane, index) => (
                                <div
                                    key={lane.key}
                                    className={cn("h-full flex-1", index > 0 && "border-l border-default")}
                                >
                                    <div
                                        className="h-full"
                                        style={{ width: `${lane.ratio * 100}%`, backgroundColor: lane.color }}
                                    />
                                </div>
                            ))}
                    </div>
                ),
                ...(!hideLegend ? [() => (
                    isSkeleton ? (
                        <Legend isSkeleton />
                    ) : (
                        <Legend
                            isSkeleton={false}
                            items={lanes.map((lane) => ({
                                key: lane.key,
                                label: lane.label,
                                color: lane.color,
                                suffix: `\u00A0·\u00A0${lane.completed}`}))}
                        />
                    )
                )] : []),
            ]}
        />
    )
}

import React from "react"
import { cn } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH } from "@/components/frames/Stack"

/**
 * STORYBOOK-LOCAL DESIGN SPEC — ported faithfully from
 * `@/components/composites/stats/Legend`. Authored in Storybook (not `src`); synced
 * to `src` later.
 */

/**
 * Resolve a swatch `color` into the right paint channel: a Tailwind `bg-*`
 * utility class is applied as a className; anything else (a raw hex, `var(--…)`,
 * `rgb(…)`, …) is applied as an inline `backgroundColor` — same dual-mode
 * handling as the dot of `Chip` (`dotClassName` vs `dotColor`).
 */
const resolveDotColor = (color: string): { className?: string; style?: React.CSSProperties } =>
    color.startsWith("bg-")
        ? { className: color }
        : { style: { backgroundColor: color } }

/** One legend entry: a colour swatch + its label (+ an optional trailing value). */
export interface LegendItem {
    /** Stable key. */
    key: string
    /**
     * Label shown next to the swatch. `string`, not `ReactNode` — the composite
     * wraps it in `Typography` itself, so it must be able to build it.
     */
    label: string
    /** Swatch colour — a Tailwind `bg-*` class OR a raw colour value (`var(--success)`, `#3178c6`). */
    color: string
    /**
     * Optional trailing value printed after the label in the SAME muted line
     * (e.g. a "· 12" count or a "40%" share). Omit for a bare label. `string` —
     * see {@link LegendItem.label}.
     */
    suffix?: string
}

/** Props {@link Legend} carries regardless of loading state. */
interface LegendOwnProps {
    /**
     * Layout of the entries. `"row"` (default) is a `flex-wrap` row that wraps to
     * new lines when narrow; `"col"` stacks entries vertically.
     */
    direction?: "row" | "col"
    /** Entry count to shimmer while `isSkeleton`. Defaults to `3`. */
    skeletonCount?: number
    /** `true` → tag the dot/label skeleton bars with ``. */
}

/**
 * Props for the {@link Legend} block. `items` is REQUIRED unless `isSkeleton`
 * (§12b) — a shimmer legend has no real entries to show yet.
 */
export type LegendProps = LegendOwnProps &
    (
        | { isSkeleton: true; items?: Array<LegendItem> }
        | { isSkeleton?: false; items: Array<LegendItem> }
    )

/**
 * Standalone colour legend — a `flex-wrap` row (or vertical stack) of `dot +
 * label + optional trailing value`, matching the legend a {@link SegmentBar} or
 * {@link CourseProgressBar} renders under itself. Each entry's `color` accepts a
 * Tailwind `bg-*` class or a raw colour value, and an optional `suffix` prints a
 * count/share after the label. Pure/props-only.
 *
 * @param props - {@link LegendProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Legend" } as const

/** A standalone dot + label (+ optional value) legend row matching a chart's own legend. */
export const Legend = ({
    items,
    direction = "row",
    isSkeleton = false,
    skeletonCount = 3}: LegendProps) => {
    return (
        <div
            className={cn(
                direction === "col"
                    ? "flex flex-col gap-2"
                    : "flex flex-wrap gap-x-3 gap-y-2")}
            data-tier="composite"
            data-component="Legend"
            data-principle={direction === "col" ? "sibling-stack" : undefined}
        >
            {isSkeleton
                ? Array.from({ length: skeletonCount }, (_unused, index) => (
                    <StackH
                        key={index}
                        gap={3}
                        items={[
                            /* ATOM GAP: no swatch/dot atom exists yet, so the dot stays a
                                    real plain span in both states — a neutral flat fill (no
                                    hand-drawn `animate-pulse`, COMPOSITE-10) instead of reaching
                                    for a vendor Skeleton (the same span shape the loaded entry
                                    below draws, just without a real color). */
                            () => (
                                <span
                                    aria-hidden
                                    className="size-2.5 shrink-0 rounded-full bg-default"
                                />
                            ),
                            () => <Typography size="xs" isSkeleton />,
                        ]}
                    />
                ))
                : (items ?? []).map((item) => {
                    const dot = resolveDotColor(item.color)
                    return (
                        <StackH
                            key={item.key}
                            gap={3}
                            items={[
                                () => (
                                    <span
                                        aria-hidden
                                        style={dot.style}
                                        className={cn("size-2.5 shrink-0 rounded-full", dot.className)}
                                    />
                                ),
                                () => <Typography size="xs" color="muted" text={`${item.label}${item.suffix ?? ""}`} />,
                            ]}
                        />
                    )
                })}
        </div>
    )
}

