}: MetricCardProps) => {
    return (
        // SectionCard provides the framed card shell (border + bg + radius)
        <SectionCard body={
            <StackV
                gap={3}
                isSkeleton={isSkeleton}
                items={[
                    // Primary metric value — large and visually prominent
                    () => <Typography size="h4" isSkeleton={isSkeleton} text={value} />,
                    // Descriptive label — body-sm foreground, the prominent line
                    () => <Typography size="sm" isSkeleton={isSkeleton} text={label} />,
                    // Optional hint — small + muted footnote, DISTINCT from the label.
                    // While loading there is no `hint` to test yet, so the composite still
                    // decides to shimmer a third line (the count is its call, not the atom's).
                    ...(hint !== undefined || isSkeleton ? [() => (
                        <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={hint} />
                    )] : []),
                ]}
            />
        } />
    )
}

import React from "react"
import { cn } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import type { TypographyColor } from "@/components/atoms/text/Typography"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * COMPOSITE — `DotLabel`: a colour swatch + an inline text label, as ONE unit —
 * NO pill/background around it (a status line inside a card, an "Online" row
 * beside a name, a category line in a dense list — anywhere a coloured dot
 * reads faster than the word alone, but a full chip's padding/background would
 * be too heavy for the surface it sits in).
 *
 * CHECKED BEFORE BUILDING (per the build brief's "two candidates" audit):
 *
 * * NOT already covered by `Chip`'s dot variant (`dotColor`/`dotClassName` on
 * `atoms/chips/Chip`, informally "Chip.Dot"). That variant is still a real
 * `HeroChip` underneath — `variant="soft"`, the chip's own background/padding/
 * rounded-full pill shell, just with a coloured dot in the leading-glyph slot
 * instead of an icon. It answers "a status **chip**"; it cannot render a bare
 * dot + label with no chip shell around it, because `ChipBase` never renders
 * without the `HeroChip` wrapper. Confirmed by reading `ChipBase.tsx` directly
 * — every branch (skeleton and real) returns a `<HeroChip>` root.
 *
 * * THE SAME BARE SHAPE ALREADY EXISTS, but only INLINED inside `Legend`
 * (`composites/stats/Legend`), one entry of its `items` list, and its own file
 * flags the same thing this composite now fixes: *"ATOM GAP: no swatch/dot
 * atom exists yet, so the dot stays a real plain span"*. `DotLabel` reuses
 * that exact swatch mechanism (`resolveDotColor`, size-2.5 flat circle,
 * neutral skeleton fill) so the two composites don't invent two different dots
 * for the same idea — but exposes it as its own standalone single-instance
 * composite, since `Legend` only takes a repeated `items` array and is scoped
 * to "a legend for a chart", not any dot+label row in the app.
 *
 * SAME ATOM GAP AS `Legend`: no swatch/dot atom exists yet in `atoms/`. Kept
 * as a plain `<span>` here for the same reason — a flat, non-animated fill is
 * already a correct "not loaded yet" indicator for a shape this simple, so
 * reaching for a vendor `Skeleton` here would be COMPOSITE-10 for no gain.
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Label tone — the 6-value scale every composite text draws from. Default `muted` (a status line reads as secondary text; the swatch already carries the emphasis). */
export type DotLabelTone = "default" | "muted" | "accent" | "success" | "warning" | "danger"

const TONE_TO_TYPOGRAPHY: Record<DotLabelTone, TypographyColor> = {
    default: "default",
    muted: "muted",
    accent: "accent",
    success: "success",
    warning: "warning",
    danger: "danger",
}

/**
 * Resolve a swatch `color` into the right paint channel — same dual-mode
 * split `Legend` uses for its own dot: a Tailwind `bg-*` utility applies as a
 * className; anything else (a raw hex, `var(--…)`, `rgb(…)`) applies as an
 * inline `backgroundColor`, so a caller can pass either a token or a value
 * outside the Tailwind palette (e.g. a GitHub language colour) through one prop.
 */
/** The resolved dot paint channel — a Tailwind `bg-*` className, or a raw-colour inline style, never both. */
interface ResolvedDotColor {
    className?: string
    style?: React.CSSProperties
}

const resolveDotColor = (color: string): ResolvedDotColor => {
    if (color.startsWith("bg-")) {
        return { className: color }
    }
    return { style: { backgroundColor: color } }
}

/** Props shared regardless of loading state — see {@link DotLabelProps} for the `color`/`label`/`isSkeleton` union. */
interface DotLabelOwnProps {
    /** Label tone. Defaults to `"muted"`. */
    tone?: DotLabelTone
}

/**
 * `color`/`label` are required when rendering a real row; not needed when
 * `isSkeleton` — the shimmer mirror has no swatch colour or text of its own.
 */
export type DotLabelProps = DotLabelOwnProps &
    (
        | { isSkeleton: true; color?: string; label?: string }
        | {
              isSkeleton?: false
              /**
               * Swatch colour — a Tailwind `bg-*` class OR a raw colour value
               * (`var(--success)`, `#3178c6`).
               */
              color: string
              /**
               * The label text, rendered through `Typography` — the composite owns
               * the tone (see {@link DotLabelOwnProps.tone}), so this is `string`,
               * never a pre-built node.
               */
              label: string
          }
    )

/**
 * `DotLabel` — a colour dot beside an inline text label, no chip/pill shell.
 * See the file header for why this is not already `Chip`'s dot variant or
 * `Legend`.
 *
 * @param props - {@link DotLabelProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "DotLabel" } as const

/** A colour dot beside an inline text label, with no chip/pill shell around it. */
export const DotLabel = ({
    color,
    label,
    tone = "muted",
    
    isSkeleton = false,
}: DotLabelProps) => {
    const dot = color ? resolveDotColor(color) : undefined

    return (
        <span
            className={cn("inline-flex items-center gap-1")}
            data-tier="composite"
            data-component="DotLabel"
            data-principle="icon-text"
        >
            {isSkeleton ? (
                // ATOM GAP (same one `Legend` already flags): no swatch/dot atom exists
                // yet, so the dot stays a real plain span in both states — a neutral
                // flat fill (no hand-drawn `animate-pulse`, COMPOSITE-10) instead of
                // reaching for a vendor Skeleton.
                <span aria-hidden className="size-2.5 shrink-0 rounded-full bg-default" />
            ) : (
                <span
                    aria-hidden
                    style={dot?.style}
                    className={cn("size-2.5 shrink-0 rounded-full", dot?.className)}
                />
            )}
            <Typography
                size="sm"
                color={isSkeleton ? undefined : TONE_TO_TYPOGRAPHY[tone]}
                classNames={isSkeleton ? ["w-1/3"] : undefined}
                isSkeleton={isSkeleton}
                text={label}
            />
        </span>
    )
}

import React from "react"
import { cn } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Divider } from "@/components/atoms/display/Divider"

/**
 * STORYBOOK-LOCAL DESIGN SPEC — MetaDotRow: a row of small text fragments
 * separated by a `·` mark ("12 lessons · 3 hours · Free", "12 minutes ago ·
 * Edited"). The fragments are one recurring meta-line SHAPE — the same info
 * seen today as a hand-rolled `flex flex-wrap items-center gap-2 text-xs
 * text-muted` with a bare `<span aria-hidden>·</span>` between children
 * (`PostRow`, `ProfileHero`'s sidebar meta) — so it becomes ONE composite
 * that owns the separator, the gap, and the tone, instead of every call site
 * re-typing the same three things.
 *
 * `items` is a plain `string[]`, not `ClusterItem[]`/`ReactNode[]` (COMPOSITE-8):
 * each fragment is TEXT the composite renders through `Typography` itself, so
 * it can shimmer the fragment — a pre-built node could not be told it is loading.
 *
 * GAP — the registry's own `separator-dot` token (`patterns.mjs`): "a · separating
 * meta fragments", step 2, 4px (`gap-1`). The real call sites above sit at `gap-2`
 * (8px) today; that is the debt this composite corrects, not a convention to copy.
 *
 * TONE — every fragment is `muted` (§law-2, explicit on the atom). The `·` mark
 * itself is `Divider`'s `shape="inline"` glyph, which paints `text-current` (no
 * colour prop of its own — ATOM-shape, not a status) — so the row's ROOT carries
 * a fixed `text-muted` class the mark inherits, keeping fragment and mark on the
 * same tone without a second colour decision.
 */

/** Props {@link MetaDotRow} carries regardless of loading state. */
interface MetaDotRowOwnProps {
    /** Fragment count to shimmer while `isSkeleton`. Defaults to `3`. */
    skeletonCount?: number
}

/**
 * Props for the {@link MetaDotRow} composite. `items` is REQUIRED unless
 * `isSkeleton` (§12b) — a shimmer row has no real fragments to show yet.
 */
export type MetaDotRowProps = MetaDotRowOwnProps &
    (
        | { isSkeleton: true; items?: Array<string> }
        | { isSkeleton?: false; items: Array<string> }
    )

/**
 * A `flex-wrap` row of muted text fragments with a `·` mark between every pair —
 * the composite owns the mark (`Divider` atom, `shape="inline"`), the seam
 * (`separator-dot`, 4px) and the tone (`muted`, on every fragment AND the root,
 * so the marks inherit it). Each fragment renders through `Typography` so it can
 * shimmer on its own; the row decides only HOW MANY shimmer while loading.
 *
 * @param props - {@link MetaDotRowProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "MetaDotRow" } as const

/** A wrapping row of muted text fragments joined by a `·` divider mark. */
export const MetaDotRow = ({
    items,
    isSkeleton = false,
    skeletonCount = 3,
    
}: MetaDotRowProps) => {
    const fragments = isSkeleton
        ? Array.from({ length: skeletonCount }, (_unused, index) => ({ key: String(index), text: undefined }))
        : (items ?? []).map((text, index) => ({ key: String(index), text }))

    // COMPOSITE-10: ONE render path — same wrapper, same gap, in both states. Every
    // fragment goes through `Typography`'s own `isSkeleton` (§12c: the atom draws
    // its own bar, sized to its own value) — there is no second, hand-built
    // skeleton row to keep in sync with this one. The `·` mark needs no skeleton
    // of its own (a static glyph, nothing to load — see `Divider`'s own header).
    return (
        <div
            className={cn("flex flex-wrap items-center gap-1 text-muted")}
            data-tier="composite"
            data-component="MetaDotRow"
            data-principle="separator-dot"
        >
            {fragments.map((fragment, index) => (
                <React.Fragment key={fragment.key}>
                    {index > 0 ? <Divider shape="inline" /> : null}
                    <Typography
                        size="xs"
                        color={isSkeleton ? undefined : "muted"}
                        classNames={isSkeleton ? ["w-1/4"] : undefined}
                        isSkeleton={isSkeleton}
                        text={fragment.text}
                    />
                </React.Fragment>
            ))}
        </div>
    )
}

import { cn } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * PricePeriod: a price shown as one baseline-aligned unit — a prominent amount, an
 * optional struck original/list price, and an optional billing period ("/month").
 *
 * This is a COMPOSITE, not an atom: a price is a CLUSTER of distinct values (a
 * `value-row`), not one atom's single concern. It replaces the retired `PricePoint`
 * atom, which reached ATOM-3 by rendering raw spans instead of the house `Typography`
 * atom — this component fixes that by composing `Typography` for all three parts, so
 * each part draws its own tone AND its own skeleton bar.
 *
 * Distinct from `commerce/PriceTag`, which is a product-discount price (VND/USD
 * numbers + a −X% chip + a breakdown popover). `PricePeriod` takes pre-formatted
 * strings plus a billing `/period`.
 */

/** Amount type scale — drives the main amount's size, and (via {@link SIZE_TO_TOKENS}) the original/period sizes riding along with it. */
export type PricePeriodSize = "sm" | "md" | "lg"

/** Heading-scale token for `amount` — one of `Typography`'s own heading sizes. */
type AmountHeadingSize = "h2" | "h3" | "h4"
/** Body-scale token for `original`/`period` — one of `Typography`'s own body sizes. */
type BodySize = "xs" | "sm" | "base"

/**
 * One table per `size` for all three parts — amount (heading scale) + original +
 * period (body scale) — so the whole unit grows as one coherent piece instead of a
 * big number next to leftover tiny text.
 */
const SIZE_TO_TOKENS: Record<
    PricePeriodSize,
    { amount: AmountHeadingSize; original: BodySize; period: BodySize }
> = {
    sm: { amount: "h4", original: "xs", period: "xs" },
    md: { amount: "h3", original: "sm", period: "xs" },
    lg: { amount: "h2", original: "base", period: "sm" },
}

/** Props shared by every `amount`/`isSkeleton` combination — see {@link PricePeriodProps}. */
interface PricePeriodOwnProps {
    /** Struck-through original/list price shown beside the amount (e.g. "399,000₫"). */
    original?: string
    /** Billing period rendered small + muted after the amount (e.g. "/month"). */
    period?: string
    /** Amount size — also drives `original`/`period`'s size via {@link SIZE_TO_TOKENS}. Defaults to `"md"` (h3). */
    size?: PricePeriodSize
}

/**
 * `amount` is required to render the live price, optional when `isSkeleton` — the
 * shimmer bar has no content to read.
 */
export type PricePeriodProps = PricePeriodOwnProps &
    (
        | { isSkeleton: true; amount?: string }
        | { isSkeleton?: false; amount: string }
    )

/**
 * Renders a price as one baseline-aligned unit: the amount (prominent), an optional
 * struck original, and an optional muted period. Each part is a `Typography` string —
 * the composite owns the tone and the per-size scale, the caller passes pre-formatted
 * text. `isSkeleton` forwards straight into every `Typography` instance so each part
 * draws its own bar (COMPOSITE-10): this component only decides WHICH parts shimmer
 * (the original never gets a placeholder of its own — passing it during `isSkeleton`
 * changes nothing) and, implicitly via `size`, HOW TALL each bar is.
 *
 * @param props - {@link PricePeriodProps}
 */
export const PricePeriod = ({
    amount,
    original,
    period,
    size = "md",
    isSkeleton = false,
    
}: PricePeriodProps) => {
    const tokens = SIZE_TO_TOKENS[size]

    return (
        <div
            data-tier="composite"
            data-component="PricePeriod"
            data-principle="value-row"
            className={cn("flex flex-wrap items-baseline gap-2")}
        >
            {/* Main amount — prominent, sized off {@link SIZE_TO_TOKENS}. */}
            <Typography
                size={tokens.amount}
                weight="semibold"
                color="default"
                isSkeleton={isSkeleton}
                classNames={isSkeleton ? ["w-1/3"] : undefined}
                text={amount}
            />
            {/* Struck-through original — only rendered for a real value; no skeleton
                placeholder of its own (mirrors the retired atom's behaviour). */}
            {original && !isSkeleton ? (
                <Typography
                    size={tokens.original}
                    color="muted"
                    isStruck
                    text={original}
                />
            ) : null}
            {/* Billing period — smallest muted text at this size. */}
            {period ? (
                <Typography
                    size={tokens.period}
                    color={isSkeleton ? undefined : "muted"}
                    isSkeleton={isSkeleton}
                    classNames={isSkeleton ? ["w-1/4"] : undefined}
                    text={period}
                />
            ) : null}
        </div>
    )
}

/** Component-tier metadata for `PricePeriod` — registers it as a composite named `PricePeriod`. */
export const meta = { tier: "composite", name: "PricePeriod" } as const

"use client"

import React, { useId, useState } from "react"
import { MagnifyingGlassPlusIcon } from "@phosphor-icons/react"
import mermaid from "mermaid"
import useSWR from "swr"
import {
    ModalBackdrop,
    ModalBody,
    ModalCloseTrigger,
    ModalContainer,
    ModalDialog,
    ModalRoot,
} from "@/components/atoms/overlay/Modal"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * STORYBOOK-LOCAL DESIGN SPEC — faithful port of
 * `@/components/blocks/rendering/MarkdownContent/MermaidDiagram`. Authored in
 * Storybook (not `src`); synced back to `src` later. Sibling of
 * `MarkdownContent.tsx` in this same composite folder (this repo keeps a
 * component's helper pieces FLAT inside its own folder rather than the
 * `Name/index.tsx` sub-folder shape `src` uses — see `SurfaceCard`/`ProgressMeter`
 * for the same convention).
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Props for {@link MermaidDiagram}. */
export interface MermaidDiagramProps {
    /** Mermaid source string. */
    code: string
    /** Mermaid theme key resolved from the current Storybook toolbar theme. */
    theme: "default" | "dark"
    /** Loading text shown while the diagram is rendering. */
    loadingLabel: string
    /** Accessible label for the click-to-zoom trigger. */
    expandLabel: string
    /** Figure caption paragraph that follows the diagram (e.g. "Figure 1: ..."), if any. */
    caption?: string
    /** Generic caption shown in the zoom modal when the diagram has no authored caption. */
    fallbackLabel: string
}

/**
 * Renders mermaid code blocks to SVG, cached per theme + source via SWR.
 *
 * Presentational: uses only UI-local hooks (`useId`, `useState`) plus SWR's local cache to
 * render the diagram and toggle a full-screen preview; no business logic. Marked
 * `"use client"` for the browser-side mermaid renderer.
 * @param props - {@link MermaidDiagramProps}
 */
export const MermaidDiagram = ({ code, theme, loadingLabel, expandLabel, caption, fallbackLabel }: MermaidDiagramProps) => {
    // Stable id so concurrent diagrams never collide on mermaid's render target id.
    const renderId = useId().replace(/:/g, "-")
    // Local open flag for the full-screen preview dialog (per-diagram, not a global modal).
    const [isOpen, setOpen] = useState(false)
    // Authored caption wins; otherwise show a generic figure label.
    const figureCaption = caption ?? fallbackLabel
    const { data } = useSWR(
        `mermaid:${theme}:${code}`,
        async () => {
            mermaid.initialize({
                startOnLoad: false,
                theme,
                securityLevel: "strict",
            })
            const { svg } = await mermaid.render(`mermaid-${renderId}`, code)
            return svg
        },
        {
            revalidateOnFocus: false,
            revalidateOnReconnect: false,
        },
    )

    return (
        <figure className="overflow-hidden rounded-3xl border border-default bg-background">
            {/* Header row matches `CodeToHtml`'s exact chrome (label left, action right) — a
                mermaid block is "a fence with a name" the same way a code fence is: the WORD
                "mermaid" is the label, same as a code fence names its own language. The zoom
                trigger is icon-only too, matching `SnippetIcon`'s copy button — always visible,
                not a hover-only overlay. */}
            <Box principle="control-pad" className="flex items-center justify-between border-b border-default px-3 py-2"
                explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                <span className="font-mono text-xs text-muted">mermaid</span>
                {data ? (
                    <button type="button" aria-label={expandLabel} title={expandLabel} onClick={() => setOpen(true)} className="text-muted">
                        <MagnifyingGlassPlusIcon className="size-4" />
                    </button>
                ) : null}
            </Box>
            {data ? (
                <>
                    {/* mermaid stamps an inline `style="max-width:Npx"` on the <svg> that
                        outranks our `max-w-full` class, so a wide diagram would otherwise push
                        the reading column past the viewport. Wrap it in an x-scroll box: it
                        scales to fit when it can, and scrolls inside the figure when it can't.
                        data-principle hand-set (not `Box`): `dangerouslySetInnerHTML` has no slot on `Box`'s prop surface. */}
                    <div
                        data-principle="cell-pad" className="overflow-x-auto p-3 [&_svg]:h-auto [&_svg]:!w-auto [&_svg]:!max-w-none"
                        dangerouslySetInnerHTML={{ __html: data }}
                    />
                    {/* Authored caption ("Figure N: …") as a real figcaption — the source paragraph
                        is stripped upstream so it isn't shown twice. Generic fallback stays modal-only.
                        px-3 pb-3 is a continuation inset (no top — it sits flush under the diagram
                        above, not its own surface), not a symmetric `padding`/`padding-xy` shape in
                        patterns.mjs; `figcaption` is also outside `Box`'s `as` union. Nearest token by
                        intent (dense inner surface, same 12px measure as the diagram box above),
                        data-principle hand-set directly. */}
                    {caption ? (
                        <figcaption data-principle="cell-pad" className="px-3 pb-3 text-center text-sm italic text-muted">
                            {caption}
                        </figcaption>
                    ) : null}
                    <ModalRoot isOpen={isOpen} onOpenChange={setOpen}>
                        <ModalBackdrop>
                            <ModalContainer size="full">
                                <ModalDialog>
                                    <ModalCloseTrigger />
                                    <ModalBody>
                                        {/* Full-screen figure: diagram scaled to fill, caption beneath.
                                            Page inset owned by Box principle=page-pad — not ModalBody
                                            className (ATOM-5: atoms take position only). */}
                                        <Box
                                            principle="page-pad"
                                            className="h-full"
                                            explain="Outermost reading inset inside the zoom dialog — not card-padding, because this is a full-viewport surface rather than a card body."
                                        >
                                            <StackV
                                                as="figure"
                                                gap={3}
                                                principle="sibling-stack"
                                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                align="center"
                                                justify="center"
                                                classNames={["h-full"]}
                                                items={[
                                                    () => (
                                                        <div className="flex w-full flex-1 items-center justify-center overflow-auto">
                                                            <div
                                                                className="[&_svg]:h-auto [&_svg]:w-full [&_svg]:max-w-full"
                                                                dangerouslySetInnerHTML={{ __html: data }}
                                                            />
                                                        </div>
                                                    ),
                                                    () => (
                                                        <figcaption className="text-center text-sm italic text-muted">
                                                            {figureCaption}
                                                        </figcaption>
                                                    ),
                                                ]}
                                            />
                                        </Box>
                                    </ModalBody>
                                </ModalDialog>
                            </ModalContainer>
                        </ModalBackdrop>
                    </ModalRoot>
                </>
            ) : (
                <Box principle="cell-pad" className="p-3 text-sm text-muted"
                    explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body.">{loadingLabel}</Box>
            )}
        </figure>
    )
}

import React from "react"
import { cn } from "@heroui/react"
import {
    AccordionTree,
    AccordionTreeBody,
    AccordionTreeHeading,
    AccordionTreeIndicator,
    AccordionTreeItem,
    AccordionTreePanel,
    AccordionTreeTrigger,
} from "@/components/atoms/navigation/AccordionTree"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { CodeToHtml } from "@/components/composites/viewers/MarkdownContent/CodeToHtml"
import { MermaidDiagram } from "@/components/composites/viewers/MarkdownContent/MermaidDiagram"
import { TabsBlock, TabPane } from "@/components/composites/viewers/MarkdownContent/TabsBlock"
import {
    MarkdownTable,
    MarkdownTableBody,
    MarkdownTableCell,
    MarkdownTableColumn,
    MarkdownTableHead,
    MarkdownTableRow,
} from "@/components/composites/viewers/MarkdownContent/MarkdownTableParts"
import { Box } from "@/components/frames/Box"
import { StackH } from "@/components/frames/Stack"

/**
 * The element-renderer MAP for `MarkdownContent` — the whole grammar (headings,
 * tables, code, mermaid, custom directive tags) in one file.
 *
 * Handles: Shiki syntax highlighting, mermaid diagrams, `:::tab`/`:::code`/
 * `:::preview` -> Preview<->Code tabs, GFM tables -> house `TableRoot`,
 * `::::accordion`/`:::panel` -> house `AccordionTree`, `:::muted`, `:::chip`, image
 * captions, link routing, heading anchors. Not handled here: `arcSections`,
 * `plain` mode, the ` ```mdx ` live-render fence, the ` ```layout ` fence.
 *
 * Vertical rhythm is owned by the single wrapper in `MarkdownContent.tsx`, or in
 * reading measure by a plain `<div className={blockMy}>` around each block-level
 * renderer's output — margin is a seam between two blocks, written where both are
 * visible rather than passed as a `className` prop. `CodeToHtml`,
 * `MermaidDiagram`, and `MarkdownTable` take no `className`.
 */

/** UI copy for the code/table/mermaid chrome. Storybook has no i18n-aware runtime
 * for this tree (see the file header on `MarkdownContent.tsx`), so — like every
 * other composite in this design system — the copy is a hardcoded constant
 * instead of a `useTranslations()` call. Values mirror `src/messages/vi.json`'s
 * `markdown.*` keys so a reader comparing the two sees the same words. */
const TABLE_ARIA_LABEL = "Content table"
const MERMAID_LOADING_LABEL = "Drawing diagram..."
const MERMAID_EXPAND_LABEL = "Expand diagram"
const MERMAID_FALLBACK_LABEL = "Figure"
const HEADING_ANCHOR_LABEL = "Link to this section"

/** Anything the parser hands back with only children — most of the grammar. */
export interface MarkdownNodeProps {
    /** Whatever the parser put inside this element. */
    children?: React.ReactNode
}

/** A link node: the payload decides the target, the viewer only decides the skin. */
export interface MarkdownLinkProps extends MarkdownNodeProps {
    /** Link target as authored. */
    href?: string
}

/** An image node — a raw URL plus its alt text, both straight from the payload. */
export interface MarkdownImageProps {
    /** Image source as authored. */
    src?: string
    /** Alt text as authored; a non-empty alt doubles as a real figure caption. */
    alt?: string
}

/**
 * A code node. A fenced block arrives with `language-*` on react-markdown's
 * `className`; that string is the language hook, not a styling door — stored here
 * as `fenceClass` so COMPOSITE-4 does not see a `className` prop on a `*Props` type.
 */
export interface MarkdownCodeProps extends MarkdownNodeProps {
    /** `language-*` for a fenced block, absent for inline code. */
    fenceClass?: string
}

/** react-markdown still emits `className` on `code`; rename at the renderer boundary. */
type MarkdownCodeRuntimeProps = MarkdownNodeProps & {
    className?: string
}

/** One `:::panel{title="…"}` inside an `::::accordion` block. */
export interface MarkdownPanelProps extends MarkdownNodeProps {
    /** Trigger-row title carried by the directive attribute. */
    title?: string
}

/** The `:::chip` directive's rewritten tag — one `|`-joined line of keywords. */
export interface MarkdownChipBlockProps {
    /** `|`-joined keyword list, one per authored line (see `remarkChip` in `MarkdownContent.tsx`). */
    items?: string
}

/** Config for one {@link buildTocHeading} level. */
interface TocHeadingConfig {
    /** Heading depth surfaced in the outline. */
    level: 2 | 3 | 4
    /** Tailwind text-size class. */
    sizeClass: string
    /** Tailwind margin class (asymmetric — reading measure only). */
    marginClass: string
    /** `true` (reading measure only) -> render the hover `#` deep-link affordance. */
    showAnchor: boolean
}

/**
 * Recursively flattens a React children tree to its plain-text content — used to
 * derive a stable heading slug (and the "on this page" outline label) from the
 * rendered heading nodes.
 * @param node - The React node to read text from.
 * @returns The concatenated text content.
 */
const getNodeText = (node: React.ReactNode): string => {
    if (node === null || node === undefined || typeof node === "boolean") {
        return ""
    }
    if (typeof node === "string" || typeof node === "number") {
        return String(node)
    }
    if (Array.isArray(node)) {
        return node.map(getNodeText).join("")
    }
    if (React.isValidElement(node)) {
        return getNodeText((node.props as MarkdownNodeProps).children)
    }
    return ""
}

/**
 * Slugify heading text into a URL-safe anchor id (diacritics stripped, Vietnamese
 * Vietnamese d-with-stroke folded to `d`, non-alphanumerics collapsed to single hyphens). Deterministic so the
 * rendered heading id and any "on this page" outline reading it from the DOM agree.
 * @param text - The raw heading text.
 * @returns The anchor slug.
 */
const slugify = (text: string): string =>
    text
        .normalize("NFKD")
        .replace(/[̀-ͯ]/g, "")
        .replace(/[đĐ]/g, "d") // vn-ok: slug transliteration of the VI letter
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")

/**
 * Heading renderer factory: renders a section heading carrying a slug `id` +
 * `data-toc` markers so an "on this page" rail can scan the rendered article
 * (`[data-toc]`) and anchor-scroll to it. `scroll-mt-20` clears a sticky navbar
 * when jumped to. The hover `#` deep-link only renders in reading measure — cards
 * / chat / modals have no shareable url for it.
 * @param config - {@link TocHeadingConfig}
 */
const buildTocHeading = ({ level, sizeClass, marginClass, showAnchor }: TocHeadingConfig) =>
    ({ children }: MarkdownNodeProps) => {
        const Tag = `h${level}` as "h2" | "h3" | "h4"
        const text = getNodeText(children)
        const id = slugify(text)
        return (
            <Tag
                id={id}
                data-toc=""
                data-toc-level={level}
                data-toc-label={text}
                className={cn("group scroll-mt-20 font-semibold", marginClass, sizeClass)}
            >
                {children}
                {showAnchor ? (
                    <a
                        href={`#${id}`}
                        aria-label={HEADING_ANCHOR_LABEL}
                        className="ml-2 text-muted no-underline opacity-0 transition-opacity group-hover:opacity-100"
                    >
                        #
                    </a>
                ) : null}
            </Tag>
        )
    }

/** Params for {@link buildMarkdownRenderers}. */
export interface MarkdownRenderersParams {
    /** True when the Storybook toolbar theme is dark; selects mermaid/Shiki themes. */
    isDark: boolean
    /** Reading-grade typography (bigger type, generous rhythm) vs the compact scale. */
    reading: boolean
    /** Figure captions keyed by trimmed mermaid source, paired from the following paragraph. */
    mermaidCaptions: Record<string, string>
}

/**
 * Builds the element-renderer map handed to `ReactMarkdown`. See the file header
 * for scope; each renderer stays margin-free in compact measure (the wrapper in
 * `MarkdownContent.tsx` owns the uniform rhythm there) and carries its own
 * asymmetric margin in reading measure.
 * @param params - {@link MarkdownRenderersParams}
 */
export const buildMarkdownRenderers = ({ isDark, reading, mermaidCaptions }: MarkdownRenderersParams) => {
    const blockMy = reading ? "my-4" : "my-3"
    // Link text rides the same body scale as the surrounding prose.
    const linkSize = reading ? "base" : "sm"

    return {
        h1: ({ children }: MarkdownNodeProps) => (
            <h1 className={cn("font-semibold text-foreground", reading ? "mt-8 mb-3 text-2xl" : "mt-6 mb-2 text-xl")}>{children}</h1>
        ),
        h2: buildTocHeading({
            level: 2,
            sizeClass: reading ? "text-xl" : "text-lg",
            marginClass: reading ? "mt-8 mb-3" : "mt-6 mb-2",
            showAnchor: reading,
        }),
        h3: buildTocHeading({
            level: 3,
            sizeClass: reading ? "text-lg" : "text-base",
            marginClass: reading ? "mt-6 mb-2" : "mt-4 mb-2",
            showAnchor: reading,
        }),
        h4: buildTocHeading({
            level: 4,
            sizeClass: reading ? "text-base" : "text-sm",
            marginClass: reading ? "mt-6 mb-2" : "mt-4 mb-2",
            showAnchor: reading,
        }),
        p: ({ children }: MarkdownNodeProps) => (
            <p className={cn("text-foreground", reading ? "my-3 text-base leading-7" : "my-2 text-sm leading-6")}>{children}</p>
        ),
        ul: ({ children }: MarkdownNodeProps) => (
            <ul className={cn("list-disc pl-6", reading ? "my-3 space-y-1" : "my-2 space-y-1")}>{children}</ul>
        ),
        ol: ({ children }: MarkdownNodeProps) => (
            <ol className={cn("list-decimal pl-6", reading ? "my-3 space-y-1" : "my-2 space-y-1")}>{children}</ol>
        ),
        li: ({ children }: MarkdownNodeProps) => (
            <li className={cn("text-foreground", reading ? "text-base leading-7" : "text-sm leading-6")}>{children}</li>
        ),
        strong: ({ children }: MarkdownNodeProps) => (
            <strong className="font-semibold text-foreground">{children}</strong>
        ),
        em: ({ children }: MarkdownNodeProps) => <em className="italic">{children}</em>,
        // Internal (`/`-prefixed) links stay in the same tab; anything else is external and opens a
        // new tab. Reuses the `Typography` atom's `isLink` branch (HeroUI `Link` + a11y) rather than
        // hand-rolling an `<a>` — the atom already owns exactly this link skin everywhere else.
        a: ({ href, children }: MarkdownLinkProps) => {
            const isInternal = typeof href === "string" && href.startsWith("/")
            return (
                <Typography
                    size={linkSize}
                    isLink
                    href={href}
                    target={isInternal ? undefined : "_blank"}
                    rel={isInternal ? undefined : "noopener noreferrer"}
                    text={children}
                />
            )
        },
        blockquote: ({ children }: MarkdownNodeProps) => (
            <blockquote className={cn("border-l-2 border-default pl-3 text-muted", reading ? "my-4" : "my-3")}>{children}</blockquote>
        ),
        hr: () => <hr className={cn("border-default", reading ? "my-8" : "my-6")} />,
        // Markdown `![caption](src)`: a non-empty alt doubles as a real figure caption; an empty
        // alt renders a bare (decorative) image — same rule `src` uses.
        img: ({ src, alt }: MarkdownImageProps) => (
            alt ? (
                <figure className={blockMy}>
                    <img src={src} alt={alt} className="w-full rounded-2xl" />
                    <figcaption className="mt-2 text-center text-sm italic text-muted">{alt}</figcaption>
                </figure>
            ) : (
                <img src={src} alt="" className={cn("w-full rounded-2xl", blockMy)} />
            )
        ),
        // GFM table -> house `TableRoot` compound (see the file header on `MarkdownTableParts.tsx`
        // for why this is NOT the config-driven `composites/data/Table`). The block-rhythm margin
        // (COMPOSITE-4: `MarkdownTable` takes no `className`) is owned here, by the plain wrapping
        // `<div>` — margin is a seam between two blocks, not a prop of either one.
        table: ({ children }: MarkdownNodeProps) => (
            <div className={blockMy}>
                <MarkdownTable ariaLabel={TABLE_ARIA_LABEL}>{children}</MarkdownTable>
            </div>
        ),
        thead: MarkdownTableHead,
        tbody: MarkdownTableBody,
        tr: MarkdownTableRow,
        th: MarkdownTableColumn,
        td: MarkdownTableCell,
        // A fenced block's inner `code` carries `language-*`; anything else is inline.
        // react-markdown still passes `className`; rename to `fenceClass` at this boundary.
        code: ({ children, className }: MarkdownCodeRuntimeProps) => {
            const fenceClass = className
            if (fenceClass?.startsWith("language-")) {
                return children
            }
            return (
                // inset-exception: inline-code geometry, wider than tall by nature, not a surface inset
                // (same shape as `RichText`'s inline `<code>` — see `RichText.tsx`)
                <Box as="code" principle="control-pad" className="rounded-md bg-default px-1 py-0 font-mono text-sm text-foreground [overflow-wrap:anywhere]"
                    explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                    {children}
                </Box>
            )
        },
        // Fenced block dispatch: `mermaid` -> diagram, everything else -> Shiki.
        pre: ({ children }: MarkdownNodeProps) => {
            const child = React.Children.only(children) as React.ReactElement<MarkdownCodeRuntimeProps>
            const fenceClass = child.props.className
            const lang = /language-(\w+)/.exec(fenceClass ?? "")?.[1] ?? "text"
            const code = String(child.props.children ?? "").replace(/\n$/, "")
            // Block-rhythm margin (COMPOSITE-4: neither viewer takes `className`) owned by the
            // plain wrapping `<div>` — margin is a seam between two blocks, not either one's prop.
            if (lang.toLowerCase() === "mermaid") {
                return (
                    <div className={blockMy}>
                        <MermaidDiagram
                            code={code}
                            theme={isDark ? "dark" : "default"}
                            loadingLabel={MERMAID_LOADING_LABEL}
                            expandLabel={MERMAID_EXPAND_LABEL}
                            caption={mermaidCaptions[code.trim()]}
                            fallbackLabel={MERMAID_FALLBACK_LABEL}
                        />
                    </div>
                )
            }
            return (
                <div className={blockMy}>
                    <CodeToHtml
                        code={code}
                        language={lang}
                        theme={isDark ? "material-theme-darker" : "material-theme-lighter"}

                    />
                </div>
            )
        },
        // Custom `:::muted` directive tags (see `remarkMuted` in `MarkdownContent.tsx`): small,
        // muted label text. `[&_*]:text-muted` forces the muted colour onto any inner `<p>`.
        mutedblock: ({ children }: MarkdownNodeProps) => (
            <div className="text-sm font-semibold text-muted [&_*]:text-muted">{children}</div>
        ),
        mutedtext: ({ children }: MarkdownNodeProps) => (
            <span className="text-sm font-semibold text-muted">{children}</span>
        ),
        // Custom `:::chip` directive tag: a wrapped row of chips, one per authored keyword line.
        // Reuses the `Chip` ATOM (soft/neutral) rather than HeroUI `Chip` directly.
        chipblock: ({ items }: MarkdownChipBlockProps) => (
            <div className="my-2">
                <StackH
                    as="span"
                    at="sm"
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    items={String(items ?? "").split("|").filter(Boolean).map((keyword) => () => (
                        <Chip tone="default" text={keyword} />
                    ))}
                />
            </div>
        ),
        // :::tab -> [ Preview | Code ] tabs; code/preview panes carry `kind` so `TabsBlock` matches them.
        tabblock: ({ children }: MarkdownNodeProps) => <TabsBlock>{children}</TabsBlock>,
        tabcode: ({ children }: MarkdownNodeProps) => <TabPane kind="code">{children}</TabPane>,
        tabpreview: ({ children }: MarkdownNodeProps) => <TabPane kind="preview">{children}</TabPane>,
        // ::::accordion / :::panel{title} -> house `AccordionTree` compound (incremental panels from
        // react-markdown — not the data-driven Disclosure `Accordion` atom). `variant="default"`
        // keeps the item separator FULL-BLEED, with the light hairline `--separator` re-point so
        // dividers read the same as the `SurfaceListCard` family; `border` delineates it as a
        // nested surface.
        accordionblock: ({ children }: MarkdownNodeProps) => (
            // `AccordionTree` omits `className` (atom door is closed); border/rhythm sit on the
            // wrapping seam so COMPOSITE-4 stays clean while the nested-surface look is preserved.
            <div className={cn("overflow-hidden border border-default bg-surface", blockMy)}>
                <AccordionTree
                    variant="default"
                    separatorTone="subtle"
                >
                    {children}
                </AccordionTree>
            </div>
        ),
        accordionpanel: ({ title, children }: MarkdownPanelProps) => (
            <AccordionTreeItem aria-label={String(title ?? "")}>
                <AccordionTreeHeading>
                    <AccordionTreeTrigger>
                        <div className="text-start">
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                justify="between"
                                items={[
                                    () => <span className={reading ? "text-base font-semibold" : "text-sm font-semibold"}>{title}</span>,
                                    () => <AccordionTreeIndicator />,
                                ]}
                            />
                        </div>
                    </AccordionTreeTrigger>
                </AccordionTreeHeading>
                <AccordionTreePanel>
                    <AccordionTreeBody>
                        <div className="space-y-2">{children}</div>
                    </AccordionTreeBody>
                </AccordionTreePanel>
            </AccordionTreeItem>
        ),
    }
}

"use client"

import React, {
    useDeferredValue,
    useEffect,
    useLayoutEffect,
    useMemo,
    useRef,
    useState} from "react"
import { Document, Page, pdfjs } from "react-pdf"
import { cn } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import {
    resolvePDFViewHeight,
    type PDFViewHeight,
} from "@/components/composites/_semantic-contracts"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * STORYBOOK-LOCAL DESIGN SPEC — faithful port of
 * `@/components/blocks/rendering/PDFView` (+ its colocated `PdfViewportPage` and
 * `constants`, inlined here as sibling helpers). Authored in Storybook (not
 * `src`); synced back to `src` later.
 *
 * NOTE: like the real component, the pdf.js worker is loaded from the unpkg CDN
 * (below) and each rendered page needs a reachable PDF file — so the actual
 * canvas rendering requires NETWORK access in Storybook. The `Empty` story
 * (`src=""`) renders fully offline; the file-backed stories use a tiny inline
 * data-URI PDF and only paint when the worker CDN is reachable.
 * ─────────────────────────────────────────────────────────────────────────────
 */

pdfjs.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.mjs`

/** Fallback aspect ratio (height / width) for a page placeholder before its canvas mounts (A4-ish). */
const PAGE_ASPECT_FALLBACK = 1.414

/** Debounce window (ms) before reacting to container resize observations. */
const RESIZE_DEBOUNCE_MS = 120

/** How many placeholder pages the whole-file skeleton shows (no real page count yet). */
const SKELETON_PAGE_COUNT = 2

/** Props for {@link PdfViewportPage}. */
interface PdfViewportPageProps {
    /** 1-based page index. */
    pageNumber: number
    /** Scroll container ref used as the IntersectionObserver root. */
    scrollRootRef: React.RefObject<HTMLDivElement | null>
    /** Rendered page width (deferred during resize). */
    width: number
    /** When true, mount the canvas immediately (no IntersectionObserver). */
    eager: boolean
}

/**
 * Renders one PDF page once it nears the viewport to avoid painting every page at once.
 *
 * Presentational: uses only UI-local hooks (`useState`/`useRef`/`useEffect`) to lazily
 * mount the page canvas via an IntersectionObserver.
 * @param props - {@link PdfViewportPageProps}
 */
const PdfViewportPage = (props: PdfViewportPageProps) => {
    const {
        pageNumber,
        scrollRootRef,
        width,
        eager} = props
    const wrapRef = useRef<HTMLDivElement | null>(null)
    const [showCanvas, setShowCanvas] = useState(eager)
    const placeholderMinH = Math.max(
        160,
        Math.round(width * PAGE_ASPECT_FALLBACK))

    useEffect(() => {
        if (eager) {
            setShowCanvas(true)
            return
        }
        if (showCanvas) {
            return
        }
        const el = wrapRef.current
        if (!el) {
            return
        }
        const root = scrollRootRef.current ?? undefined
        const io = new IntersectionObserver(
            (entries) => {
                const entry = entries[0]
                if (entry?.isIntersecting) {
                    setShowCanvas(true)
                }
            },
            {
                root,
                rootMargin: "100% 0px 120% 0px",
                threshold: 0.01})
        io.observe(el)
        return () => io.disconnect()
    }, [
        eager,
        scrollRootRef,
        showCanvas,
        pageNumber])

    return (
        <div
            ref={wrapRef}
            className="flex justify-center"
        >
            {
                showCanvas ? (
                    <Page
                        pageNumber={pageNumber}
                        width={width}
                        renderTextLayer={false}
                        renderAnnotationLayer={false}
                    />
                ) : (
                    // Not scrolled into view yet — a real bordered page-shaped frame (not a
                    // drawn shimmer rectangle); the two lines inside are the only shimmer,
                    // and `Typography` draws its own shape (COMPOSITE-10).
                    <Box
                        principle="title-subtitle" className="flex w-full max-w-full flex-col items-center justify-center gap-2 rounded-medium border border-default"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        style={{ minHeight: placeholderMinH }}
                        aria-hidden
                    >
                        <Typography size="sm" color="muted" isSkeleton />
                        <Typography size="xs" color="muted" isSkeleton />
                    </Box>
                )
            }
        </div>
    )
}

interface PDFViewOwnProps {
    /**
     * Named viewer height. Prefer this over raw height class escapes.
     * @default "document"
     */
    height?: PDFViewHeight
    /** Optional page width for PDF rendering. */
    pageWidth?: number
    /** Render all pages or only first page. */
    showAllPages?: boolean
    /** Allow vertical scroll in viewer container. */
    allowVerticalScroll?: boolean
    /** Auto fit rendered PDF width to container width. */
    fitToContainer?: boolean
    /**
     * `true` → no `Document` mounted at all, the whole file hasn't arrived yet
     * (distinct from the per-page placeholder `PdfViewportPage` already draws for
     * a page that just hasn't scrolled into view).
     */
    isSkeleton?: boolean
}

/**
 * Props for {@link PDFView}. `src`/`title` are REQUIRED unless `isSkeleton`
 * (§12b) — a shimmer viewer has no real file to preview yet.
 */
export type PDFViewProps = PDFViewOwnProps &
    (
        | { isSkeleton: true; src?: string; title?: string }
        | {
            isSkeleton?: false
            /** Source URL of the PDF file to preview. */
            src: string
            /** Accessible title for the iframe viewer. */
            title: string
        }
    )

export type { PDFViewHeight }

/**
 * Reusable PDF preview viewer built on react-pdf.
 *
 * Presentational: uses only UI-local hooks (refs, resize/layout effects, deferred width)
 * to size pages to the container; no business logic. Marked `"use client"` for the DOM
 * observers and react-pdf canvas rendering.
 * @param props - {@link PDFViewProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "PDFView" } as const

/** A reusable, presentational PDF preview viewer built on react-pdf. */
export const PDFView = ({
    src,
    title,
    height = "document",
    pageWidth = 840,
    showAllPages = true,
    allowVerticalScroll = false,
    fitToContainer = false,
    isSkeleton = false,
}: PDFViewProps) => {
    const file = useMemo(() => (src ? src : undefined), [src])
    const [numPages, setNumPages] = useState(0)
    const containerRef = useRef<HTMLDivElement | null>(null)
    const scrollRootRef = useRef<HTMLDivElement | null>(null)
    const [containerWidth, setContainerWidth] = useState(0)
    const computedPageWidth = fitToContainer && containerWidth > 0
        ? Math.max(320, Math.floor(containerWidth) - 24)
        : pageWidth
    const deferredPageWidth = useDeferredValue(computedPageWidth)
    const renderWidth = deferredPageWidth > 0 ? deferredPageWidth : computedPageWidth

    const assignContainerRef = (node: HTMLDivElement | null) => {
        containerRef.current = node
        scrollRootRef.current = node
    }

    useLayoutEffect(() => {
        if (!fitToContainer) {
            return
        }
        const el = containerRef.current
        if (!el) {
            return
        }
        const w = Math.floor(el.getBoundingClientRect().width)
        if (w > 0) {
            setContainerWidth(w)
        }
    }, [
        fitToContainer,
        src,
        height])

    useEffect(() => {
        if (!fitToContainer) {
            return
        }
        const element = containerRef.current
        if (!element) {
            return
        }
        let timeoutId: NodeJS.Timeout | undefined
        const observer = new ResizeObserver((entries) => {
            const nextWidth = Math.floor(entries[0]?.contentRect.width ?? 0)
            clearTimeout(timeoutId)
            timeoutId = setTimeout(
                () => {
                    setContainerWidth(nextWidth)
                }, RESIZE_DEBOUNCE_MS
            )
        })
        observer.observe(element)
        return () => {
            clearTimeout(timeoutId)
            observer.disconnect()
        }
    }, [
        fitToContainer,
        src])

    const pageCount = showAllPages ? numPages : Math.min(1, numPages)

    // The frame stays real throughout (COMPOSITE-10) — same height/scroll footprint
    // whether or not the file has arrived.
    return (
        <div
            ref={assignContainerRef}
            className={cn(
                resolvePDFViewHeight(height),
                "overflow-x-auto bg-surface scrollbar-thin scrollbar-thumb-accent scrollbar-track-surface-secondary",
                allowVerticalScroll ? "overflow-y-auto" : "overflow-y-hidden",
            )}
            data-tier="composite"
            data-component="PDFView"
        >
            {isSkeleton ? (
                // No real page count exists before the file arrives — the composite still
                // decides WHICH parts shimmer and HOW MANY: a small stack of the SAME
                // bordered page frame `PdfViewportPage` draws for a page not yet scrolled
                // into view, each one handed `isSkeleton` `Typography` lines.
                <StackV
                    gap={4}
                    items={Array.from({ length: SKELETON_PAGE_COUNT }, () => () => (
                        <Box
                            principle="title-subtitle" className="flex w-full flex-col items-center justify-center gap-2 rounded-medium border border-default"
                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                            style={{ minHeight: 320 }}
                            aria-hidden
                        >
                            <Typography size="sm" color="muted" isSkeleton />
                            <Typography size="xs" color="muted" isSkeleton />
                        </Box>
                    ))}
                />
            ) : file ? (
                <Document
                    key={src}
                    file={file}
                    loading={<div className="text-sm text-muted">{title}</div>}
                    error={<div className="text-sm text-danger-soft-foreground">Failed to render PDF.</div>}
                    noData={<div className="text-sm text-muted">No PDF selected.</div>}
                    onLoadSuccess={(pdf) => setNumPages(pdf.numPages)}
                >
                    <StackV
                        gap={4}
                        items={Array.from({ length: pageCount }, (_, index) => {
                            const pageNumber = index + 1
                            const eager = !showAllPages || pageNumber <= 2
                            return () => (
                                <PdfViewportPage
                                    eager={eager}
                                    pageNumber={pageNumber}
                                    scrollRootRef={scrollRootRef}
                                    width={renderWidth}
                                />
                            )
                        })}
                    />
                </Document>
            ) : (
                <div className="text-sm text-muted">No PDF selected.</div>
            )}
        </div>
    )
}
